package com.ironwise;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Outlines the Bring list in the bank (new in 0.5.0), like RuneLite's inventory tags: the run in progress's, or, before
 * a run starts, the run picked in the side panel (Ironwise sends each listed run's ids). Only draws: nothing is
 * withdrawn or clicked. The ids are worked out once per answer or pick (FarmRunState#bankIds), not per item per frame.
 */
class BankHighlightOverlay extends WidgetItemOverlay
{
	private static final Color OUTLINE = new Color(75, 139, 255);

	private final ItemManager itemManager;
	private final IronwiseConfig config;
	private final FarmRunState state;

	@Inject
	BankHighlightOverlay(ItemManager itemManager, IronwiseConfig config, FarmRunState state)
	{
		this.itemManager = itemManager;
		this.config = config;
		this.state = state;
		showOnBank();
	}

	/** Every item id on the run's Bring list (any of each row's ids counts). */
	static Set<Integer> ids(FarmRuns.Active run)
	{
		Set<Integer> out = new HashSet<>();
		if (run == null)
		{
			return out;
		}
		for (FarmRuns.BringItem b : run.bring)
		{
			for (int id : b.itemIds)
			{
				out.add(id);
			}
		}
		return out;
	}

	/**
	 * What to outline: the Bring list of the run in progress; once it's finished, or with none on, the picked run's
	 * (its bringItemIds); otherwise nothing.
	 */
	static Set<Integer> ids(FarmRuns runs, String picked)
	{
		if (runs == null)
		{
			return new HashSet<>();
		}
		if (runs.active != null && !runs.active.finished)
		{
			return ids(runs.active);
		}
		Set<Integer> out = new HashSet<>();
		FarmRuns.Preset p = picked == null ? null : runs.preset(picked);
		if (p != null)
		{
			for (int id : p.bringItemIds)
			{
				out.add(id);
			}
		}
		return out;
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.syncEnabled() || !config.farmRuns() || !config.farmRunBankHighlight() || !state.bankIds().contains(itemId))
		{
			return;
		}
		Rectangle bounds = widgetItem.getCanvasBounds();
		BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), OUTLINE);
		graphics.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
	}
}

package com.ironwise;

import java.util.Collection;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * Watches every stop of the current stop's cluster that isn't done (new in 0.5.0): a player may deal with a cluster's
 * patches in any order, and with the next one before Ironwise has answered for the last, so each stop has its own
 * {@link StopWatcher}, kept while its cluster is the current one (no new settle ticks when the run moves on inside it).
 * A stop seen dealt with waits in a queue, first seen first, until Ironwise has it. Pure: the controller feeds it the
 * view, the player's position and each stop's value.
 */
final class ClusterWatch
{
	private final Map<String, StopWatcher> watchers = new LinkedHashMap<>();
	private final Set<String> pending = new LinkedHashSet<>();
	private String cluster;
	private String current;

	/** Follows a new view: watches the current stop and its cluster's stops still to do, and forgets the rest. */
	void update(FarmRuns runs)
	{
		FarmRuns.Active a = runs == null ? null : runs.active;
		FarmRuns.Stop now = a == null || a.finished ? null : a.current();
		if (now == null)
		{
			clear();
			return;
		}
		if (!Objects.equals(now.cluster, cluster))
		{
			watchers.clear();
			cluster = now.cluster;
		}
		current = now.patchId;
		Set<String> open = new HashSet<>();
		for (FarmRuns.Stop s : a.openInCluster())
		{
			open.add(s.patchId);
			if (s.watch != null && !watchers.containsKey(s.patchId))
			{
				watchers.put(s.patchId, new StopWatcher(s, runs.tables));
			}
		}
		watchers.keySet().retainAll(open);
		pending.retainAll(open);
	}

	/** Every watcher settles again (a hop, a loading screen, the welcome screen). */
	void reset()
	{
		for (StopWatcher w : watchers.values())
		{
			w.reset();
		}
	}

	void clear()
	{
		watchers.clear();
		pending.clear();
		cluster = null;
		current = null;
	}

	Collection<StopWatcher> watchers()
	{
		return watchers.values();
	}

	/** One tick for one watcher; a stop seen dealt with is queued for Ironwise. */
	void tick(StopWatcher w, int x, int y, int plane, int regionId, int value)
	{
		if (w.tick(x, y, plane, regionId, value) == StopWatcher.Event.DONE)
		{
			pending.add(w.patchId());
		}
	}

	/** The next stop to tell Ironwise is dealt with (the first seen), or null. */
	String next()
	{
		return pending.isEmpty() ? null : pending.iterator().next();
	}

	/** Ironwise has it (or refused it as stale): don't send it again. */
	void sent(String patchId)
	{
		pending.remove(patchId);
	}

	/** The current stop's line for the run box, or null. */
	String hint()
	{
		StopWatcher w = current == null ? null : watchers.get(current);
		return w == null ? null : w.hint();
	}
}

package com.ironwise;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.ScriptEvent;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.RuneScapeProfileType;

/**
 * Reads the player's own collection log while they look at it, only when they've asked for it: the
 * Sync collection log setting (off by default), while Sync with Ironwise is ticked. Otherwise nothing
 * about the log is read, and anything read earlier this session is dropped so it's never sent. It only
 * watches what the game draws: no clicks, no menu actions, no scripts run, nothing added to the log's
 * interface. Everything here runs on the client thread.
 *
 * Two ways the game shows the log:
 * - A page (e.g. "Vorkath"): its name, "Obtained: x/y" and kill count lines in the heading
 *   (InterfaceID.Collection.HEADER_TEXT), and one item graphic per log slot in ITEMS_CONTENTS, drawn
 *   see-through unless obtained (clientscript proc collection_draw_log, 2732).
 * - The log's own Search: the server sends every obtained item through clientscript 4100,
 *   collection_delayed_transmit(obj, count, int, struct), one call per item. WikiSync (weirdgloop/WikiSync
 *   1ff4ea0, BSD-2) reads the item from argument 1, and RuneProfile (ReinhardtR/runeprofile-plugin 7c6ef18)
 *   and Temple OSRS (SMaloney2017/Temple-OSRS-Plugin d5de3a3) read the item and count from arguments 1
 *   and 2 (argument 0 is the script id). Script names and signatures: Joshua-F/cs2-scripts.
 */
@Singleton
class CollectionLogReader
{
	/** Clientscript collection_delayed_transmit: one call per obtained item while the log's Search lists them. */
	static final int COLLECTION_DELAYED_TRANSMIT = 4100;
	/**
	 * Enum log item → the version the log shows for the other body type, used when
	 * COLLECTION_PLAYER_BODYTYPE is 1 (collection_draw_log and collection_search_display_item). Ironwise
	 * turns them back into the log's own item ids.
	 */
	private static final int BODY_TYPE_ITEMS_ENUM = 2108;
	/**
	 * A search listing is finished once no item has arrived for this many ticks (large logs arrive over
	 * a few ticks: Temple OSRS waits 3 ticks, WikiSync 2).
	 */
	private static final int SEARCH_SETTLE_TICKS = 3;

	private final Client client;
	private final CollectionLogState state;
	private final IronwiseConfig config;

	/** Items from a search listing still arriving, or null. */
	private Map<Integer, Integer> listing;
	private int lastItemTick;
	/** How many items the last finished listing had, until the plugin has said so in chat. */
	private int finishedListing = -1;
	/** The page on screen last tick: a page only counts once it reads the same twice in a row. */
	private Page lastPage;
	private Map<Integer, Integer> bodyTypeItems;

	/** A page as drawn. */
	private static final class Page
	{
		final String name;
		final Map<String, Integer> kc;
		final List<Integer> shown;
		final Map<Integer, Integer> obtained;

		Page(String name, Map<String, Integer> kc, List<Integer> shown, Map<Integer, Integer> obtained)
		{
			this.name = name;
			this.kc = kc;
			this.shown = shown;
			this.obtained = obtained;
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof Page))
			{
				return false;
			}
			Page p = (Page) o;
			return name.equals(p.name) && kc.equals(p.kc) && shown.equals(p.shown) && obtained.equals(p.obtained);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(name, kc, shown, obtained);
		}
	}

	@Inject
	CollectionLogReader(Client client, CollectionLogState state, IronwiseConfig config)
	{
		this.client = client;
		this.state = state;
		this.config = config;
	}

	/** Logged out, hopping or a new account: drop anything half-read. */
	void reset()
	{
		listing = null;
		lastPage = null;
		finishedListing = -1;
	}

	/** The player has ticked Sync collection log, and Sync with Ironwise (the log is only read to be sent). */
	private boolean wanted()
	{
		return config.syncEnabled() && config.syncCollectionLog();
	}

	/**
	 * Whether the log may be read now, checked before every read. If not, everything read of it this
	 * session, half-read or not, is dropped at once. The plugin runs {@link #onGameTick} before it builds
	 * each sync, so once the setting is unticked no sync has a collection log section (Ironwise keeps
	 * what it had, as for a player who never opened the log).
	 */
	private boolean reading()
	{
		if (wanted())
		{
			return true;
		}
		reset();
		state.reset();
		return false;
	}

	void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != COLLECTION_DELAYED_TRANSMIT || !reading() || !ownLog())
		{
			return;
		}
		ScriptEvent script = event.getScriptEvent();
		Object[] args = script == null ? null : script.getArguments();
		if (args == null || args.length < 3 || !(args[1] instanceof Integer) || !(args[2] instanceof Integer))
		{
			return;
		}
		int id = logItemId((Integer) args[1]);
		int count = (Integer) args[2];
		if (listing == null)
		{
			listing = new HashMap<>();
		}
		lastItemTick = client.getTickCount();
		if (id > 0 && count > 0)
		{
			listing.merge(id, count, Math::max);
		}
	}

	/** A "New item added to your collection log" chat line; true if it's new. */
	boolean onChatMessage(ChatMessage message, long now)
	{
		if (message.getType() != ChatMessageType.GAMEMESSAGE || !reading() || !standardWorld())
		{
			return false;
		}
		String name = CollectionLogState.addedItemName(message.getMessage());
		return name != null && state.added(name, now);
	}

	/** Finishes a search listing and reads the page on screen; true if anything new was recorded. */
	boolean onGameTick(long now)
	{
		if (!reading())
		{
			return false;
		}
		boolean changed = false;
		if (listing != null && client.getTickCount() - lastItemTick >= SEARCH_SETTLE_TICKS)
		{
			Map<Integer, Integer> items = listing;
			listing = null;
			if (ownLog() && state.searchSeen(items, now))
			{
				changed = true;
				finishedListing = items.size();
			}
		}
		Page page = pageOnScreen();
		if (page != null && page.equals(lastPage))
		{
			changed |= state.pageSeen(page.name, page.kc, page.shown, page.obtained, now);
		}
		lastPage = page;
		return changed;
	}

	/** How many items the last search listing had, once; -1 if there's been none since. */
	int takeFinishedListing()
	{
		int n = finishedListing;
		finishedListing = -1;
		return n;
	}

	/** The collection log page on screen, or null if there isn't one (or it doesn't add up). */
	private Page pageOnScreen()
	{
		Widget heading = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
		Widget slots = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
		if (heading == null || slots == null || heading.isHidden() || slots.isHidden() || !ownLog())
		{
			return null;
		}
		Widget search = client.getWidget(InterfaceID.Collection.CONTENT_SEARCH);
		if (search != null && !search.isHidden())
		{
			return null;
		}
		Widget[] lines = heading.getDynamicChildren();
		if (lines == null || lines.length < 2)
		{
			return null;
		}
		String name = CollectionLogState.pageName(lines[0].getText());
		if (name == null)
		{
			return null;
		}
		int[] counts = null;
		Map<String, Integer> kc = new LinkedHashMap<>();
		for (int i = 1; i < lines.length; i++)
		{
			String text = lines[i].getText();
			int[] obtainedLine = CollectionLogState.obtainedLine(text);
			if (obtainedLine != null)
			{
				counts = obtainedLine;
				continue;
			}
			Map.Entry<String, Integer> line = CollectionLogState.kcLine(text);
			if (line != null)
			{
				kc.put(line.getKey(), line.getValue());
			}
		}
		if (counts == null)
		{
			return null;
		}
		List<Integer> shown = new ArrayList<>();
		Map<Integer, Integer> obtained = new HashMap<>();
		Widget[] items = slots.getDynamicChildren();
		for (Widget slot : items == null ? new Widget[0] : items)
		{
			int id = slot.getItemId();
			if (id <= 0)
			{
				continue;
			}
			id = logItemId(id);
			shown.add(id);
			// Obtained slots are drawn solid, the rest see-through.
			if (slot.getOpacity() == 0 && slot.getItemQuantity() > 0)
			{
				obtained.merge(id, slot.getItemQuantity(), Math::max);
			}
		}
		// Only trust a page whose slots match its own "Obtained: x/y" line.
		if (shown.size() != counts[1] || obtained.size() != counts[0])
		{
			return null;
		}
		return new Page(name, kc, shown, obtained);
	}

	/** Not another player's log (the house's adventure log opens theirs), and not Leagues, Deadman or beta. */
	private boolean ownLog()
	{
		return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) != 1 && standardWorld();
	}

	private boolean standardWorld()
	{
		return RuneScapeProfileType.getCurrent(client) == RuneScapeProfileType.STANDARD;
	}

	/** The log's own item id for an item it may show as its other-body-type version. */
	private int logItemId(int id)
	{
		if (client.getVarbitValue(VarbitID.COLLECTION_PLAYER_BODYTYPE) != 1)
		{
			return id;
		}
		if (bodyTypeItems == null)
		{
			bodyTypeItems = new HashMap<>();
			EnumComposition e = client.getEnum(BODY_TYPE_ITEMS_ENUM);
			if (e != null)
			{
				int[] keys = e.getKeys();
				int[] values = e.getIntVals();
				for (int i = 0; i < Math.min(keys.length, values.length); i++)
				{
					bodyTypeItems.put(values[i], keys[i]);
				}
			}
			bodyTypeItems = Collections.unmodifiableMap(bodyTypeItems);
		}
		return bodyTypeItems.getOrDefault(id, id);
	}
}

package com.ironwise;

import java.util.AbstractMap;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Singleton;
import net.runelite.client.util.Text;

/**
 * What Ironwise has seen of the player's collection log this session, and how it goes into a sync.
 * It doesn't touch the game (CollectionLogReader does), so it can be unit tested.
 *
 * Collection log counts never go down, so a new reading of something already seen keeps the larger
 * count. That also stops a page drawn before the game sent its items (it shows 0) from undoing a good
 * reading.
 */
@Singleton
class CollectionLogState
{
	/** Caps, matched by the app's checks. */
	static final int MAX_ITEMS = 3000;
	static final int MAX_PAGES = 200;
	static final int MAX_ADDED = 100;
	static final int MAX_KC_LINES = 5;
	static final int MAX_NAME = 60;

	private static final Pattern ADDED = Pattern.compile("^New item added to your collection log: (.+)$");
	/** "Vorkath kills: 1,234" (a page's kill count lines, after removing colour tags). */
	private static final Pattern KC = Pattern.compile("^(.+?):\\s*([0-9][0-9,]*)$");
	/** "Obtained: 3/12" (the line under a page's name). */
	private static final Pattern OBTAINED = Pattern.compile("^Obtained:\\s*([0-9]+)/([0-9]+)$");

	/** A search listing: every obtained item in the log, or null until the player has searched this session. */
	private TreeMap<Integer, Integer> all;
	private long allSeenAt;
	/** Page name → the page as viewed, in the order first seen. */
	private final Map<String, Page> pages = new LinkedHashMap<>();
	/** "New item added" chat lines not yet carried by a sync that got through. */
	private final List<Added> added = new ArrayList<>();

	private static final class Page
	{
		long seenAt;
		final Map<String, Integer> kc = new LinkedHashMap<>();
		final TreeMap<Integer, Integer> items = new TreeMap<>();

		Page(long seenAt)
		{
			this.seenAt = seenAt;
		}
	}

	private static final class Added
	{
		final String name;
		final long at;

		Added(String name, long at)
		{
			this.name = name;
			this.at = at;
		}
	}

	/** A new account (or the plugin restarting): forget everything. */
	void reset()
	{
		all = null;
		allSeenAt = 0;
		pages.clear();
		added.clear();
	}

	/**
	 * A finished search listing (item id → count). The listing covers the whole log, so it's recorded
	 * as seen now even when nothing changed. False if it's too big to send.
	 */
	boolean searchSeen(Map<Integer, Integer> items, long now)
	{
		if (items.size() > MAX_ITEMS)
		{
			return false;
		}
		if (all == null)
		{
			all = new TreeMap<>();
		}
		mergeMax(all, items);
		allSeenAt = now;
		return true;
	}

	/**
	 * A page as viewed: its name, kill count lines, the item ids it shows and the ones drawn as
	 * obtained (id → count). An item a search listing earlier this session had counts too. True if
	 * the page is new or something on it went up.
	 */
	boolean pageSeen(String name, Map<String, Integer> kc, Collection<Integer> shown, Map<Integer, Integer> obtained, long now)
	{
		Map<Integer, Integer> items = new TreeMap<>(obtained);
		if (all != null)
		{
			for (int id : shown)
			{
				Integer n = all.get(id);
				if (n != null)
				{
					items.merge(id, n, Math::max);
				}
			}
		}
		if (items.size() > MAX_ITEMS)
		{
			return false;
		}
		Page page = pages.get(name);
		boolean isNew = page == null;
		if (isNew)
		{
			if (pages.size() >= MAX_PAGES)
			{
				evictOldestPage();
			}
			page = new Page(now);
			pages.put(name, page);
		}
		boolean changed = mergeMax(page.items, items);
		for (Map.Entry<String, Integer> line : kc.entrySet())
		{
			Integer old = page.kc.get(line.getKey());
			if (line.getValue() <= 0 || (old == null && page.kc.size() >= MAX_KC_LINES))
			{
				continue;
			}
			if (old == null || line.getValue() > old)
			{
				page.kc.put(line.getKey(), line.getValue());
				changed = true;
			}
		}
		if (changed)
		{
			page.seenAt = now;
		}
		return isNew || changed;
	}

	/** A "New item added to your collection log" line. False if that item is already waiting to be sent. */
	boolean added(String name, long at)
	{
		for (Added a : added)
		{
			if (a.name.equals(name))
			{
				return false;
			}
		}
		if (added.size() >= MAX_ADDED)
		{
			added.remove(0);
		}
		added.add(new Added(name, at));
		return true;
	}

	/** A sync carrying these "added" entries got through: drop them (ones that arrived since stay). */
	void addedSent(List<Object[]> sent)
	{
		if (sent == null)
		{
			return;
		}
		for (Object[] s : sent)
		{
			added.removeIf(a -> a.name.equals(s[0]) && Long.valueOf(a.at).equals(s[1]));
		}
	}

	/** The section for a sync, or null while nothing is known. */
	SyncPayload.CollectionLog toPayload()
	{
		if (all == null && pages.isEmpty() && added.isEmpty())
		{
			return null;
		}
		SyncPayload.ClogSnapshot snapshot = all == null ? null : new SyncPayload.ClogSnapshot(allSeenAt, pairs(all));
		Map<String, SyncPayload.ClogPage> pageOut = new LinkedHashMap<>();
		for (Map.Entry<String, Page> e : pages.entrySet())
		{
			Page p = e.getValue();
			List<Object[]> kc = new ArrayList<>();
			for (Map.Entry<String, Integer> line : p.kc.entrySet())
			{
				kc.add(new Object[]{line.getKey(), line.getValue()});
			}
			pageOut.put(e.getKey(), new SyncPayload.ClogPage(p.seenAt, kc, pairs(p.items)));
		}
		List<Object[]> addedOut = new ArrayList<>();
		for (Added a : added)
		{
			addedOut.add(new Object[]{a.name, a.at});
		}
		return new SyncPayload.CollectionLog(snapshot, pageOut, addedOut);
	}

	private void evictOldestPage()
	{
		String oldest = null;
		long oldestAt = Long.MAX_VALUE;
		for (Map.Entry<String, Page> e : pages.entrySet())
		{
			if (e.getValue().seenAt < oldestAt)
			{
				oldest = e.getKey();
				oldestAt = e.getValue().seenAt;
			}
		}
		pages.remove(oldest);
	}

	/** Adds each positive count, keeping the larger one; true if anything was added or went up. */
	private static boolean mergeMax(Map<Integer, Integer> into, Map<Integer, Integer> from)
	{
		boolean changed = false;
		for (Map.Entry<Integer, Integer> e : from.entrySet())
		{
			int id = e.getKey();
			int qty = e.getValue();
			if (id <= 0 || qty <= 0)
			{
				continue;
			}
			Integer old = into.get(id);
			if (old == null && into.size() >= MAX_ITEMS)
			{
				continue;
			}
			if (old == null || qty > old)
			{
				into.put(id, qty);
				changed = true;
			}
		}
		return changed;
	}

	private static List<int[]> pairs(Map<Integer, Integer> items)
	{
		List<int[]> out = new ArrayList<>(items.size());
		for (Map.Entry<Integer, Integer> e : items.entrySet())
		{
			out.add(new int[]{e.getKey(), e.getValue()});
		}
		return out;
	}

	/** Game text without colour tags and with ordinary spaces. */
	static String plain(String text)
	{
		return text == null ? "" : Text.removeTags(text).replace('\u00A0', ' ').trim();
	}

	/** The item named in a "New item added to your collection log: …" chat line, or null. */
	static String addedItemName(String message)
	{
		Matcher m = ADDED.matcher(plain(message));
		if (!m.matches())
		{
			return null;
		}
		String name = m.group(1).trim();
		return name.isEmpty() || name.length() > MAX_NAME ? null : name;
	}

	/** A page's name from its heading, or null if it's empty or too long. */
	static String pageName(String heading)
	{
		String name = plain(heading);
		return name.isEmpty() || name.length() > MAX_NAME ? null : name;
	}

	/**
	 * A kill count line ("Vorkath kills: 1,234") as its label and count, or null if it isn't one. A count
	 * of 0 is left out: it says nothing the app needs, and every number Ironwise sends is then positive.
	 */
	static Map.Entry<String, Integer> kcLine(String text)
	{
		Matcher m = KC.matcher(plain(text));
		if (!m.matches())
		{
			return null;
		}
		String label = m.group(1).trim();
		String digits = m.group(2).replace(",", "");
		if (label.isEmpty() || label.length() > MAX_NAME || label.equalsIgnoreCase("Obtained") || digits.length() > 10)
		{
			return null;
		}
		long n = Long.parseLong(digits);
		if (n <= 0 || n > Integer.MAX_VALUE)
		{
			return null;
		}
		return new AbstractMap.SimpleImmutableEntry<>(label, (int) n);
	}

	/** The "Obtained: 3/12" line as {obtained, total}, or null if it isn't that line. */
	static int[] obtainedLine(String text)
	{
		Matcher m = OBTAINED.matcher(plain(text));
		if (!m.matches() || m.group(1).length() > 6 || m.group(2).length() > 6)
		{
			return null;
		}
		return new int[]{Integer.parseInt(m.group(1)), Integer.parseInt(m.group(2))};
	}
}

package com.ironwise;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.Text;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Ironwise's /api/plugin/runs (new in 0.5.0): GET the account's farm runs (with the last ETag, so an unchanged answer
 * is a 304) and POST start, advance, skip, previous or end. On OkHttp's thread pool, with the sync's client and token;
 * redirects aren't followed, so the token only goes to the address the player set. Ironwise only lets the device that
 * synced an account read or change its runs (the account's owner: a group member sees them on the website only).
 */
@Singleton
class FarmRunClient
{
	static final String PATH = "/api/plugin/runs";
	static final String START = "start";
	static final String ADVANCE = "advance";
	static final String SKIP = "skip";
	static final String PREVIOUS = "previous";
	static final String END = "end";
	static final String NO_RUNS = "this Ironwise app can't do farm runs yet.";
	/** The address isn't one the plugin sends to (as the sync says in chat). */
	static final String BAD_ADDRESS = "set your Ironwise address in the plugin settings (it must start with https://).";
	/** A click while the last change is still on its way to Ironwise. */
	static final String BUSY = "the last change is still on its way to Ironwise. Try again in a moment.";

	enum Outcome
	{
		OK,
		NOT_MODIFIED,
		FAILED,
	}

	static final class Result
	{
		final Outcome outcome;
		/** The new view (OK only). */
		final FarmRuns runs;
		final String etag;
		/** Why it didn't work (FAILED only), reading on after "couldn't …: ". */
		final String message;

		Result(Outcome outcome, FarmRuns runs, String etag, String message)
		{
			this.outcome = outcome;
			this.runs = runs;
			this.etag = etag;
			this.message = message;
		}

		static Result failed(String message)
		{
			return new Result(Outcome.FAILED, null, null, message);
		}
	}

	interface Listener
	{
		void done(Result result);
	}

	private final SyncClient syncClient;
	private final Gson gson;

	@Inject
	FarmRunClient(SyncClient syncClient, Gson gson)
	{
		this.syncClient = syncClient;
		this.gson = gson;
	}

	static HttpUrl getUrl(String address, String accountHash)
	{
		HttpUrl url = SyncClient.appUrl(address, PATH);
		return url == null ? null : url.newBuilder().addQueryParameter("accountHash", accountHash).build();
	}

	static HttpUrl postUrl(String address)
	{
		return SyncClient.appUrl(address, PATH);
	}

	/**
	 * The chat line for a click that didn't work. The server's words are shown as text: the chat box would read
	 * {@code <col=…>} or {@code <img=…>} in them as tags.
	 */
	static String couldnt(String what, String message)
	{
		return "Ironwise: couldn't " + what + ": " + Text.escapeJagex(message);
	}

	/** {accountHash, action, presetId?, stop?}; the hash is a string, as in syncs. */
	String body(String accountHash, String action, String presetId, String stop)
	{
		JsonObject o = new JsonObject();
		o.addProperty("accountHash", accountHash);
		o.addProperty("action", action);
		if (presetId != null)
		{
			o.addProperty("presetId", presetId);
		}
		if (stop != null)
		{
			o.addProperty("stop", stop);
		}
		return gson.toJson(o);
	}

	void get(HttpUrl url, String token, String etag, Listener listener)
	{
		Request.Builder b = new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + token)
			.header("User-Agent", "Ironwise-RuneLite/" + IronwisePlugin.VERSION);
		if (etag != null)
		{
			b.header("If-None-Match", etag);
		}
		enqueue(b.get().build(), listener);
	}

	void post(HttpUrl url, String token, String json, Listener listener)
	{
		enqueue(SyncClient.post(url, token, json), listener);
	}

	private void enqueue(Request request, Listener listener)
	{
		syncClient.http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				listener.done(Result.failed("can't reach the app (" + e.getMessage() + ")"));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				Result r;
				try
				{
					r = result(response.code(), SyncClient.bodyOf(response), response.header("ETag"));
				}
				catch (IOException e)
				{
					r = Result.failed("couldn't read the app's answer (" + e.getMessage() + ")");
				}
				catch (RuntimeException e)
				{
					r = Result.failed("unexpected answer from the app");
				}
				finally
				{
					response.close();
				}
				listener.done(r);
			}
		});
	}

	Result result(int code, String body, String etag)
	{
		if (code == 304)
		{
			return new Result(Outcome.NOT_MODIFIED, null, etag, null);
		}
		JsonObject answer = ironwise(body);
		if (code >= 200 && code < 300)
		{
			FarmRuns runs = answer == null ? null : FarmRuns.parse(answer);
			return runs == null ? Result.failed(SyncClient.NOT_IRONWISE) : new Result(Outcome.OK, runs, etag, null);
		}
		if (code >= 300 && code < 400)
		{
			return Result.failed("that address redirects somewhere else. Use the app's main address.");
		}
		String message = messageOf(answer);
		if (message != null)
		{
			return Result.failed(message);
		}
		if (code == 404)
		{
			return Result.failed(NO_RUNS);
		}
		if (code == 401 || code == 403)
		{
			return Result.failed(answer == null ? SyncClient.LOGIN : SyncClient.BAD_TOKEN);
		}
		return Result.failed("the app answered " + code);
	}

	/** Ironwise's JSON answer ({"ok": ...}), or null if the body is something else. */
	private JsonObject ironwise(String body)
	{
		try
		{
			JsonObject o = gson.fromJson(body, JsonObject.class);
			JsonElement ok = o == null ? null : o.get("ok");
			return ok != null && ok.isJsonPrimitive() && ok.getAsJsonPrimitive().isBoolean() ? o : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static String messageOf(JsonObject answer)
	{
		JsonElement m = answer == null ? null : answer.get("message");
		if (m == null || !m.isJsonPrimitive() || !m.getAsJsonPrimitive().isString())
		{
			return null;
		}
		String s = NextStep.clean(m.getAsString(), 200);
		return s.isEmpty() ? null : s;
	}
}

package com.ironwise;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WidgetNode;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import okhttp3.HttpUrl;

/**
 * Farm runs in the game (new in 0.5.0): polls Ironwise every 10 s while logged in, watches every stop of the current
 * stop's cluster that isn't done (ClusterWatch), reading only when RuneLite's Time Tracking would (TickGate), and tells
 * Ironwise each stop it sees dealt with (none of it while syncing is stopped on a problem only the player can fix: then
 * nothing goes to Ironwise until the settings change); points Shortest Path at the current stop; keeps the side panel
 * (and its sidebar button, there while Sync with Ironwise and Farm runs are ticked) up to date; and sends the player's
 * clicks (Start, Skip stop, Previous stop, End run), each naming the stop the box shows. It only reads the game and
 * draws: nothing here clicks, moves or types for the player. Everything runs on the client thread except the HTTP
 * calls, whose answers come back to it, and the panel, which is laid out on the Swing thread.
 */
@Singleton
class FarmRunController
{
	/** A stop seen dealt with that didn't reach Ironwise: try again after this long (a poll's pace). */
	private static final long RETRY_MS = FarmRunState.POLL_MS;

	private final Client client;
	private final ClientThread clientThread;
	private final IronwiseConfig config;
	private final ConfigManager configManager;
	private final FarmRunClient http;
	private final FarmRunState state;
	private final ShortestPath shortestPath;
	private final ClientToolbar clientToolbar;
	private final ItemManager itemManager;
	private final ClusterWatch watch = new ClusterWatch();
	private TickGate gate = new TickGate();
	/** The view the watch follows (a new answer is a new object). */
	private FarmRuns watched;
	private long retryAt;
	/** Syncing has stopped on a problem only the player can fix: nothing goes to Ironwise until the settings change. */
	private boolean syncStopped;
	private FarmRunPanel panel;
	private NavigationButton button;
	private boolean buttonShown;

	@Inject
	FarmRunController(Client client, ClientThread clientThread, IronwiseConfig config, ConfigManager configManager, FarmRunClient http,
		FarmRunState state, ShortestPath shortestPath, ClientToolbar clientToolbar, ItemManager itemManager)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.configManager = configManager;
		this.http = http;
		this.state = state;
		this.shortestPath = shortestPath;
		this.clientToolbar = clientToolbar;
		this.itemManager = itemManager;
	}

	/** The plugin starting: the side panel, and its sidebar button while farm runs are on. */
	void startUp()
	{
		panel = new FarmRunPanel(itemManager, new FarmRunPanel.Actions()
		{
			@Override
			public void pick(String presetId)
			{
				clientThread.invokeLater(() -> picked(presetId));
			}

			@Override
			public void start(String presetId)
			{
				clientThread.invokeLater(() -> act(FarmRunClient.START, presetId));
			}

			@Override
			public void skip()
			{
				clientThread.invokeLater(() -> act(FarmRunClient.SKIP, null));
			}

			@Override
			public void previous()
			{
				clientThread.invokeLater(() -> act(FarmRunClient.PREVIOUS, null));
			}

			@Override
			public void end()
			{
				clientThread.invokeLater(() -> act(FarmRunClient.END, null));
			}
		});
		button = NavigationButton.builder().tooltip("Ironwise farm runs").icon(FarmRunPanel.icon()).priority(8).panel(panel).build();
		buttonShown = false;
		clientThread.invokeLater(this::settingsChanged);
	}

	/** The plugin stopping: the button goes, and the runs and the path this plugin drew (on the client thread). */
	void shutDown()
	{
		if (button != null && buttonShown)
		{
			clientToolbar.removeNavigation(button);
		}
		buttonShown = false;
		panel = null;
		button = null;
		clientThread.invokeLater(this::reset);
	}

	private String accountHash()
	{
		long hash = client.getAccountHash();
		return hash == -1 ? null : Long.toString(hash);
	}

	private String token()
	{
		return config.token() == null ? "" : config.token().trim();
	}

	private boolean on()
	{
		return config.syncEnabled() && config.farmRuns();
	}

	/**
	 * Every game tick while logged in on a standard world with syncing on.
	 *
	 * @param syncStopped why syncing stopped (the chat line: a bad token or address, or a refused sync), or null. Then,
	 *                    as with the sync, nothing more goes to that address until the settings change; the runs shown
	 *                    can't follow the game any more, so they go, and the side panel says why.
	 */
	void onGameTick(long now, String syncStopped)
	{
		if (!config.farmRuns())
		{
			return;
		}
		this.syncStopped = syncStopped != null;
		if (syncStopped != null)
		{
			if (state.paused(reason(syncStopped)))
			{
				forgetWatch();
			}
			return;
		}
		String hash = accountHash();
		if (hash == null || token().isEmpty())
		{
			return;
		}
		FarmRunState.Poll poll = state.startPoll(hash, now);
		HttpUrl url = FarmRunClient.getUrl(config.serverUrl(), hash);
		if (poll != null && url == null)
		{
			// Not an address the plugin sends to: the side panel says so (not "Waiting for Ironwise" for ever), and
			// the poll is over, so the next one goes as soon as the address is fixed.
			if (state.answered(poll, FarmRunClient.Result.failed(FarmRunClient.BAD_ADDRESS), now))
			{
				refreshPanel();
			}
		}
		else if (poll != null)
		{
			try
			{
				http.get(url, token(), poll.etag, r -> clientThread.invokeLater(() ->
				{
					if (state.answered(poll, r, System.currentTimeMillis()))
					{
						refreshPanel();
					}
				}));
			}
			catch (RuntimeException e)
			{
				state.answered(poll, FarmRunClient.Result.failed("couldn't send (" + e.getMessage() + ")"), now);
			}
		}
		FarmRuns runs = state.runs();
		if (runs != watched)
		{
			watched = runs;
			watch.update(runs);
		}
		FarmRuns.Active run = runs == null ? null : runs.active;
		FarmRuns.Stop stop = run == null || run.finished ? null : run.current();
		if (stop == null)
		{
			state.hint(null);
			shortestPath.show(null);
			return;
		}
		shortestPath.show(config.farmRunShortestPath() ? stop.point : null);
		read();
		state.hint(watch.hint());
		String done = watch.next();
		if (done != null && now >= retryAt)
		{
			send(FarmRunClient.ADVANCE, null, done, null);
		}
	}

	/** One tick's readings for every watched stop, through Time Tracking's gates. */
	private void read()
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return;
		}
		WorldPoint at = me.getWorldLocation();
		int region = at.getRegionID();
		Widget welcome = client.getWidget(InterfaceID.WelcomeScreen.MOTW);
		if (!gate.readable(welcome != null && !welcome.isHidden(), modalOpen(), region))
		{
			return;
		}
		Boolean houses = null;
		for (StopWatcher w : watch.watchers())
		{
			FarmRuns.Watch k = w.watch();
			int value;
			if ("birdhouse".equals(k.kind))
			{
				if (k.inRegion(region) && at.getPlane() == k.plane)
				{
					// On Fossil Island's surface, where Time Tracking reads them: not while they're still arriving.
					if (houses == null)
					{
						houses = gate.housesReadable(birdHouseVarps());
					}
					if (!houses)
					{
						continue;
					}
				}
				value = client.getVarpValue(k.varp);
			}
			else
			{
				value = client.getVarbitValue(k.varbit);
			}
			watch.tick(w, at.getX(), at.getY(), at.getPlane(), region, value);
		}
	}

	/** Varbits aren't sent while a modal interface is open (FarmingTracker#updateData). */
	private boolean modalOpen()
	{
		for (WidgetNode node : client.getComponentTable())
		{
			if (node.getModalMode() != WidgetModalMode.NON_MODAL)
			{
				return true;
			}
		}
		return false;
	}

	/** The four bird house spaces' varps, as BirdHouseSpace lists them. */
	private int[] birdHouseVarps()
	{
		return new int[]{
			client.getVarpValue(VarPlayerID.BIRDHOUSE_TRANSMIT_A),
			client.getVarpValue(VarPlayerID.BIRDHOUSE_TRANSMIT_B),
			client.getVarpValue(VarPlayerID.BIRDHOUSE_TRANSMIT_C),
			client.getVarpValue(VarPlayerID.BIRDHOUSE_TRANSMIT_D),
		};
	}

	/** The stop the run box shows (a finished run shows its last stop), which Skip and Previous name; null without a run. */
	static String shownStop(FarmRuns.Active run)
	{
		if (run == null || run.stops.isEmpty())
		{
			return null;
		}
		FarmRuns.Stop shown = run.finished || run.current() == null ? run.stops.get(run.stops.size() - 1) : run.current();
		return shown.patchId;
	}

	/** Why syncing stopped, as the side panel says it after "Couldn't get your farm runs: " (the chat line without "Ironwise: "). */
	static String reason(String syncStopped)
	{
		String prefix = "Ironwise: ";
		return syncStopped.startsWith(prefix) ? syncStopped.substring(prefix.length()) : syncStopped;
	}

	/** The player's click in words, for the chat line if it doesn't work. */
	static String words(String action)
	{
		switch (action)
		{
			case FarmRunClient.START:
				return "start the run";
			case FarmRunClient.END:
				return "end the run";
			case FarmRunClient.SKIP:
				return "skip the stop";
			default:
				return "go back a stop";
		}
	}

	/**
	 * The player's click: Start (presetId), Skip stop, Previous stop, End run. Skip and Previous name the stop the box
	 * shows, so a click the run has already moved past is refused. On the client thread.
	 */
	void act(String action, String presetId)
	{
		String stop = null;
		if (FarmRunClient.SKIP.equals(action) || FarmRunClient.PREVIOUS.equals(action))
		{
			stop = shownStop(state.active());
			if (stop == null)
			{
				return;
			}
		}
		send(action, presetId, stop, words(action));
	}

	/** The player picked (or unpicked) a run in the side panel: its Bring list is outlined in the bank. */
	private void picked(String presetId)
	{
		state.pick(presetId);
		refreshPanel();
	}

	/** Sends an action. `what`: the player's click, in words for the chat line if it fails; null for a stop the plugin saw dealt with. */
	private void send(String action, String presetId, String stop, String what)
	{
		String hash = accountHash();
		HttpUrl url = FarmRunClient.postUrl(config.serverUrl());
		if (hash == null || url == null || token().isEmpty() || !on() || syncStopped || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (!state.startAct())
		{
			if (what != null)
			{
				// One change at a time (an advance the plugin saw may be on its way): the player's click isn't lost
				// without a word. A stop seen dealt with just waits for the next tick.
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", FarmRunClient.couldnt(what, FarmRunClient.BUSY), null);
			}
			return;
		}
		int session = state.session();
		try
		{
			http.post(url, token(), http.body(hash, action, presetId, stop), r -> clientThread.invokeLater(() -> sent(session, r, stop, what)));
		}
		catch (RuntimeException e)
		{
			sent(session, FarmRunClient.Result.failed("couldn't send (" + e.getMessage() + ")"), stop, what);
		}
	}

	/** Back on the client thread with Ironwise's answer to an action. */
	private void sent(int session, FarmRunClient.Result r, String stop, String what)
	{
		if (state.answeredClick(session, r, System.currentTimeMillis()))
		{
			if (what == null)
			{
				watch.sent(stop);
			}
			refreshPanel();
			return;
		}
		if (session != state.session() || r.outcome != FarmRunClient.Outcome.FAILED)
		{
			return;
		}
		if (what != null)
		{
			// The player asked for this, so they hear why it didn't work even with chat messages off.
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", FarmRunClient.couldnt(what, r.message), null);
		}
		else
		{
			// A stop seen dealt with: tried again later, quietly. If the run has moved past it, the next answer drops it
			// from the watch.
			retryAt = System.currentTimeMillis() + RETRY_MS;
		}
	}

	/** Hide on the run box: unticks its setting and says how to bring it back. Nothing goes to Ironwise. */
	void hideBox()
	{
		FarmRunOverlay.hide((group, key, value) -> configManager.setConfiguration(group, key, value), client);
	}

	/** A hop or a loading screen: readings from before it can linger, so every watched stop settles again. */
	void hopped()
	{
		gate.reset();
		watch.reset();
	}

	/** Logged out: the runs go (the next login may be another account), and the panel says to log in. */
	void loggedOut()
	{
		reset();
	}

	/**
	 * A farm run setting, or Sync with Ironwise, changed: the sidebar button is there only while both are on; switched
	 * off, the runs and the path this plugin drew go. On the client thread.
	 */
	void settingsChanged()
	{
		if (!on())
		{
			reset();
		}
		NavigationButton b = button;
		boolean show = on() && b != null;
		if (show != buttonShown && b != null)
		{
			buttonShown = show;
			if (show)
			{
				clientToolbar.addNavigation(b);
			}
			else
			{
				clientToolbar.removeNavigation(b);
			}
		}
		if (!config.farmRunShortestPath())
		{
			shortestPath.show(null);
		}
		refreshPanel();
	}

	/** Another Ironwise address or token: the runs shown may be another site's. On the client thread. */
	void addressChanged()
	{
		reset();
		settingsChanged();
	}

	/**
	 * Logged out, another account, another Ironwise, syncing or farm runs switched off, or the plugin stopping: forget
	 * the runs and clear the path this plugin set.
	 */
	void reset()
	{
		state.clear();
		forgetWatch();
	}

	/** The runs are gone from the state: the watch, the retry and the path this plugin set go too, and the panel follows. */
	private void forgetWatch()
	{
		watch.clear();
		watched = null;
		gate = new TickGate();
		retryAt = 0;
		shortestPath.show(null);
		refreshPanel();
	}

	/** Shortest Path switched on or off: the panel's note follows. */
	void pluginsChanged()
	{
		refreshPanel();
	}

	/** Lays the panel out again from the state (the model is built here, laid out on the Swing thread). */
	void refreshPanel()
	{
		FarmRunPanel p = panel;
		if (p == null)
		{
			return;
		}
		FarmRunPanel.Model m;
		if (!on())
		{
			m = FarmRunPanel.Model.off();
		}
		else if (client.getGameState() != GameState.LOGGED_IN && state.runs() == null)
		{
			m = FarmRunPanel.Model.loggedOut();
		}
		else
		{
			m = FarmRunPanel.Model.of(state.runs(), state.picked(), state.problem(),
				!config.farmRunShortestPath() || shortestPath.enabled(), config.farmRunBankHighlight());
		}
		SwingUtilities.invokeLater(() -> p.show(m));
	}
}

package com.ironwise;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The run box (new in 0.5.0), compact like the Next step box, which steps aside while it's up: "Farm run · 3 of 7", the
 * stop, the way there Ironwise worked out as it words it ("Camelot Teleport", "Run from the last stop", "Home teleport ->
 * Lumbridge") and, for a route it can't confirm, what that hangs on after it, the whole route in its own colour
 * ("Ardougne cloak 2 -> Farm (if you still have a teleport left today)"), and a hint. Information only. Its menu entries
 * are RuneLite overlay entries (Shift + right-click on the box): Skip stop, Previous stop and End run tell Ironwise, each
 * naming the stop the box shows; Hide unticks the box's setting. Nothing here acts in the game.
 */
class FarmRunOverlay extends OverlayPanel
{
	static final String TARGET = "Farm run";
	static final String SKIP = "Skip stop";
	static final String PREVIOUS = "Previous stop";
	static final String END = "End run";
	static final String HIDE = "Hide";
	static final String DONE_HINT = "Shift + right-click the box: End run.";
	/** What Hide says in chat: the only way back is the setting, so it names it. */
	static final String HIDDEN = "Ironwise: run box hidden. Tick Show the run box in the Ironwise settings to bring it back.";
	static final int WIDTH = NextStepOverlay.WIDTH;
	/** The stop and the hint each wrap to at most this many lines. */
	static final int STOP_LINES = 2;
	/**
	 * The way there, with what it hangs on, wraps to at most this many (the app keeps its words to them: a route's
	 * condition in shorter words when the full ones don't fit), or one more rather than cut a condition short.
	 */
	static final int ROUTE_LINES = 3;
	static final Color MUTED = new Color(160, 160, 160);
	/** A route Ironwise can't confirm, with its condition: it never reads like the rest. */
	static final Color CONDITION = new Color(255, 200, 80);

	private final Client client;
	private final IronwiseConfig config;
	private final FarmRunState state;

	@Inject
	FarmRunOverlay(IronwisePlugin plugin, Client client, IronwiseConfig config, FarmRunState state, FarmRunController controller)
	{
		super(plugin);
		this.client = client;
		this.config = config;
		this.state = state;
		setPosition(OverlayPosition.TOP_RIGHT);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, SKIP, TARGET, e -> controller.act(FarmRunClient.SKIP, null));
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, PREVIOUS, TARGET, e -> controller.act(FarmRunClient.PREVIOUS, null));
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, END, TARGET, e -> controller.act(FarmRunClient.END, null));
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, HIDE, TARGET, e -> controller.hideBox());
	}

	/**
	 * Hide: unticks Show the run box, which hides the box at once, and says in chat how to bring it back. The player
	 * asked for it, so the line shows even with chat messages off. Only the setting changes: nothing goes to Ironwise,
	 * the run carries on, and nothing happens in the game.
	 */
	static void hide(NextStepOverlay.Settings settings, Client client)
	{
		settings.set(IronwiseConfig.GROUP, IronwiseConfig.FARM_RUN_BOX, false);
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", HIDDEN, null);
	}

	/** Whether the run box is up (a run on, and its settings ticked); the Next step box steps aside while it is. */
	static boolean showing(IronwiseConfig config, FarmRuns.Active run)
	{
		return run != null && config.syncEnabled() && config.farmRuns() && config.farmRunBox();
	}

	/** One line of the box under its title, wrapped, in its colour. */
	static final class Row
	{
		final String text;
		final Color colour;

		Row(String text, Color colour)
		{
			this.text = text;
			this.colour = colour;
		}
	}

	/**
	 * The box's lines: the title, then the stop, the way there with what it hangs on after it (for a route Ironwise can't
	 * confirm: "Ardougne cloak 2 -> Farm (if you still have a teleport left today)"), and a hint (or, finished, how to end
	 * it).
	 */
	static List<String> lines(FarmRuns.Active run, String hint)
	{
		List<String> out = new ArrayList<>();
		FarmRuns.Stop stop = run.current();
		if (run.finished || stop == null)
		{
			out.add("Farm run done");
			out.add(DONE_HINT);
			return out;
		}
		out.add("Farm run · " + (run.index + 1) + " of " + run.total());
		out.add(stop.name);
		if (stop.teleport != null)
		{
			out.add(route(stop.teleport));
		}
		if (hint != null)
		{
			out.add(hint);
		}
		return out;
	}

	/** The way there as the box shows it: its label, and what it hangs on after it. */
	private static String route(FarmRuns.Teleport t)
	{
		return t.condition == null ? t.label : t.label + " (" + t.condition + ")";
	}

	/** The way there wrapped to at most ROUTE_LINES, or one more rather than cut what it hangs on short. */
	static List<String> routeLines(String route, Predicate<String> fits)
	{
		return NextStepOverlay.wrap(route, ROUTE_LINES + 1, fits);
	}

	/** The lines under the title, wrapped to what fits the box: the stop, the way there, the hint. */
	static List<Row> rows(FarmRuns.Active run, String hint, Predicate<String> fits)
	{
		List<Row> out = new ArrayList<>();
		List<String> lines = lines(run, hint);
		FarmRuns.Stop stop = run.finished ? null : run.current();
		String route = stop != null && stop.teleport != null ? route(stop.teleport) : null;
		Color routeColour = stop != null && stop.teleport != null && stop.teleport.condition != null ? CONDITION : Color.WHITE;
		for (String line : lines.subList(1, lines.size()))
		{
			boolean muted = line.equals(hint) || line.equals(DONE_HINT);
			boolean isRoute = !muted && line.equals(route);
			Color colour = muted ? MUTED : isRoute ? routeColour : Color.WHITE;
			for (String part : isRoute ? routeLines(line, fits) : NextStepOverlay.wrap(line, STOP_LINES, fits))
			{
				out.add(new Row(part, colour));
			}
		}
		return out;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		FarmRuns.Active run = state.active();
		if (!showing(config, run) || client.getGameState() != GameState.LOGGED_IN
			|| RuneScapeProfileType.getCurrent(client) != RuneScapeProfileType.STANDARD)
		{
			return null;
		}
		String hint = state.hint();

		// The player can resize the box, like the Next step box; wrap to whatever width it has.
		Dimension size = getPreferredSize();
		int width = size != null && size.width > 0 ? size.width : WIDTH;
		panelComponent.setPreferredSize(new Dimension(width, 0));
		FontMetrics metrics = graphics.getFontMetrics();
		int inner = width - 2 * ComponentConstants.STANDARD_BORDER;
		Predicate<String> fits = s -> metrics.stringWidth(s) <= inner;

		panelComponent.getChildren().add(TitleComponent.builder().text(lines(run, hint).get(0)).build());
		for (Row row : rows(run, hint, fits))
		{
			panelComponent.getChildren().add(LineComponent.builder().left(row.text).leftColor(row.colour).build());
		}
		return super.render(graphics);
	}
}

package com.ironwise;

import java.awt.BasicStroke;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * The Ironwise side panel (new in 0.5.0): your saved and built-in farm runs, each with its picture (an item sprite for
 * its type), name, stops and minutes ("—" when Ironwise can't say, "~7" when they count a route it can't confirm);
 * pick one and its Bring list is outlined in the bank, then Start it. During a run: the stops with a tick for each one done and the current one marked, the way to the
 * current one (and what it hangs on, for a route Ironwise can't confirm), Previous, Skip and End, and what you're short. A note when Shortest Path isn't on. {@link Model} is what it shows, so the panel is tested
 * without Swing; the buttons call back through {@link Actions}. Every word from Ironwise is escaped before it goes into
 * a label or button ({@link #escape}): Swing reads text starting with {@code <html>} as HTML.
 */
class FarmRunPanel extends PluginPanel
{
	/** What the panel's clicks do (FarmRunController, on the client thread). Nothing here acts in the game. */
	interface Actions
	{
		default void pick(String presetId)
		{
		}

		default void start(String presetId)
		{
		}

		default void skip()
		{
		}

		default void previous()
		{
		}

		default void end()
		{
		}
	}

	/** What the panel shows. */
	static final class Model
	{
		static final String OFF = "Tick Sync with Ironwise and Farm runs in the Ironwise settings to see your farm runs here.";
		static final String LOGGED_OUT = "Log in to see your farm runs.";
		static final String WAITING = "Waiting for Ironwise…";
		static final String NO_RUN = "No run in progress. Pick one below, or start one on the Ironwise site.";
		static final String NO_RUNS = "No runs yet: save one on the Ironwise site.";
		static final String OUTLINED = "Its Bring list is outlined in your bank.";
		static final String NOTHING_TO_OUTLINE = "Ironwise can't list what to bring for this run yet.";
		static final String INSTALL_SHORTEST_PATH = "Install Shortest Path from the Plugin Hub to have the way drawn.";

		String status;
		/** A run is in progress (finished or not). */
		boolean running;
		boolean canSkip;
		boolean canPrevious;
		/** Each stop in words ("Done: …"), for screen readers; the panel shows a mark and the name. */
		final List<String> stops = new ArrayList<>();
		final List<String> stopNames = new ArrayList<>();
		final List<String> stopStates = new ArrayList<>();
		/** The way to the current stop, as the run box words it ("Run from the last stop"), or null: a walk, or none known. */
		String route;
		/**
		 * What that route hangs on, for one Ironwise can't confirm, on its own line ("If you still have a teleport left
		 * today"), or null.
		 */
		String routeCondition;
		final List<String> missing = new ArrayList<>();
		/** The list of runs to pick from: when no run is on, or once it's finished. */
		boolean showRuns;
		final List<String> presetIds = new ArrayList<>();
		final List<String> presetNames = new ArrayList<>();
		final List<String> presetDetails = new ArrayList<>();
		/** Each run's picture: an item id, or null. */
		final List<Integer> presetIcons = new ArrayList<>();
		/** The picked run's place in the list; -1: none. */
		int picked = -1;
		/** The Start button's words for the picked run, or null. */
		String start;
		/** What the bank shows for the picked run, or null. */
		String bankNote;
		String note;

		static Model off()
		{
			Model m = new Model();
			m.status = OFF;
			return m;
		}

		static Model loggedOut()
		{
			Model m = new Model();
			m.status = LOGGED_OUT;
			return m;
		}

		/**
		 * @param picked         the run picked in the panel, or null
		 * @param problem        why the last poll didn't work, or null
		 * @param shortestPathOn Shortest Path is on (or drawing the way is switched off): no note about it
		 * @param outlineOn      the bank outline setting is ticked
		 */
		static Model of(FarmRuns runs, String picked, String problem, boolean shortestPathOn, boolean outlineOn)
		{
			Model m = new Model();
			if (runs == null)
			{
				m.status = problem == null ? WAITING : "Couldn't get your farm runs: " + problem;
				return m;
			}
			for (FarmRuns.Preset p : runs.presets)
			{
				m.presetIds.add(p.id);
				m.presetNames.add(p.name);
				// Unknown minutes are shown as unknown, never as 0; minutes that count a route Ironwise can't confirm, as a
				// guess (the site's "Total ≈").
				m.presetDetails.add(p.stops + " stop" + (p.stops == 1 ? "" : "s") + " · " + (p.minutes == null ? "—" : (p.minutesUnsure ? "~" : "") + p.minutes) + " min");
				m.presetIcons.add(p.iconItem);
			}
			FarmRuns.Active a = runs.active;
			if (a == null)
			{
				m.status = NO_RUN;
				m.showRuns = true;
			}
			else
			{
				m.running = true;
				m.status = a.finished ? a.name + " · done" : a.name + " · " + (a.index + 1) + " of " + a.total();
				for (FarmRuns.Stop s : a.stops)
				{
					m.stops.add(prefix(s.state) + s.name);
					m.stopNames.add(s.name);
					m.stopStates.add(s.state);
				}
				FarmRuns.Stop now = a.finished ? null : a.current();
				if (now != null && now.teleport != null)
				{
					m.route = now.teleport.label;
					String c = now.teleport.condition;
					m.routeCondition = c == null ? null : Character.toUpperCase(c.charAt(0)) + c.substring(1);
				}
				for (FarmRuns.BringItem b : a.bring)
				{
					// Recommended items are never short, and an item Ironwise can't see is unknown, not 0.
					if (!b.optional && b.have != null && b.have < b.qty)
					{
						m.missing.add(b.name + ": have " + b.have + " of " + b.qty);
					}
				}
				m.canSkip = !a.finished && a.current() != null;
				m.canPrevious = a.index > 0;
				m.showRuns = a.finished;
			}
			if (m.showRuns)
			{
				m.picked = picked == null ? -1 : m.presetIds.indexOf(picked);
				if (m.picked >= 0)
				{
					FarmRuns.Preset p = runs.presets.get(m.picked);
					m.start = "Start " + p.name;
					m.bankNote = !outlineOn ? null : p.bringItemIds.length > 0 ? OUTLINED : NOTHING_TO_OUTLINE;
				}
			}
			m.note = shortestPathOn ? null : INSTALL_SHORTEST_PATH;
			return m;
		}

		/** A stop's state in words (the panel draws a mark for it; the words are for screen readers). */
		static String prefix(String state)
		{
			switch (state)
			{
				case "done":
					return "Done: ";
				case "skipped":
					return "Skipped: ";
				case "current":
					return "Now: ";
				default:
					return "Next: ";
			}
		}
	}

	/** Text width inside the panel, and beside a run's picture. */
	private static final int TEXT_WIDTH = PANEL_WIDTH - 30;
	private static final int ROW_TEXT_WIDTH = TEXT_WIDTH - 60;
	private static final Color TICK = new Color(90, 190, 90);
	private static final Map<String, BufferedImage> MARKS = new HashMap<>();

	private final JPanel body = new JPanel();
	private final ItemManager items;
	private final Actions actions;

	FarmRunPanel(ItemManager items, Actions actions)
	{
		this.items = items;
		this.actions = actions;
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		add(body, BorderLayout.NORTH);
		show(Model.off());
	}

	/** Swing reads text starting with {@code <html>} as HTML: this makes any text plain words inside HTML. */
	static String escape(String text)
	{
		StringBuilder b = new StringBuilder(text.length() + 16);
		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			switch (c)
			{
				case '&':
					b.append("&amp;");
					break;
				case '<':
					b.append("&lt;");
					break;
				case '>':
					b.append("&gt;");
					break;
				case '"':
					b.append("&quot;");
					break;
				case '\'':
					b.append("&#39;");
					break;
				default:
					b.append(c);
			}
		}
		return b.toString();
	}

	/** Text for a label or button, escaped, wrapped to `width` pixels (0: not wrapped). */
	static String html(String text, int width)
	{
		return width > 0
			? "<html><div style=\"width:" + width + "px\">" + escape(text) + "</div></html>"
			: "<html>" + escape(text) + "</html>";
	}

	/** Lays the model out again (on the Swing thread). */
	void show(Model m)
	{
		body.removeAll();
		body.add(heading("Farm runs"));
		body.add(label(m.status, Color.WHITE, TEXT_WIDTH));
		if (m.running)
		{
			for (int i = 0; i < m.stopNames.size(); i++)
			{
				String state = m.stopStates.get(i);
				JLabel stop = label(m.stopNames.get(i), "current".equals(state) ? ColorScheme.BRAND_ORANGE : "todo".equals(state) ? Color.WHITE : Color.GRAY, TEXT_WIDTH - 20);
				stop.setIcon(new ImageIcon(mark(state)));
				stop.setIconTextGap(6);
				stop.getAccessibleContext().setAccessibleName(m.stops.get(i));
				stop.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
				body.add(stop);
				if ("current".equals(state) && m.route != null)
				{
					// Under the current stop, lined up with its name: the way there, and what it hangs on.
					body.add(indented(label(m.route, Color.LIGHT_GRAY, TEXT_WIDTH - 40)));
					if (m.routeCondition != null)
					{
						body.add(indented(label(m.routeCondition, FarmRunOverlay.CONDITION, TEXT_WIDTH - 40)));
					}
				}
			}
			JPanel buttons = new JPanel(new GridLayout(1, 0, 4, 0));
			buttons.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));
			if (m.canPrevious)
			{
				buttons.add(button("Previous", actions::previous));
			}
			if (m.canSkip)
			{
				buttons.add(button("Skip stop", actions::skip));
			}
			buttons.add(button("End run", actions::end));
			body.add(left(buttons));
		}
		if (!m.missing.isEmpty())
		{
			body.add(heading("Short"));
			for (String s : m.missing)
			{
				body.add(label(s, ColorScheme.PROGRESS_ERROR_COLOR, TEXT_WIDTH));
			}
		}
		if (m.showRuns)
		{
			body.add(heading("Your runs"));
			if (m.presetIds.isEmpty())
			{
				body.add(label(Model.NO_RUNS, Color.LIGHT_GRAY, TEXT_WIDTH));
			}
			for (int i = 0; i < m.presetIds.size(); i++)
			{
				body.add(row(m, i));
			}
			if (m.start != null)
			{
				String id = m.presetIds.get(m.picked);
				JButton start = new JButton(html(m.start, 0));
				start.addActionListener(e -> actions.start(id));
				JPanel wrap = new JPanel(new BorderLayout());
				wrap.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));
				wrap.add(start, BorderLayout.CENTER);
				body.add(left(wrap));
			}
			if (m.bankNote != null)
			{
				body.add(label(m.bankNote, Color.LIGHT_GRAY, TEXT_WIDTH));
			}
		}
		if (m.note != null)
		{
			JLabel note = label(m.note, Color.LIGHT_GRAY, TEXT_WIDTH);
			note.setBorder(BorderFactory.createEmptyBorder(10, 0, 0, 0));
			body.add(note);
		}
		body.revalidate();
		body.repaint();
	}

	/** A label moved right to line up with the stop names beside their marks. */
	private static JLabel indented(JLabel label)
	{
		label.setBorder(BorderFactory.createEmptyBorder(0, 20, 2, 0));
		return label;
	}

	/** One run to pick: its picture, name, and stops and minutes. Clicking it picks it (or, picked, unpicks it). */
	private JPanel row(Model m, int i)
	{
		String id = m.presetIds.get(i);
		boolean picked = i == m.picked;
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(picked ? ColorScheme.DARKER_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 4, 0, ColorScheme.DARK_GRAY_COLOR),
			BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, 3, 0, 0, picked ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR),
				BorderFactory.createEmptyBorder(4, 4, 4, 4))));
		Integer icon = m.presetIcons.get(i);
		JLabel picture = new JLabel();
		picture.setPreferredSize(new java.awt.Dimension(36, 32));
		if (icon != null && items != null)
		{
			items.getImage(icon).addTo(picture);
		}
		row.add(picture, BorderLayout.WEST);
		JPanel text = new JPanel(new GridLayout(0, 1));
		text.setOpaque(false);
		text.add(label(m.presetNames.get(i), Color.WHITE, ROW_TEXT_WIDTH));
		text.add(label(m.presetDetails.get(i), Color.LIGHT_GRAY, ROW_TEXT_WIDTH));
		row.add(text, BorderLayout.CENTER);
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.getAccessibleContext().setAccessibleName((picked ? "Picked: " : "Pick: ") + m.presetNames.get(i));
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				actions.pick(id);
			}
		});
		return left(row);
	}

	private static <T extends JComponent> T left(T c)
	{
		c.setAlignmentX(LEFT_ALIGNMENT);
		return c;
	}

	private static JLabel heading(String text)
	{
		JLabel l = new JLabel(text);
		l.setForeground(Color.WHITE);
		l.setBorder(BorderFactory.createEmptyBorder(8, 0, 4, 0));
		return left(l);
	}

	/** A label for any text, Ironwise's included: escaped, wrapped to `width`. */
	private static JLabel label(String text, Color colour, int width)
	{
		JLabel l = new JLabel(html(text, width));
		l.setForeground(colour);
		return left(l);
	}

	private static JButton button(String text, Runnable action)
	{
		JButton b = new JButton(text);
		b.addActionListener(e -> action.run());
		return b;
	}

	/** The sidebar button's picture: a small sprout, drawn (no image file). */
	static BufferedImage icon()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(TICK);
		g.setStroke(new BasicStroke(2f));
		g.drawLine(8, 15, 8, 6);
		g.fillOval(2, 3, 6, 5);
		g.fillOval(8, 1, 6, 5);
		g.dispose();
		return img;
	}

	/**
	 * A stop's mark, drawn (RuneLite's panel font has no tick): a tick when done, a dash when skipped, a filled dot for
	 * the current stop, an empty ring for the stops to come.
	 */
	static synchronized BufferedImage mark(String state)
	{
		// Kept one per state the panel knows (a state it doesn't is a stop to come), so there are never more than four.
		String known = "done".equals(state) || "skipped".equals(state) || "current".equals(state) ? state : "todo";
		return MARKS.computeIfAbsent(known, s ->
		{
			BufferedImage img = new BufferedImage(12, 12, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = img.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			switch (s)
			{
				case "done":
					g.setColor(TICK);
					g.drawLine(2, 6, 5, 9);
					g.drawLine(5, 9, 10, 2);
					break;
				case "skipped":
					g.setColor(Color.GRAY);
					g.drawLine(2, 6, 10, 6);
					break;
				case "current":
					g.setColor(ColorScheme.BRAND_ORANGE);
					g.fillOval(2, 2, 8, 8);
					break;
				default:
					g.setColor(Color.GRAY);
					g.setStroke(new BasicStroke(1.5f));
					g.drawOval(2, 2, 8, 8);
			}
			g.dispose();
			return img;
		});
	}
}

package com.ironwise;

import java.util.Collections;
import java.util.Set;
import javax.inject.Singleton;

/**
 * The account's farm runs as Ironwise last sent them, the run picked in the side panel, and one poll and one click at a
 * time (new in 0.5.0). Polls come every {@link #POLL_MS} while logged in (after a failed one, 20 s, 40 s, then at most a
 * minute); an answer for another account, or from before the player switched account or logged out, is dropped, and so
 * is a poll's answer when a click was sent after the poll or was still on its way when the poll went (the click's
 * answer is the newer view: without this a slow poll could put the box back on a stop just dealt with). The bank
 * outline's item ids are worked out once per answer or pick: the run in progress's Bring list, otherwise the picked
 * run's (its bringItemIds, before Start).
 */
@Singleton
class FarmRunState
{
	static final long POLL_MS = 10_000L;
	static final long MAX_POLL_WAIT_MS = 60_000L;

	static final class Poll
	{
		final int session;
		/** Clicks sent before this poll: a later click makes its answer old. */
		final int clicks;
		/**
		 * A click was on its way when this poll was sent: Ironwise may have read the run before saving the click, and
		 * the poll's answer can come after the click's, so it's dropped too (the click's answer is the newer view).
		 */
		final boolean clickOut;
		final String accountHash;
		final String etag;

		Poll(int session, int clicks, boolean clickOut, String accountHash, String etag)
		{
			this.session = session;
			this.clicks = clicks;
			this.clickOut = clickOut;
			this.accountHash = accountHash;
			this.etag = etag;
		}
	}

	private FarmRuns runs;
	/** The run picked in the side panel (a listed run's id), or null. */
	private String picked;
	private Set<Integer> bankIds = Collections.emptySet();
	/** Why the last poll didn't work, or null. */
	private String problem;
	private String hint;
	private String etag;
	private String accountHash;
	private int session;
	private int clicks;
	private boolean polling;
	private boolean acting;
	private long polledAt = Long.MIN_VALUE / 2;
	private long pollWait = POLL_MS;

	synchronized FarmRuns runs()
	{
		return runs;
	}

	/** The item ids to outline in the bank; empty with no run on and none picked. */
	synchronized Set<Integer> bankIds()
	{
		return bankIds;
	}

	synchronized FarmRuns.Active active()
	{
		return runs == null ? null : runs.active;
	}

	synchronized String picked()
	{
		return picked;
	}

	synchronized String problem()
	{
		return problem;
	}

	/** The run box's line about the current stop's patch ("Still growing…"), or null. */
	synchronized String hint()
	{
		return hint;
	}

	/** Set by the controller each tick from what it reads of the current stop. */
	synchronized void hint(String hint)
	{
		this.hint = hint;
	}

	synchronized String accountHash()
	{
		return accountHash;
	}

	synchronized int session()
	{
		return session;
	}

	/**
	 * The player picks a run in the side panel (its Bring list is outlined in the bank from now on), or picks the picked
	 * one again to unpick it. Only a run Ironwise listed can be picked.
	 */
	synchronized void pick(String presetId)
	{
		if (presetId != null && presetId.equals(picked))
		{
			picked = null;
		}
		else
		{
			picked = runs != null && presetId != null && runs.preset(presetId) != null ? presetId : null;
		}
		outline();
	}

	/** A poll to send now for this account, or null (one on its way, or too soon). */
	synchronized Poll startPoll(String hash, long now)
	{
		if (!hash.equals(accountHash))
		{
			forget();
			accountHash = hash;
		}
		if (polling || now - polledAt < pollWait)
		{
			return null;
		}
		polling = true;
		polledAt = now;
		return new Poll(session, clicks, acting, hash, etag);
	}

	/** A poll's answer. True when the view changed. */
	synchronized boolean answered(Poll p, FarmRunClient.Result r, long now)
	{
		if (p.session != session)
		{
			return false;
		}
		polling = false;
		if (r.outcome == FarmRunClient.Outcome.FAILED)
		{
			// Not there, or not answering: ask less often, and say why in the side panel.
			pollWait = Math.min(pollWait * 2, MAX_POLL_WAIT_MS);
			boolean changed = !r.message.equals(problem);
			problem = r.message;
			return changed;
		}
		pollWait = POLL_MS;
		boolean changed = problem != null;
		problem = null;
		if (p.clicks != clicks || p.clickOut)
		{
			// A click was sent while this poll was out, or was on its way when it went: its answer is newer than this one.
			return changed;
		}
		return take(r, now) || changed;
	}

	/** A click's answer (the session it was sent in). True when the view changed. */
	synchronized boolean answeredClick(int clickSession, FarmRunClient.Result r, long now)
	{
		if (clickSession != session)
		{
			return false;
		}
		acting = false;
		return take(r, now);
	}

	private boolean take(FarmRunClient.Result r, long now)
	{
		if (r.outcome != FarmRunClient.Outcome.OK)
		{
			return false;
		}
		runs = r.runs;
		if (picked != null && runs.preset(picked) == null)
		{
			// Deleted on the website: nothing to outline for it.
			picked = null;
		}
		outline();
		etag = r.etag;
		polledAt = now;
		return true;
	}

	private void outline()
	{
		bankIds = Collections.unmodifiableSet(BankHighlightOverlay.ids(runs, picked));
	}

	/** Starts a click (Start, Skip, advance…) if none is on its way; any poll already out is then old. */
	synchronized boolean startAct()
	{
		if (acting)
		{
			return false;
		}
		acting = true;
		clicks++;
		return true;
	}

	/**
	 * Syncing stopped on a problem only the player can fix (`why`, in the side panel's words): the runs go, a poll or
	 * click still on its way is dropped when it answers, and the panel says why. The controller starts no poll or click
	 * until syncing starts again. True when the view changed (false while it's already paused for the same reason).
	 */
	synchronized boolean paused(String why)
	{
		if (runs == null && why.equals(problem) && !polling && !acting)
		{
			return false;
		}
		forget();
		problem = why;
		return true;
	}

	/** Logged out, another account, or the plugin stopped. */
	synchronized void clear()
	{
		forget();
		accountHash = null;
	}

	private void forget()
	{
		session++;
		runs = null;
		picked = null;
		bankIds = Collections.emptySet();
		problem = null;
		hint = null;
		etag = null;
		polling = false;
		acting = false;
		polledAt = Long.MIN_VALUE / 2;
		pollWait = POLL_MS;
	}
}

package com.ironwise;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.regex.Pattern;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * An account's farm runs as Ironwise sends them (GET /api/plugin/runs; every POST answers the same; new in 0.5.0): the
 * saved and built-in runs, each with the items its Bring list would outline in the bank; the run in progress with each
 * stop's name, Shortest Path target, teleport and what to watch, and its Bring list; and the value tables the run box
 * reads a patch's varbit with. Ironwise works everything out; the plugin shows it, watches the current stop and says
 * when it's dealt with, reading only the farming patch varbits and bird house varps listed here
 * ({@link #FARMING_VARBITS}, {@link #BIRD_HOUSE_VARPS}), whatever Ironwise names. {@link #parse} never throws: a part
 * that's missing or out of range is left out, and a run that can't be read is dropped (the saved runs stay). Names are
 * cleaned for the game's fonts here; the side panel escapes them again for Swing.
 */
final class FarmRuns
{
	static final int MAX_NAME = 80;
	/** The app's MAX_BRING_ITEM_IDS (src/lib/farm/types.ts): a run's bank outline has at most this many ids. */
	static final int MAX_BRING_ITEM_IDS = 200;
	private static final int MAX_PRESETS = 50;
	private static final int MAX_STOPS = 200;
	private static final Pattern PATCH_ID = Pattern.compile("^[a-z][a-z0-9-]{2,48}$");
	/** A saved run's id, or a built-in run's (the app's PRESET_ID_RE and BUILTIN_ID_RE). */
	private static final Pattern PRESET_ID = Pattern.compile("^([A-Za-z0-9_-]{8}|builtin-[a-z]{1,20})$");
	static final Set<String> CLASSES = new HashSet<>(Arrays.asList("empty", "planted", "grown", "harvest", "diseased", "dead"));
	/**
	 * The only varbits a stop's watch may name, whatever Ironwise sends: the farming patch varbits RuneLite's Time
	 * Tracking reads patches from (FarmingWorld). A watch naming any other is left out, and that stop is skipped by hand.
	 */
	static final Set<Integer> FARMING_VARBITS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		VarbitID.FARMING_TRANSMIT_A, VarbitID.FARMING_TRANSMIT_B, VarbitID.FARMING_TRANSMIT_C, VarbitID.FARMING_TRANSMIT_D,
		VarbitID.FARMING_TRANSMIT_E, VarbitID.FARMING_TRANSMIT_A1, VarbitID.FARMING_TRANSMIT_A2, VarbitID.FARMING_TRANSMIT_B1,
		VarbitID.FARMING_TRANSMIT_B2, VarbitID.FARMING_TRANSMIT_C1, VarbitID.FARMING_TRANSMIT_C2, VarbitID.FARMING_TRANSMIT_D1,
		VarbitID.FARMING_TRANSMIT_D2, VarbitID.FARMING_TRANSMIT_E1, VarbitID.FARMING_TRANSMIT_E2, VarbitID.FARMING_TRANSMIT_F1,
		VarbitID.FARMING_TRANSMIT_F2, VarbitID.FARMING_TRANSMIT_F, VarbitID.FARMING_TRANSMIT_G, VarbitID.FARMING_TRANSMIT_H,
		VarbitID.FARMING_TRANSMIT_I, VarbitID.FARMING_TRANSMIT_J, VarbitID.FARMING_TRANSMIT_K, VarbitID.FARMING_TRANSMIT_L,
		VarbitID.FARMING_TRANSMIT_M)));
	/** The only varps a bird house watch may name: the four bird house spaces' (BirdHouseSpace). */
	static final Set<Integer> BIRD_HOUSE_VARPS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		VarPlayerID.BIRDHOUSE_TRANSMIT_A, VarPlayerID.BIRDHOUSE_TRANSMIT_B, VarPlayerID.BIRDHOUSE_TRANSMIT_C,
		VarPlayerID.BIRDHOUSE_TRANSMIT_D)));

	final String rev;
	/** The saved runs, then the built-in ones, as Ironwise lists them. */
	final List<Preset> presets;
	/** The run in progress, or null. */
	final Active active;
	/** Value → class ranges per PatchImplementation (only those the run watches). */
	final Map<String, List<Range>> tables;

	private FarmRuns(String rev, List<Preset> presets, Active active, Map<String, List<Range>> tables)
	{
		this.rev = rev;
		this.presets = presets;
		this.active = active;
		this.tables = tables;
	}

	/** The listed run with this id, or null. */
	Preset preset(String id)
	{
		for (Preset p : presets)
		{
			if (p.id.equals(id))
			{
				return p;
			}
		}
		return null;
	}

	static final class Preset
	{
		final String id;
		final String name;
		final String icon;
		/** An item whose picture shows the run's type; null when Ironwise can't say. */
		final Integer iconItem;
		final int stops;
		/** Est. minutes for this account; null when Ironwise can't say. */
		final Integer minutes;
		/**
		 * The minutes count a route Ironwise can't confirm (a stop's only way hangs on something it can't see), so the
		 * side panel shows them as a guess ("~7 min"). False when left out (a server from before it) or with no minutes.
		 */
		final boolean minutesUnsure;
		/**
		 * The items to outline in the bank once this run is picked in the side panel, before it starts: every id that
		 * satisfies a row of its Bring list for this account. Empty when Ironwise can't plan it (or is older than 0.5.0).
		 */
		final int[] bringItemIds;

		Preset(String id, String name, String icon, Integer iconItem, int stops, Integer minutes, boolean minutesUnsure, int[] bringItemIds)
		{
			this.id = id;
			this.name = name;
			this.icon = icon;
			this.iconItem = iconItem;
			this.stops = stops;
			this.minutes = minutes;
			this.minutesUnsure = minutes != null && minutesUnsure;
			this.bringItemIds = bringItemIds;
		}
	}

	static final class Active
	{
		final String presetId;
		final String name;
		final int index;
		final boolean finished;
		final long startedAt;
		/** "web" or "plugin". */
		final String by;
		final List<Stop> stops;
		final List<BringItem> bring;

		Active(String presetId, String name, int index, boolean finished, long startedAt, String by, List<Stop> stops, List<BringItem> bring)
		{
			this.presetId = presetId;
			this.name = name;
			this.index = index;
			this.finished = finished;
			this.startedAt = startedAt;
			this.by = by;
			this.stops = stops;
			this.bring = bring;
		}

		/** The stop the player is on; null once the run is finished. */
		Stop current()
		{
			return index < stops.size() ? stops.get(index) : null;
		}

		int total()
		{
			return stops.size();
		}

		/**
		 * The stops the run box watches: the current stop and the stops of its cluster still to do (a player may take a
		 * cluster's patches in any order); none once the run is finished.
		 */
		List<Stop> openInCluster()
		{
			List<Stop> out = new ArrayList<>();
			Stop now = finished ? null : current();
			if (now == null)
			{
				return out;
			}
			for (Stop s : stops)
			{
				if (Objects.equals(s.cluster, now.cluster) && ("current".equals(s.state) || "todo".equals(s.state)))
				{
					out.add(s);
				}
			}
			return out;
		}
	}

	static final class Stop
	{
		final String patchId;
		final String name;
		final String type;
		/** The patches you walk between after one teleport share a cluster. */
		final String cluster;
		/** "done", "skipped", "current" or "todo". */
		final String state;
		final Point point;
		final Teleport teleport;
		final Watch watch;

		Stop(String patchId, String name, String type, String cluster, String state, Point point, Teleport teleport, Watch watch)
		{
			this.patchId = patchId;
			this.name = name;
			this.type = type;
			this.cluster = cluster;
			this.state = state;
			this.point = point;
			this.teleport = teleport;
			this.watch = watch;
		}
	}

	static final class Point
	{
		final int x;
		final int y;
		final int plane;

		Point(int x, int y, int plane)
		{
			this.x = x;
			this.y = y;
			this.plane = plane;
		}

		@Override
		public boolean equals(Object o)
		{
			return o instanceof Point && ((Point) o).x == x && ((Point) o).y == y && ((Point) o).plane == plane;
		}

		@Override
		public int hashCode()
		{
			return (x * 31 + y) * 31 + plane;
		}
	}

	/**
	 * The way to a stop that starts a cluster, as Ironwise words it for the run box: a teleport ("Camelot Teleport"), a run
	 * ("Run from the last stop") or the home teleport ("Home teleport -> Lumbridge"), shown as it is; and, for a route
	 * Ironwise can't confirm (the stop's only one), what it hangs on as the site words it, which the run box shows after
	 * it ("if you still have a teleport left today"), else null.
	 */
	static final class Teleport
	{
		final String label;
		final int[] itemIds;
		final String condition;

		Teleport(String label, int[] itemIds, String condition)
		{
			this.label = label;
			this.itemIds = itemIds;
			this.condition = condition;
		}
	}

	static final class Watch
	{
		/** "varbit" (a farming patch) or "birdhouse" (a bird house space's varp). */
		final String kind;
		final int varbit;
		final int varp;
		final String impl;
		final int[] regions;
		final Bounds bounds;
		final List<DoneRule> doneWhen;
		final int plane;
		final Point near;

		Watch(String kind, int varbit, int varp, String impl, int[] regions, Bounds bounds, List<DoneRule> doneWhen, int plane, Point near)
		{
			this.kind = kind;
			this.varbit = varbit;
			this.varp = varp;
			this.impl = impl;
			this.regions = regions;
			this.bounds = bounds;
			this.doneWhen = doneWhen;
			this.plane = plane;
			this.near = near;
		}

		boolean inRegion(int regionId)
		{
			for (int r : regions)
			{
				if (r == regionId)
				{
					return true;
				}
			}
			return false;
		}
	}

	/** RuneLite's FarmingRegion#isInBounds as data: inside when in one of `any` and in none of `not`. */
	static final class Bounds
	{
		final List<Box> any;
		final List<Box> not;

		Bounds(List<Box> any, List<Box> not)
		{
			this.any = any;
			this.not = not;
		}

		boolean contains(int x, int y, int plane)
		{
			for (Box b : not)
			{
				if (b.contains(x, y, plane))
				{
					return false;
				}
			}
			for (Box b : any)
			{
				if (b.contains(x, y, plane))
				{
					return true;
				}
			}
			return false;
		}
	}

	static final class Box
	{
		final Integer minX;
		final Integer maxX;
		final Integer minY;
		final Integer maxY;
		final Integer plane;

		Box(Integer minX, Integer maxX, Integer minY, Integer maxY, Integer plane)
		{
			this.minX = minX;
			this.maxX = maxX;
			this.minY = minY;
			this.maxY = maxY;
			this.plane = plane;
		}

		boolean contains(int x, int y, int p)
		{
			return (minX == null || x >= minX) && (maxX == null || x <= maxX) && (minY == null || y >= minY)
				&& (maxY == null || y <= maxY) && (plane == null || p == plane);
		}
	}

	static final class DoneRule
	{
		final Set<String> from;
		final String to;

		DoneRule(Set<String> from, String to)
		{
			this.from = from;
			this.to = to;
		}
	}

	static final class Range
	{
		final int from;
		final int to;
		final String cls;

		Range(int from, int to, String cls)
		{
			this.from = from;
			this.to = to;
			this.cls = cls;
		}
	}

	static final class BringItem
	{
		final int[] itemIds;
		final String name;
		final int qty;
		/** Owned; null when Ironwise can't see enough to say. */
		final Integer have;
		/** Recommended, not needed: never listed as short. */
		final boolean optional;

		BringItem(int[] itemIds, String name, int qty, Integer have, boolean optional)
		{
			this.itemIds = itemIds;
			this.name = name;
			this.qty = qty;
			this.have = have;
			this.optional = optional;
		}
	}

	/** The class of a varbit value in a table; null when the table has no row for it (ignore the reading). */
	static String classOf(List<Range> table, int value)
	{
		if (table == null)
		{
			return null;
		}
		for (Range r : table)
		{
			if (value >= r.from && value <= r.to)
			{
				return r.cls;
			}
		}
		return null;
	}

	/** The answer from its JSON, or null if it isn't a usable farm runs answer. */
	static FarmRuns parse(JsonElement json)
	{
		if (json == null || !json.isJsonObject())
		{
			return null;
		}
		JsonObject o = json.getAsJsonObject();
		if (!Boolean.TRUE.equals(bool(o, "ok")))
		{
			return null;
		}
		String rev = string(o, "rev");
		if (rev == null || rev.isEmpty() || rev.length() > 80)
		{
			return null;
		}
		List<Preset> presets = new ArrayList<>();
		for (JsonObject p : objects(o, "presets", MAX_PRESETS))
		{
			String id = string(p, "id");
			String name = name(p);
			Integer stops = integer(p, "stops");
			if (id != null && PRESET_ID.matcher(id).matches() && name != null && stops != null && stops > 0)
			{
				// A picture of an item below 0 never loads (RuneLite keeps asking for it): no picture.
				Integer iconItem = integer(p, "iconItem");
				presets.add(new Preset(id, name, string(p, "icon"), iconItem == null || iconItem < 0 ? null : iconItem, stops, integer(p, "minutes"), Boolean.TRUE.equals(bool(p, "minutesUnsure")), itemIds(p, "bringItemIds", MAX_BRING_ITEM_IDS)));
			}
		}
		return new FarmRuns(rev, Collections.unmodifiableList(presets), active(o.get("active")), tables(o.get("tables")));
	}

	private static Active active(JsonElement json)
	{
		if (json == null || !json.isJsonObject())
		{
			return null;
		}
		JsonObject o = json.getAsJsonObject();
		String name = name(o);
		Integer index = integer(o, "index");
		Boolean finished = bool(o, "finished");
		Long startedAt = longValue(o, "startedAt");
		List<Stop> stops = new ArrayList<>();
		for (JsonObject s : objects(o, "stops", MAX_STOPS))
		{
			Stop stop = stop(s);
			if (stop == null)
			{
				return null;
			}
			stops.add(stop);
		}
		if (name == null || index == null || finished == null || startedAt == null || stops.isEmpty() || index < 0 || index > stops.size())
		{
			return null;
		}
		List<BringItem> bring = new ArrayList<>();
		for (JsonObject b : objects(o, "bring", MAX_BRING_ITEM_IDS))
		{
			String n = name(b);
			Integer qty = integer(b, "qty");
			if (n != null && qty != null && qty > 0)
			{
				bring.add(new BringItem(itemIds(b, "itemIds", MAX_BRING_ITEM_IDS), n, qty, integer(b, "have"), Boolean.TRUE.equals(bool(b, "optional"))));
			}
		}
		return new Active(string(o, "presetId"), name, index, finished, startedAt, string(o, "by"), Collections.unmodifiableList(stops), Collections.unmodifiableList(bring));
	}

	private static Stop stop(JsonObject s)
	{
		String id = string(s, "patchId");
		String name = name(s);
		String state = string(s, "state");
		if (id == null || !PATCH_ID.matcher(id).matches() || name == null || state == null)
		{
			return null;
		}
		Teleport teleport = null;
		JsonElement t = s.get("teleport");
		if (t != null && t.isJsonObject())
		{
			String label = name(t.getAsJsonObject(), "label");
			if (label != null)
			{
				teleport = new Teleport(label, itemIds(t.getAsJsonObject(), "itemIds", MAX_BRING_ITEM_IDS), name(t.getAsJsonObject(), "condition"));
			}
		}
		return new Stop(id, name, string(s, "type"), string(s, "cluster"), state, point(s.get("point")), teleport, watch(s.get("watch")));
	}

	private static Watch watch(JsonElement json)
	{
		if (json == null || !json.isJsonObject())
		{
			return null;
		}
		JsonObject w = json.getAsJsonObject();
		String kind = string(w, "kind");
		int[] regions = ints(w, "regions", 50);
		if (regions.length == 0)
		{
			return null;
		}
		if ("varbit".equals(kind))
		{
			Integer varbit = integer(w, "varbit");
			String impl = string(w, "impl");
			List<DoneRule> rules = new ArrayList<>();
			for (JsonObject r : objects(w, "doneWhen", 10))
			{
				String to = string(r, "to");
				Set<String> from = new HashSet<>();
				JsonElement f = r.get("from");
				if (f != null && f.isJsonArray())
				{
					for (JsonElement e : f.getAsJsonArray())
					{
						if (e.isJsonPrimitive() && e.getAsJsonPrimitive().isString() && CLASSES.contains(e.getAsString()))
						{
							from.add(e.getAsString());
						}
					}
				}
				if (to != null && CLASSES.contains(to) && !from.isEmpty())
				{
					rules.add(new DoneRule(from, to));
				}
			}
			// Only a farming patch varbit is read: any other (one the client would refuse, or one that isn't about farming)
			// leaves the stop unwatched (Skip stop by hand).
			if (varbit == null || !FARMING_VARBITS.contains(varbit) || impl == null || rules.isEmpty())
			{
				return null;
			}
			return new Watch(kind, varbit, -1, impl, regions, bounds(w.get("bounds")), rules, 0, null);
		}
		if ("birdhouse".equals(kind))
		{
			Integer varp = integer(w, "varp");
			Integer plane = integer(w, "plane");
			Point near = point(w.get("near"));
			// Only a bird house space's varp is read.
			if (varp == null || !BIRD_HOUSE_VARPS.contains(varp) || plane == null || near == null)
			{
				return null;
			}
			return new Watch(kind, -1, varp, null, regions, null, Collections.emptyList(), plane, near);
		}
		return null;
	}

	private static Bounds bounds(JsonElement json)
	{
		if (json == null || !json.isJsonObject())
		{
			return null;
		}
		JsonObject b = json.getAsJsonObject();
		List<Box> any = new ArrayList<>();
		List<Box> not = new ArrayList<>();
		for (JsonObject x : objects(b, "any", 20))
		{
			any.add(box(x));
		}
		for (JsonObject x : objects(b, "not", 20))
		{
			not.add(box(x));
		}
		return any.isEmpty() ? null : new Bounds(any, not);
	}

	private static Box box(JsonObject b)
	{
		return new Box(integer(b, "minX"), integer(b, "maxX"), integer(b, "minY"), integer(b, "maxY"), integer(b, "plane"));
	}

	private static Map<String, List<Range>> tables(JsonElement json)
	{
		Map<String, List<Range>> out = new HashMap<>();
		if (json == null || !json.isJsonObject())
		{
			return out;
		}
		for (Map.Entry<String, JsonElement> e : json.getAsJsonObject().entrySet())
		{
			if (!e.getValue().isJsonArray())
			{
				continue;
			}
			List<Range> rows = new ArrayList<>();
			for (JsonElement row : e.getValue().getAsJsonArray())
			{
				if (!row.isJsonArray() || row.getAsJsonArray().size() != 3)
				{
					continue;
				}
				JsonArray r = row.getAsJsonArray();
				try
				{
					String cls = r.get(2).getAsString();
					if (CLASSES.contains(cls))
					{
						rows.add(new Range(r.get(0).getAsInt(), r.get(1).getAsInt(), cls));
					}
				}
				catch (RuntimeException ex)
				{
					// a bad row is left out
				}
			}
			out.put(e.getKey(), Collections.unmodifiableList(rows));
		}
		return out;
	}

	private static Point point(JsonElement json)
	{
		if (json == null || !json.isJsonObject())
		{
			return null;
		}
		JsonObject p = json.getAsJsonObject();
		Integer x = integer(p, "x");
		Integer y = integer(p, "y");
		Integer plane = integer(p, "plane");
		return x == null || y == null || plane == null || plane < 0 || plane > 3 ? null : new Point(x, y, plane);
	}

	private static List<JsonObject> objects(JsonObject o, String key, int max)
	{
		List<JsonObject> out = new ArrayList<>();
		JsonElement a = o.get(key);
		if (a == null || !a.isJsonArray())
		{
			return out;
		}
		for (JsonElement e : a.getAsJsonArray())
		{
			if (out.size() >= max)
			{
				break;
			}
			if (e.isJsonObject())
			{
				out.add(e.getAsJsonObject());
			}
		}
		return out;
	}

	/** The whole numbers in a list (at most `max`); anything else in it is left out. */
	private static int[] ints(JsonObject o, String key, int max)
	{
		JsonElement a = o.get(key);
		if (a == null || !a.isJsonArray())
		{
			return new int[0];
		}
		List<Integer> out = new ArrayList<>();
		for (JsonElement e : a.getAsJsonArray())
		{
			Integer i = integer(e);
			if (i != null && out.size() < max)
			{
				out.add(i);
			}
		}
		return out.stream().mapToInt(Integer::intValue).toArray();
	}

	/** Item ids: whole numbers from 0 up, each once, at most `max`. */
	private static int[] itemIds(JsonObject o, String key, int max)
	{
		Set<Integer> out = new LinkedHashSet<>();
		for (int id : ints(o, key, Integer.MAX_VALUE))
		{
			if (id >= 0 && out.size() < max)
			{
				out.add(id);
			}
		}
		return out.stream().mapToInt(Integer::intValue).toArray();
	}

	private static String name(JsonObject o)
	{
		return name(o, "name");
	}

	private static String name(JsonObject o, String key)
	{
		String s = string(o, key);
		if (s == null)
		{
			return null;
		}
		String clean = NextStep.clean(s, MAX_NAME);
		return clean.isEmpty() ? null : clean;
	}

	private static String string(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isString() ? e.getAsString() : null;
	}

	private static Integer integer(JsonObject o, String key)
	{
		return integer(o.get(key));
	}

	private static Integer integer(JsonElement e)
	{
		if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber())
		{
			return null;
		}
		double d = e.getAsDouble();
		return d == Math.rint(d) && d >= Integer.MIN_VALUE && d <= Integer.MAX_VALUE ? (int) d : null;
	}

	private static Long longValue(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber())
		{
			return null;
		}
		double d = e.getAsDouble();
		return d == Math.rint(d) && Math.abs(d) < 9.0e15 ? e.getAsLong() : null;
	}

	private static Boolean bool(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isBoolean() ? e.getAsBoolean() : null;
	}
}

package com.ironwise;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.Response;

/**
 * "Mark step done" and "Skip step" from the Next step box: one POST to Ironwise's /api/guide/tick
 * on OkHttp's thread pool, with the same client and token as syncing (new in 0.4.0).
 */
@Singleton
class GuideClient
{
	static final String DONE = "done";
	static final String SKIP = "skip";

	static final String NOT_SYNCED = "Ironwise hasn't had a sync of this account from this device yet.";
	static final String NO_GUIDE = "this Ironwise app can't mark guide steps.";

	interface Listener
	{
		void done(Result result);
	}

	static final class Result
	{
		final boolean ok;
		/** Why it didn't work (when not ok). */
		final String message;
		/** The step after this one; null when there's none (or when not ok). */
		final NextStep next;

		private Result(boolean ok, String message, NextStep next)
		{
			this.ok = ok;
			this.message = message;
			this.next = next;
		}

		static Result failed(String message)
		{
			return new Result(false, message, null);
		}
	}

	private final SyncClient syncClient;
	private final Gson gson;

	@Inject
	GuideClient(SyncClient syncClient, Gson gson)
	{
		this.syncClient = syncClient;
		this.gson = gson;
	}

	static HttpUrl tickUrl(String address)
	{
		return SyncClient.appUrl(address, "/api/guide/tick");
	}

	/** The body Ironwise expects: {accountHash, stepId, action}. The hash is a string, as in syncs. */
	String body(GuideState.Tick tick)
	{
		JsonObject o = new JsonObject();
		o.addProperty("accountHash", tick.accountHash);
		o.addProperty("stepId", tick.stepId);
		o.addProperty("action", tick.action);
		return gson.toJson(o);
	}

	void send(HttpUrl url, String token, GuideState.Tick tick, Listener listener)
	{
		// The sync's client: redirects aren't followed, so the token only goes to the address the player set.
		syncClient.http.newCall(SyncClient.post(url, token, body(tick))).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				listener.done(Result.failed("can't reach the app (" + e.getMessage() + ")"));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				Result r;
				try
				{
					r = result(response.code(), SyncClient.bodyOf(response));
				}
				catch (IOException e)
				{
					r = Result.failed("couldn't read the app's answer (" + e.getMessage() + ")");
				}
				catch (RuntimeException e)
				{
					r = Result.failed("unexpected answer from the app");
				}
				finally
				{
					response.close();
				}
				listener.done(r);
			}
		});
	}

	Result result(int code, String body)
	{
		JsonObject answer = ironwise(body);
		String message = messageOf(answer);
		if (code >= 200 && code < 300)
		{
			if (answer == null || !isTrue(answer.get("ok")))
			{
				return Result.failed(SyncClient.NOT_IRONWISE);
			}
			// No "next" (or one Ironwise's plugin can't read): there's no step to show after this one.
			return new Result(true, null, NextStep.parse(answer.get("next")));
		}
		if (code >= 300 && code < 400)
		{
			return Result.failed("that address redirects somewhere else. Use the app's main address.");
		}
		if (code == 401 || code == 403)
		{
			if (answer == null)
			{
				return Result.failed(SyncClient.LOGIN);
			}
			return Result.failed(message != null ? message : code == 401 ? SyncClient.BAD_TOKEN : NOT_SYNCED);
		}
		if (code == 404)
		{
			return Result.failed(message != null ? message : NO_GUIDE);
		}
		return Result.failed(message != null ? message : "the app answered " + code);
	}

	/** Ironwise's JSON answer ({"ok": ...}), or null if the body is something else. */
	private JsonObject ironwise(String body)
	{
		try
		{
			JsonObject o = gson.fromJson(body, JsonObject.class);
			JsonElement ok = o == null ? null : o.get("ok");
			return ok != null && ok.isJsonPrimitive() && ok.getAsJsonPrimitive().isBoolean() ? o : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static boolean isTrue(JsonElement e)
	{
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isBoolean() && e.getAsBoolean();
	}

	private static String messageOf(JsonObject answer)
	{
		JsonElement m = answer == null ? null : answer.get("message");
		if (m == null || !m.isJsonPrimitive() || !m.getAsJsonPrimitive().isString())
		{
			return null;
		}
		String s = NextStep.clean(m.getAsString(), 200);
		return s.isEmpty() ? null : s;
	}
}

package com.ironwise;

import javax.inject.Singleton;

/**
 * The guide step shown in the Next step box, and the one "Mark step done"/"Skip step" at a time.
 * Answers that belong to an earlier account or login are dropped, and so is a sync answer that may
 * have been worked out before the latest mark reached Ironwise.
 */
@Singleton
class GuideState
{
	/** One "Mark step done" or "Skip step" on its way to Ironwise. */
	static final class Tick
	{
		final int session;
		final String accountHash;
		final String stepId;
		/** "done" or "skip". */
		final String action;

		Tick(int session, String accountHash, String stepId, String action)
		{
			this.session = session;
			this.accountHash = accountHash;
			this.stepId = stepId;
			this.action = action;
		}
	}

	private NextStep step;
	/** The account the step belongs to. */
	private String accountHash;
	/** Changes when the account changes or the player logs out, so late answers can't show another account's step. */
	private int session;
	private boolean ticking;
	/** When Ironwise last answered a mark (plugin clock); 0 if not this session. */
	private long tickAnsweredAt;

	synchronized NextStep step()
	{
		return step;
	}

	synchronized int session()
	{
		return session;
	}

	/** Forget the step (logout, another account, plugin stopped). */
	synchronized void clear()
	{
		step = null;
		accountHash = null;
		session++;
		ticking = false;
		tickAnsweredAt = 0;
	}

	/**
	 * A sync that got through. {@code sentAt} is when it was sent: a sync sent before the last mark
	 * was answered may have been worked out before the mark, so the mark's answer stays.
	 */
	synchronized void synced(int session, String accountHash, long sentAt, NextStep.Reply reply)
	{
		if (session != this.session || !reply.said || sentAt < tickAnsweredAt)
		{
			return;
		}
		this.step = reply.step;
		this.accountHash = accountHash;
	}

	/** Starts marking the step shown; null if nothing is shown or a mark is already on its way. */
	synchronized Tick startTick(String action)
	{
		if (ticking || step == null || accountHash == null)
		{
			return null;
		}
		ticking = true;
		return new Tick(session, accountHash, step.stepId, action);
	}

	/**
	 * Ironwise's answer to a mark: when it went through, its next step (null: none) replaces the one
	 * shown. False if the answer is for an earlier account or login, and was dropped.
	 */
	synchronized boolean ticked(Tick tick, long now, boolean ok, NextStep next)
	{
		if (tick.session != session)
		{
			return false;
		}
		ticking = false;
		if (ok)
		{
			step = next;
			tickAnsweredAt = now;
		}
		return true;
	}
}

