package com.ironwise;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.AccountHashChanged;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import okhttp3.HttpUrl;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Ironwise",
	description = "Syncs your account to Ironwise, a private invite-only Ironman planner, shows your next guide step, and guides your farm runs",
	tags = {"ironman", "sync", "planner", "progress", "bank", "clog", "guide", "companion", "farming"}
)
public class IronwisePlugin extends Plugin
{
	static final String VERSION = "0.5.0";

	private static final Logger log = LoggerFactory.getLogger(IronwisePlugin.class);

	/** Let the game settle after login before reading variables. */
	private static final int LOGIN_SETTLE_TICKS = 5;
	/** At most one sync per 30 seconds while things change. */
	private static final long MIN_INTERVAL_MS = 30_000L;
	/** Send anyway every 10 minutes while logged in, so Ironwise can show the account as live. */
	private static final long HEARTBEAT_MS = 10 * 60_000L;
	/** Waits after failures: 1, 2, 4, 8, then 15 minutes. */
	private static final long MAX_BACKOFF_MS = 15 * 60_000L;

	private static final Set<Integer> VARBITS = new HashSet<>();
	private static final Set<Integer> VARPS = new HashSet<>();

	static
	{
		Arrays.stream(TrackedVars.VARBITS).forEach(VARBITS::add);
		Arrays.stream(TrackedVars.VARPS).forEach(VARPS::add);
	}

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private IronwiseConfig config;

	@Inject
	private PayloadBuilder builder;

	@Inject
	private SyncClient syncClient;

	@Inject
	private CollectionLogState collectionLog;

	@Inject
	private CollectionLogReader collectionLogReader;

	@Inject
	private Gson gson;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private NextStepOverlay nextStepOverlay;

	@Inject
	private GuideState guide;

	@Inject
	private GuideClient guideClient;

	@Inject
	private ConfigManager configManager;

	/** Farm runs (new in 0.5.0): the side panel, auto-advance, Shortest Path and the run's actions. */
	@Inject
	private FarmRunController farmRuns;

	@Inject
	private FarmRunOverlay farmRunOverlay;

	@Inject
	private BankHighlightOverlay bankHighlight;

	private int ticksLoggedIn;
	private boolean dirty;
	private long lastAttemptAt;
	private long nextAttemptAt;
	private long backoffMs;
	private int failures;
	private String lastSentSignature;
	private long lastSentAt;
	private boolean announced;
	/** A problem only the player can fix (token, address, plugin version): wait for a settings change. */
	private String stopped;
	private volatile boolean inFlight;
	/** A farm run fault has been logged this session (once is enough to see it; the rest would flood the log). */
	private boolean farmRunFaultLogged;

	/** The clock (a method so tests can move time on). */
	long now()
	{
		return System.currentTimeMillis();
	}

	@Provides
	IronwiseConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(IronwiseConfig.class);
	}

	@Override
	protected void startUp()
	{
		resetSession();
		overlayManager.add(nextStepOverlay);
		overlayManager.add(farmRunOverlay);
		overlayManager.add(bankHighlight);
		farmRuns.startUp();
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(nextStepOverlay);
		overlayManager.remove(farmRunOverlay);
		overlayManager.remove(bankHighlight);
		farmRuns.shutDown();
		resetSession();
	}

	private void resetSession()
	{
		builder.reset();
		collectionLogReader.reset();
		guide.clear();
		ticksLoggedIn = 0;
		dirty = true;
		lastSentSignature = null;
		lastSentAt = 0;
		announced = false;
		stopped = null;
		farmRunFaultLogged = false;
		clearBackoff();
	}

	private void clearBackoff()
	{
		nextAttemptAt = 0;
		backoffMs = 0;
		failures = 0;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			dirty = true;
			// The side panel stops saying "Log in" and waits for Ironwise.
			farmRuns.refreshPanel();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			ticksLoggedIn = 0;
			collectionLogReader.reset();
			if (event.getGameState() == GameState.LOGIN_SCREEN)
			{
				// Logged out: the next login may be another account.
				guide.clear();
				farmRuns.loggedOut();
			}
		}
		if (event.getGameState() == GameState.HOPPING || event.getGameState() == GameState.LOADING)
		{
			// Farm patch readings from before the hop or the loading screen can linger: every watched stop settles again.
			farmRuns.hopped();
		}
	}

	@Subscribe
	public void onAccountHashChanged(AccountHashChanged event)
	{
		builder.reset();
		collectionLogReader.reset();
		guide.clear();
		farmRuns.reset();
		lastSentSignature = null;
		announced = false;
		dirty = true;
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		// Shortest Path switched on or off: the side panel's note about it follows.
		clientThread.invokeLater(() -> farmRuns.pluginsChanged());
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (PayloadBuilder.isTrackedContainer(event.getContainerId()))
		{
			builder.onContainerChanged(event.getContainerId(), event.getItemContainer(), now());
			dirty = true;
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		dirty = true;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() == VarPlayerID.QP)
		{
			builder.questsChanged();
		}
		if (VARBITS.contains(event.getVarbitId()) || VARPS.contains(event.getVarpId()))
		{
			dirty = true;
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		collectionLogReader.onScriptPreFired(event);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (collectionLogReader.onChatMessage(event, now()))
		{
			dirty = true;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (IronwiseConfig.GROUP.equals(event.getGroup()))
		{
			if (IronwiseConfig.SHOW_NEXT_STEP.equals(event.getKey()))
			{
				// Only the Next step box (its setting, or Hide on the box): nothing about syncing changed,
				// so there's nothing to send again.
				return;
			}
			if (IronwiseConfig.FARM_RUN_KEYS.contains(event.getKey()))
			{
				// A farm run setting (or Hide on the run box): nothing about syncing changed, so there's nothing
				// to send again. The farm runs follow it on the client thread (this may run on the settings
				// panel's): switched off, the runs, the path this plugin drew and the sidebar button go.
				clientThread.invokeLater(() -> farmRuns.settingsChanged());
				return;
			}
			if (IronwiseConfig.SYNC_COLLECTION_LOG.equals(event.getKey()))
			{
				// Only what's read changed, not where or how to sync. CollectionLogReader checks the setting
				// before every read, on the client thread (this may run on the settings panel's): unticked,
				// it reads nothing more and drops what it read before the next sync is built, which then has
				// no collection log section (Ironwise keeps what it had); ticked, the log is read once the
				// player opens it.
				return;
			}
			if ("serverUrl".equals(event.getKey()) || "token".equals(event.getKey()))
			{
				// Maybe another Ironwise: show no step or farm run until it answers.
				guide.clear();
				clientThread.invokeLater(() -> farmRuns.addressChanged());
			}
			else if ("syncEnabled".equals(event.getKey()))
			{
				// Farm runs work while syncing is on: unticked, they go (and the sidebar button with them).
				clientThread.invokeLater(() -> farmRuns.settingsChanged());
			}
			// New address or token: try again straight away.
			stopped = null;
			lastSentSignature = null;
			announced = false;
			clearBackoff();
			dirty = true;
			return;
		}
		for (String group : PayloadBuilder.SAVED_GROUPS)
		{
			if (group.equals(event.getGroup()))
			{
				dirty = true;
				return;
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		// Before the payload is built: with Sync collection log unticked, this drops anything read of the log.
		if (collectionLogReader.onGameTick(now()))
		{
			dirty = true;
		}
		int listed = collectionLogReader.takeFinishedListing();
		if (!config.syncEnabled())
		{
			return;
		}
		if (listed >= 0)
		{
			say("Ironwise: read your collection log (" + listed + " items).");
		}
		// Farm runs (0.5.0): polled and watched every tick on normal worlds, also while a sync is on its way or waiting
		// to go. Once syncing has stopped on a problem only the player can fix, they send nothing to that address either
		// until the settings change, and the side panel says why. A fault in them (a varbit the client refuses, say)
		// never stops the sync or the Next step box: it's logged once a session.
		if (RuneScapeProfileType.getCurrent(client) == RuneScapeProfileType.STANDARD)
		{
			try
			{
				farmRuns.onGameTick(now(), stopped);
			}
			catch (RuntimeException e)
			{
				if (!farmRunFaultLogged)
				{
					farmRunFaultLogged = true;
					log.warn("Ironwise farm runs failed on a game tick; syncing carries on", e);
				}
			}
		}
		if (++ticksLoggedIn < LOGIN_SETTLE_TICKS || stopped != null || inFlight)
		{
			return;
		}
		// Leagues, Deadman, beta and other special worlds aren't your real account.
		if (RuneScapeProfileType.getCurrent(client) != RuneScapeProfileType.STANDARD)
		{
			return;
		}
		long now = now();
		boolean heartbeat = now - lastSentAt >= HEARTBEAT_MS;
		if ((!dirty && !heartbeat) || now < nextAttemptAt || now - lastAttemptAt < MIN_INTERVAL_MS)
		{
			return;
		}

		HttpUrl url = SyncClient.syncUrl(config.serverUrl());
		String token = config.token() == null ? "" : config.token().trim();
		if (url == null || token.isEmpty())
		{
			stop(url == null
				? "Ironwise: set your Ironwise address in the plugin settings (it must start with https://)."
				: "Ironwise: paste your device token in the plugin settings.");
			return;
		}

		SyncPayload payload = builder.build(VERSION, now);
		if (payload == null)
		{
			return;
		}
		dirty = false;
		// Compare without the timestamp: only send when something changed (or for the heartbeat).
		payload.sentAt = 0;
		String signature = gson.toJson(payload);
		if (!heartbeat && signature.equals(lastSentSignature))
		{
			return;
		}
		payload.sentAt = now;
		String json = gson.toJson(payload);
		SyncPayload.Account account = payload.account;
		List<Object[]> added = payload.collectionLog == null ? null : payload.collectionLog.added;
		int session = guide.session();

		lastAttemptAt = now;
		inFlight = true;
		try
		{
			syncClient.send(url, token, json, result -> clientThread.invokeLater(() -> finished(result, signature, now, account, added, session)));
		}
		catch (RuntimeException e)
		{
			finished(new SyncClient.Result(SyncClient.Outcome.RETRY, "couldn't send (" + e.getMessage() + ")"), signature, now, account, added, session);
		}
	}

	/** Back on the client thread after a sync. */
	private void finished(SyncClient.Result result, String signature, long sentAt, SyncPayload.Account account, List<Object[]> added, int session)
	{
		inFlight = false;
		String rsn = account.rsn;
		switch (result.outcome)
		{
			case OK:
				lastSentSignature = signature;
				lastSentAt = sentAt;
				// Ironwise has the "new item" lines now: don't send them again.
				collectionLog.addedSent(added);
				guide.synced(session, account.hash, sentAt, result.guide);
				clearBackoff();
				if (!announced)
				{
					announced = true;
					say("Ironwise: syncing " + rsn + ".");
				}
				break;
			case UNAUTHORIZED:
			case WRONG_ADDRESS:
				stop("Ironwise: " + result.message);
				break;
			case REJECTED:
				stop("Ironwise: the app couldn't use the sync: " + result.message);
				break;
			case RETRY:
			default:
				failures++;
				backoffMs = backoffMs == 0 ? 60_000L : Math.min(backoffMs * 2, MAX_BACKOFF_MS);
				nextAttemptAt = now() + backoffMs;
				dirty = true;
				log.debug("Ironwise sync failed ({}), retrying in {}s", result.message, backoffMs / 1000);
				if (failures == 3)
				{
					say("Ironwise: " + result.message + ". Still trying.");
				}
				break;
		}
	}

	/**
	 * "Mark step done" ({@link GuideClient#DONE}) or "Skip step" ({@link GuideClient#SKIP}) on the Next
	 * step box, on the client thread. Tells Ironwise; its answer's next step replaces the one shown.
	 */
	void guideAction(String action)
	{
		if (!config.syncEnabled())
		{
			return;
		}
		GuideState.Tick tick = guide.startTick(action);
		if (tick == null)
		{
			// Nothing shown, or the last click is still on its way.
			return;
		}
		String what = GuideClient.SKIP.equals(action) ? "skip the step" : "mark the step done";
		HttpUrl url = GuideClient.tickUrl(config.serverUrl());
		String token = config.token() == null ? "" : config.token().trim();
		if (url == null || token.isEmpty())
		{
			ticked(tick, what, GuideClient.Result.failed(url == null
				? "set your Ironwise address in the plugin settings (it must start with https://)."
				: "paste your device token in the plugin settings."));
			return;
		}
		try
		{
			guideClient.send(url, token, tick, result -> clientThread.invokeLater(() -> ticked(tick, what, result)));
		}
		catch (RuntimeException e)
		{
			ticked(tick, what, GuideClient.Result.failed("couldn't send (" + e.getMessage() + ")"));
		}
	}

	/**
	 * "Hide" on the Next step box, on the client thread: unticks Show next guide step and says in chat
	 * how to bring the box back. Nothing is sent to Ironwise.
	 */
	void hideNextStep()
	{
		NextStepOverlay.hide((group, key, value) -> configManager.setConfiguration(group, key, value), client);
	}

	/** Back on the client thread after a mark. */
	private void ticked(GuideState.Tick tick, String what, GuideClient.Result result)
	{
		if (guide.ticked(tick, now(), result.ok, result.next) && !result.ok)
		{
			// The player asked for this, so they hear why it didn't work even with chat messages off.
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Ironwise: couldn't " + what + ": " + result.message, null);
		}
	}

	private void stop(String message)
	{
		stopped = message;
		// Ironwise stops hearing from this account until the settings change, so the step shown can't
		// follow it any more: hide it rather than leave an old step up.
		guide.clear();
		log.debug(message);
		say(message);
	}

	private void say(String message)
	{
		if (config.chatMessages())
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
		}
	}
}

package com.ironwise;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.util.regex.Pattern;

/**
 * The account's next step in the BRUHsailer guide, as Ironwise works it out (new in 0.4.0). It comes
 * in the "guide" field of a sync answer and the "next" field of a /api/guide/tick answer. Ironwise
 * decides everything; the plugin only shows it.
 */
final class NextStep
{
	static final int MAX_TEXT = 240;
	private static final int MAX_PLACE = 100;
	private static final int MAX_STEPS = 100_000;
	private static final Pattern STEP_ID = Pattern.compile("^[0-9a-f]{16}(-\\d{1,6})?$");
	/** Colour tags would recolour the overlay's text; nothing from the guide should. */
	private static final Pattern COL_TAG = Pattern.compile("</?col(=[^>]*)?>", Pattern.CASE_INSENSITIVE);

	/** "main" or "landlubber". */
	final String variant;
	final String stepId;
	/** 1-based position in the guide. */
	final int n;
	final int total;
	final String chapter;
	final String section;
	/**
	 * Where the step is in the guide, as Ironwise writes it: "Ch 2 \u00B7 2.2" for the second section of
	 * the second chapter (new in 0.4.1). Null from an Ironwise that doesn't send it.
	 */
	final String where;
	final String text;
	/** Steps done so far. */
	final int done;
	/** A step Ironwise thinks you skipped earlier (every later step is done). */
	final boolean behind;

	NextStep(String variant, String stepId, int n, int total, String chapter, String section, String where, String text, int done, boolean behind)
	{
		this.variant = variant;
		this.stepId = stepId;
		this.n = n;
		this.total = total;
		this.chapter = chapter;
		this.section = section;
		this.where = where;
		this.text = text;
		this.done = done;
		this.behind = behind;
	}

	/** What an answer said about the guide. */
	static final class Reply
	{
		/** The answer had no such field: keep whatever is shown. */
		static final Reply NOTHING = new Reply(false, null);

		final boolean said;
		/** The step to show, or null for none (the field was null or unusable). */
		final NextStep step;

		private Reply(boolean said, NextStep step)
		{
			this.said = said;
			this.step = step;
		}
	}

	/** The step in field {@code key} of an Ironwise JSON answer. Never throws. */
	static Reply fromBody(Gson gson, String body, String key)
	{
		JsonObject object;
		try
		{
			object = gson.fromJson(body, JsonObject.class);
		}
		catch (RuntimeException e)
		{
			return Reply.NOTHING;
		}
		if (object == null || !object.has(key))
		{
			return Reply.NOTHING;
		}
		return new Reply(true, parse(object.get(key)));
	}

	/** A step from its JSON, or null if anything about it is missing or out of range. */
	static NextStep parse(JsonElement json)
	{
		if (json == null || !json.isJsonObject())
		{
			return null;
		}
		JsonObject o = json.getAsJsonObject();
		String variant = string(o, "variant");
		String stepId = string(o, "stepId");
		String state = string(o, "state");
		Integer n = integer(o, "n");
		Integer total = integer(o, "total");
		Integer done = integer(o, "done");
		String chapter = string(o, "chapter");
		String section = string(o, "section");
		String text = string(o, "text");
		if (!"main".equals(variant) && !"landlubber".equals(variant))
		{
			return null;
		}
		if (stepId == null || !STEP_ID.matcher(stepId).matches())
		{
			return null;
		}
		if (!"todo".equals(state) && !"behind".equals(state))
		{
			return null;
		}
		if (n == null || total == null || done == null || n < 1 || total < n || total > MAX_STEPS || done < 0 || done > total)
		{
			return null;
		}
		if (chapter == null || section == null || text == null)
		{
			return null;
		}
		text = clean(text, MAX_TEXT);
		if (text.isEmpty())
		{
			return null;
		}
		return new NextStep(variant, stepId, n, total, clean(chapter, MAX_PLACE), clean(section, MAX_PLACE),
			where(o), text, done, "behind".equals(state));
	}

	/** The optional "where": left out, null, blank or not text all mean none (the step still shows). */
	private static String where(JsonObject o)
	{
		String where = string(o, "where");
		if (where == null)
		{
			return null;
		}
		where = clean(where, MAX_PLACE);
		return where.isEmpty() ? null : where;
	}

	/**
	 * Plain one-line text the game's fonts can draw: no control characters or colour tags, curly quotes
	 * and dashes as plain ones (RuneLite's regular font has no curly quotes), single spaces, at most
	 * {@code max} characters.
	 */
	static String clean(String s, int max)
	{
		StringBuilder b = new StringBuilder(s.length());
		for (int i = 0; i < s.length(); i++)
		{
			char c = s.charAt(i);
			switch (c)
			{
				case '\u2018':
				case '\u2019':
				case '\u201A':
				case '\u201B':
				case '\u2032':
					b.append('\'');
					break;
				case '\u201C':
				case '\u201D':
				case '\u201E':
				case '\u2033':
					b.append('"');
					break;
				case '\u2010':
				case '\u2011':
				case '\u2012':
				case '\u2013':
				case '\u2212':
				case '\u2022':
					b.append('-');
					break;
				case '\u2192':
					b.append("->");
					break;
				case '\u2190':
					b.append("<-");
					break;
				case '\u2265':
					b.append(">=");
					break;
				case '\u2264':
					b.append("<=");
					break;
				default:
					if (Character.isISOControl(c) || Character.isWhitespace(c) || Character.isSpaceChar(c))
					{
						b.append(' ');
					}
					else if (Character.isSurrogate(c) || Character.getType(c) == Character.FORMAT)
					{
						// Emoji and invisible formatting characters: nothing the game's fonts can draw.
					}
					else
					{
						b.append(c);
					}
			}
		}
		String out = COL_TAG.matcher(b).replaceAll("").replaceAll(" {2,}", " ").trim();
		return out.length() <= max ? out : out.substring(0, max - 1).trim() + "\u2026";
	}

	private static String string(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isString() ? e.getAsString() : null;
	}

	private static Integer integer(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		if (e == null || !e.isJsonPrimitive())
		{
			return null;
		}
		JsonPrimitive p = e.getAsJsonPrimitive();
		if (!p.isNumber())
		{
			return null;
		}
		double d = p.getAsDouble();
		if (d != Math.rint(d) || d < Integer.MIN_VALUE || d > Integer.MAX_VALUE)
		{
			return null;
		}
		return (int) d;
	}
}

package com.ironwise;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.List;
import java.util.function.Predicate;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The Next step box (new in 0.4.0): the account's next BRUHsailer guide step, as Ironwise sent it.
 * Information only. Its menu entries are RuneLite overlay entries (Shift + right-click on the box):
 * two tell Ironwise the step is done or skipped, and Hide (0.4.1) turns the box off in the plugin's
 * settings. Nothing here acts in the game. While a farm run's box is up (0.5.0), this box steps aside.
 */
class NextStepOverlay extends OverlayPanel
{
	static final String TARGET = "Next step";
	static final String MARK_DONE = "Mark step done";
	static final String SKIP = "Skip step";
	static final String HIDE = "Hide";
	/** What Hide says in chat: the only way back is the setting, so it names it. */
	static final String HIDDEN = "Ironwise: Next step box hidden. Tick Show next guide step in the Ironwise settings to bring it back.";
	static final int WIDTH = 200;
	/** The step's text (Ironwise's short summary of it). */
	static final int TEXT_LINES = 3;
	/** Where the step is in the guide, muted. */
	static final int PLACE_LINES = 1;
	static final String ELLIPSIS = "\u2026";
	/** Left off the end of a line before the ellipsis, so it never reads "Lumbridge \u00B7..." or "then,...". */
	private static final String TRAILING = " \u00B7,;:";
	private static final Color MUTED = new Color(160, 160, 160);

	private final Client client;
	private final IronwiseConfig config;
	private final GuideState guide;
	/**
	 * The farm runs: while the run box is up it takes this corner, and this box steps aside (new in 0.5.0). Field
	 * injection keeps the constructor as it was; null in tests that build the box by hand.
	 */
	@Inject
	private FarmRunState farmRuns;

	@Inject
	NextStepOverlay(IronwisePlugin plugin, Client client, IronwiseConfig config, GuideState guide)
	{
		super(plugin);
		this.client = client;
		this.config = config;
		this.guide = guide;
		setPosition(OverlayPosition.TOP_RIGHT);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, MARK_DONE, TARGET, e -> plugin.guideAction(GuideClient.DONE));
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, SKIP, TARGET, e -> plugin.guideAction(GuideClient.SKIP));
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, HIDE, TARGET, e -> plugin.hideNextStep());
	}

	/** Writes one of the plugin's settings: RuneLite's ConfigManager in the game, a stand-in in tests. */
	interface Settings
	{
		void set(String group, String key, boolean value);
	}

	/**
	 * Hide: unticks Show next guide step, which hides the box at once, and says in chat how to bring it
	 * back. The player asked for it, so the line shows even with chat messages off. Only the setting
	 * changes: nothing goes to Ironwise and nothing happens in the game.
	 */
	static void hide(Settings settings, Client client)
	{
		settings.set(IronwiseConfig.GROUP, IronwiseConfig.SHOW_NEXT_STEP, false);
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", HIDDEN, null);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		NextStep step = guide.step();
		if (step == null || !config.showNextStep() || !config.syncEnabled()
			|| (farmRuns != null && FarmRunOverlay.showing(config, farmRuns.active()))
			|| client.getGameState() != GameState.LOGGED_IN
			|| RuneScapeProfileType.getCurrent(client) != RuneScapeProfileType.STANDARD)
		{
			return null;
		}

		// The player can resize the box; wrap to whatever width it has.
		Dimension size = getPreferredSize();
		int width = size != null && size.width > 0 ? size.width : WIDTH;
		panelComponent.setPreferredSize(new Dimension(width, 0));
		FontMetrics metrics = graphics.getFontMetrics();
		int inner = width - 2 * ComponentConstants.STANDARD_BORDER;
		Predicate<String> fits = s -> metrics.stringWidth(s) <= inner;

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(step.behind ? "Next step (skipped)" : "Next step")
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Step " + step.n + " of " + step.total)
			.build());
		for (String line : wrap(step.text, TEXT_LINES, fits))
		{
			panelComponent.getChildren().add(LineComponent.builder().left(line).build());
		}
		for (String line : wrap(place(step), PLACE_LINES, fits))
		{
			panelComponent.getChildren().add(LineComponent.builder().left(line).leftColor(MUTED).build());
		}
		return super.render(graphics);
	}

	/**
	 * Where the step is: Ironwise's "Ch 2 \u00B7 2.2" when it sends one, otherwise (an older Ironwise) the
	 * chapter and section titles joined by a middle dot, leaving out whichever is blank.
	 */
	static String place(NextStep step)
	{
		if (step.where != null && !step.where.isEmpty())
		{
			return step.where;
		}
		if (step.chapter.isEmpty())
		{
			return step.section;
		}
		return step.section.isEmpty() ? step.chapter : step.chapter + " \u00B7 " + step.section;
	}

	/**
	 * Word-wraps {@code text} into at most {@code maxLines} lines that each pass {@code fits}; if it
	 * doesn't all fit, the last line ends with "...". A word too long for a line is broken.
	 */
	static List<String> wrap(String text, int maxLines, Predicate<String> fits)
	{
		List<String> lines = new ArrayList<>();
		if (text == null || text.trim().isEmpty() || maxLines < 1)
		{
			return lines;
		}
		Deque<String> words = new ArrayDeque<>(Arrays.asList(text.trim().split("\\s+")));
		String line = "";
		while (!words.isEmpty())
		{
			String word = words.peekFirst();
			if (word.isEmpty())
			{
				words.pollFirst();
				continue;
			}
			String longer = line.isEmpty() ? word : line + " " + word;
			if (fits.test(longer))
			{
				line = longer;
				words.pollFirst();
				continue;
			}
			if (line.isEmpty())
			{
				// One word wider than the box: as much of it as fits (at least one character).
				int cut = 1;
				while (cut < word.length() - 1 && fits.test(word.substring(0, cut + 1)))
				{
					cut++;
				}
				line = word.substring(0, cut);
				words.pollFirst();
				if (cut < word.length())
				{
					words.addFirst(word.substring(cut));
				}
			}
			if (words.isEmpty())
			{
				break;
			}
			// The line is full and there's more to come.
			if (lines.size() == maxLines - 1)
			{
				lines.add(ellipsize(line, fits));
				return lines;
			}
			lines.add(line);
			line = "";
		}
		if (!line.isEmpty())
		{
			lines.add(line);
		}
		return lines;
	}

	/** The line with "..." on the end, shortened until it fits, and no separator just before the "...". */
	static String ellipsize(String line, Predicate<String> fits)
	{
		String s = stripTrailing(line);
		while (!s.isEmpty() && !fits.test(s + ELLIPSIS))
		{
			s = stripTrailing(s.substring(0, s.length() - 1));
		}
		return s + ELLIPSIS;
	}

	/** Without spaces, middle dots, commas, semicolons or colons at the end. */
	private static String stripTrailing(String s)
	{
		int end = s.length();
		while (end > 0 && TRAILING.indexOf(s.charAt(end - 1)) >= 0)
		{
			end--;
		}
		return s.substring(0, end);
	}
}

package com.ironwise;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.config.ConfigManager;

/**
 * Reads the logged-in account into a {@link SyncPayload}. Everything here runs on the client thread.
 */
@Singleton
class PayloadBuilder
{
	/** RuneLite config groups forwarded as they are: Time Tracking, kill counts, Kingdom of Miscellania. */
	static final String[] SAVED_GROUPS = {"timetracking", "killcount", "kingdomofmiscellania"};
	private static final int MAX_SAVED_KEYS = 2000;
	/** Quest states come from client scripts, so they're re-read on login, when quest points change, and every 10 minutes. */
	private static final long QUESTS_EVERY_MS = 10 * 60_000L;

	/** Containers Ironwise reads, by game inventory id. */
	private static final Map<Integer, String> CONTAINERS = new LinkedHashMap<>();

	static
	{
		CONTAINERS.put(InventoryID.BANK, "bank");
		CONTAINERS.put(InventoryID.INV, "inventory");
		CONTAINERS.put(InventoryID.WORN, "equipment");
		CONTAINERS.put(InventoryID.SEED_VAULT, "seedVault");
		CONTAINERS.put(InventoryID.LOOTING_BAG, "lootingBag");
		CONTAINERS.put(InventoryID.INV_GROUP_TEMP, "groupStorage");
	}

	private final Client client;
	private final ConfigManager configManager;
	private final CollectionLogState collectionLog;

	/** When the game last sent each container this session (the bank only arrives when it's opened). */
	private final Map<Integer, Long> seenAt = new HashMap<>();
	/** The last copy of each container, for when the client no longer holds it. */
	private final Map<Integer, SyncPayload.Container> lastCopy = new HashMap<>();
	private SyncPayload.Quests quests;
	private long questsReadAt;
	private boolean questsStale = true;

	@Inject
	PayloadBuilder(Client client, ConfigManager configManager, CollectionLogState collectionLog)
	{
		this.client = client;
		this.configManager = configManager;
		this.collectionLog = collectionLog;
	}

	static boolean isTrackedContainer(int containerId)
	{
		return CONTAINERS.containsKey(containerId);
	}

	/** A new account (or the plugin restarting): forget this session's containers, quests and collection log. */
	void reset()
	{
		seenAt.clear();
		lastCopy.clear();
		quests = null;
		questsStale = true;
		collectionLog.reset();
	}

	void questsChanged()
	{
		questsStale = true;
	}

	void onContainerChanged(int containerId, ItemContainer container, long now)
	{
		if (!CONTAINERS.containsKey(containerId) || container == null)
		{
			return;
		}
		seenAt.put(containerId, now);
		lastCopy.put(containerId, copy(container, now));
	}

	/** The account as it is now, or null if the player isn't fully logged in yet. */
	SyncPayload build(String version, long now)
	{
		Player player = client.getLocalPlayer();
		long hash = client.getAccountHash();
		if (player == null || player.getName() == null || hash == -1)
		{
			return null;
		}

		SyncPayload p = new SyncPayload();
		p.plugin = version;
		p.sentAt = now;
		p.account = new SyncPayload.Account(Long.toString(hash), player.getName(), client.getWorld());
		p.skills = skills();
		p.quests = quests(now);
		p.containers = containers(now);
		p.varbits = new LinkedHashMap<>();
		for (int id : TrackedVars.VARBITS)
		{
			p.varbits.put(Integer.toString(id), client.getVarbitValue(id));
		}
		p.varps = new LinkedHashMap<>();
		for (int id : TrackedVars.VARPS)
		{
			p.varps.put(Integer.toString(id), client.getVarpValue(id));
		}
		p.saved = saved();
		p.collectionLog = collectionLog.toPayload();
		return p;
	}

	private Map<String, SyncPayload.SkillEntry> skills()
	{
		Map<String, SyncPayload.SkillEntry> out = new LinkedHashMap<>();
		for (Skill skill : Skill.values())
		{
			if (skill == null || "Overall".equals(skill.getName()))
			{
				continue;
			}
			out.put(skill.getName(), new SyncPayload.SkillEntry(client.getRealSkillLevel(skill), client.getSkillExperience(skill)));
		}
		return out;
	}

	private SyncPayload.Quests quests(long now)
	{
		if (quests != null && !questsStale && now - questsReadAt < QUESTS_EVERY_MS)
		{
			return quests;
		}
		List<SyncPayload.QuestEntry> entries = new ArrayList<>();
		for (Quest quest : Quest.values())
		{
			QuestState state;
			try
			{
				state = quest.getState(client);
			}
			catch (RuntimeException e)
			{
				// A quest whose script fails is left out; Ironwise treats it as unknown.
				continue;
			}
			if (state != null)
			{
				entries.add(new SyncPayload.QuestEntry(quest.name(), quest.getName(), state.name()));
			}
		}
		quests = new SyncPayload.Quests(client.getVarpValue(VarPlayerID.QP), entries);
		questsReadAt = now;
		questsStale = false;
		return quests;
	}

	private Map<String, SyncPayload.Container> containers(long now)
	{
		Map<String, SyncPayload.Container> out = new LinkedHashMap<>();
		for (Map.Entry<Integer, String> e : CONTAINERS.entrySet())
		{
			int id = e.getKey();
			ItemContainer live = client.getItemContainer(id);
			if (live != null)
			{
				out.put(e.getValue(), copy(live, seenAt.getOrDefault(id, now)));
			}
			else if (lastCopy.containsKey(id))
			{
				out.put(e.getValue(), lastCopy.get(id));
			}
		}
		return out;
	}

	private static SyncPayload.Container copy(ItemContainer container, long seen)
	{
		List<int[]> items = new ArrayList<>();
		for (Item item : container.getItems())
		{
			// Skips empty slots and bank placeholders.
			if (item != null && item.getId() > 0 && item.getQuantity() > 0)
			{
				items.add(new int[]{item.getId(), item.getQuantity()});
			}
		}
		return new SyncPayload.Container(seen, items);
	}

	private Map<String, Map<String, String>> saved()
	{
		Map<String, Map<String, String>> out = new LinkedHashMap<>();
		String profile = configManager.getRSProfileKey();
		if (profile == null)
		{
			return out;
		}
		for (String group : SAVED_GROUPS)
		{
			Map<String, String> values = new LinkedHashMap<>();
			for (String key : configManager.getRSProfileConfigurationKeys(group, profile, ""))
			{
				if (values.size() >= MAX_SAVED_KEYS)
				{
					break;
				}
				String value = configManager.getConfiguration(group, profile, key);
				if (value != null)
				{
					values.put(key, value);
				}
			}
			if (!values.isEmpty())
			{
				out.put(group, values);
			}
		}
		return out;
	}
}

package com.ironwise;

import java.util.Collections;
import java.util.Objects;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;

/**
 * Draws the way to the run's current stop with the Shortest Path plugin (Skretzo/shortest-path, its plugin-message API
 * at 3086b0bb178dde72c9622709a701aee75ba8337f: ShortestPathPlugin#onPluginMessage): a PluginMessage in namespace
 * "shortestpath" named "path" with data {"target": WorldPoint} sets the target (from the player's position), and
 * "clear" removes it (new in 0.5.0). Only when Shortest Path is enabled, only when the target changes, and "clear" only
 * after this plugin set one. Nothing happens if it isn't installed. (Shortest Path drops its own target once the player
 * is there.) It's a message between plugins: nothing is sent anywhere and nothing happens in the game.
 */
@Singleton
class ShortestPath
{
	static final String NAMESPACE = "shortestpath";
	static final String PATH = "path";
	static final String CLEAR = "clear";
	static final String TARGET = "target";
	static final String PLUGIN_NAME = "Shortest Path";

	private final Consumer<PluginMessage> post;
	private final BooleanSupplier enabled;
	/** The target this plugin last set; null: none. */
	private FarmRuns.Point target;

	@Inject
	ShortestPath(EventBus eventBus, PluginManager pluginManager)
	{
		this(eventBus::post, () -> installedAndOn(pluginManager));
	}

	/** Where messages go and whether Shortest Path is on: RuneLite's event bus and plugin manager, or stand-ins in tests. */
	ShortestPath(Consumer<PluginMessage> post, BooleanSupplier enabled)
	{
		this.post = post;
		this.enabled = enabled;
	}

	static PluginMessage path(FarmRuns.Point p)
	{
		return new PluginMessage(NAMESPACE, PATH, Collections.singletonMap(TARGET, new WorldPoint(p.x, p.y, p.plane)));
	}

	static PluginMessage clear()
	{
		return new PluginMessage(NAMESPACE, CLEAR);
	}

	private static boolean installedAndOn(PluginManager pluginManager)
	{
		for (Plugin p : pluginManager.getPlugins())
		{
			if (PLUGIN_NAME.equals(p.getName()) && pluginManager.isPluginEnabled(p))
			{
				return true;
			}
		}
		return false;
	}

	/** Whether Shortest Path is installed and switched on. */
	boolean enabled()
	{
		return enabled.getAsBoolean();
	}

	/**
	 * Points Shortest Path at `p` (null: clears the path this plugin set). On the client thread, every tick. While
	 * Shortest Path is off nothing is sent or remembered, so switching it on mid-run draws the way to the current stop.
	 */
	void show(FarmRuns.Point p)
	{
		if (!enabled())
		{
			target = null;
			return;
		}
		if (Objects.equals(p, target))
		{
			return;
		}
		FarmRuns.Point before = target;
		target = p;
		if (p != null)
		{
			post.accept(path(p));
		}
		else if (before != null)
		{
			post.accept(clear());
		}
	}
}

package com.ironwise;

import java.util.List;
import java.util.Map;

/**
 * Watches one stop and says when it's dealt with (new in 0.5.0). A farming patch's varbit is shared between regions,
 * so, like RuneLite's Time Tracking, a value counts only while the player is in one of the stop's regions and inside
 * its bounds; a bird house's varp counts on its plane within {@link #BIRDHOUSE_NEAR_TILES} of the space. The first
 * {@link #SETTLE_TICKS} readings in the area, or after {@link #reset}, are ignored (values from the region before, or
 * from before a hop, can linger). Ironwise sends each patch type's value → class table and done rules; the stop is done
 * when the class changes from one of a rule's "from" classes to its "to" class (bird houses: from empty or built to
 * seeded). Pure: the plugin feeds it the player's position and the value each tick, after TickGate.
 */
final class StopWatcher
{
	/** The same as the app's SETTLE_TICKS and BIRDHOUSE_NEAR_TILES (src/lib/farm/types.ts). */
	static final int SETTLE_TICKS = 2;
	static final int BIRDHOUSE_NEAR_TILES = 12;
	static final String GROWING = "Still growing. Shift + right-click the box: Skip stop.";

	enum Event
	{
		NONE,
		DONE,
	}

	private final FarmRuns.Stop stop;
	private final List<FarmRuns.Range> table;
	private int ticksInArea;
	/** The last class read in the area this visit; null when out of it or nothing read yet. */
	private String last;

	StopWatcher(FarmRuns.Stop stop, Map<String, List<FarmRuns.Range>> tables)
	{
		this.stop = stop;
		FarmRuns.Watch w = stop.watch;
		this.table = w != null && w.impl != null && tables != null ? tables.get(w.impl) : null;
	}

	String patchId()
	{
		return stop.patchId;
	}

	/** What to read for this stop (null: nothing, the player advances by hand). */
	FarmRuns.Watch watch()
	{
		return stop.watch;
	}

	/** Forget what was read: the next readings settle again (a hop, a loading screen, the welcome screen). */
	void reset()
	{
		ticksInArea = 0;
		last = null;
	}

	/** One game tick: where the player is and the stop's varbit (or varp) value. */
	Event tick(int x, int y, int plane, int regionId, int value)
	{
		FarmRuns.Watch w = stop.watch;
		if (w == null)
		{
			return Event.NONE;
		}
		if (!inArea(w, x, y, plane, regionId))
		{
			reset();
			return Event.NONE;
		}
		if (++ticksInArea <= SETTLE_TICKS)
		{
			return Event.NONE;
		}
		String cls = "birdhouse".equals(w.kind) ? birdhouseClass(value) : FarmRuns.classOf(table, value);
		if (cls == null)
		{
			return Event.NONE;
		}
		boolean done = last != null && !cls.equals(last) && done(w, last, cls);
		last = cls;
		return done ? Event.DONE : Event.NONE;
	}

	/** A line for the run box about what the patch is doing now, or null. */
	String hint()
	{
		return stop.watch != null && "varbit".equals(stop.watch.kind) && "planted".equals(last) ? GROWING : null;
	}

	private static boolean inArea(FarmRuns.Watch w, int x, int y, int plane, int regionId)
	{
		if (!w.inRegion(regionId))
		{
			return false;
		}
		if ("birdhouse".equals(w.kind))
		{
			return plane == w.plane && Math.max(Math.abs(x - w.near.x), Math.abs(y - w.near.y)) <= BIRDHOUSE_NEAR_TILES;
		}
		return w.bounds == null || w.bounds.contains(x, y, plane);
	}

	private static boolean done(FarmRuns.Watch w, String from, String to)
	{
		if ("birdhouse".equals(w.kind))
		{
			return "seeded".equals(to) && ("empty".equals(from) || "built".equals(from));
		}
		for (FarmRuns.DoneRule r : w.doneWhen)
		{
			if (r.to.equals(to) && r.from.contains(from))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * A bird house varp as RuneLite's BirdHouseState#fromVarpValue reads it: 0 empty, a multiple of 3 seeded, anything
	 * else up to 27 (9 house types × 3) built; null outside 0–27.
	 */
	static String birdhouseClass(int value)
	{
		if (value < 0 || value > 27)
		{
			return null;
		}
		if (value == 0)
		{
			return "empty";
		}
		return value % 3 == 0 ? "seeded" : "built";
	}
}

package com.ironwise;

import com.google.gson.Gson;
import java.io.IOException;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** Posts syncs to Ironwise on OkHttp's thread pool (never the client thread). */
@Singleton
class SyncClient
{
	static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	static final String NOT_IRONWISE = "that address answered, but it isn't the Ironwise app.";
	static final String LOGIN = "that address asked for a login. It isn't the Ironwise app, or it's a Vercel deployment URL: use the app's main address.";
	static final String NO_APP = "there's no Ironwise app at that address. Check it in the plugin settings.";
	static final String BAD_TOKEN = "this token isn't recognised. Make a new one on the app's Live data page.";
	static final String TOO_BIG = "it's too big.";

	interface Listener
	{
		void done(Result result);
	}

	enum Outcome
	{
		/** Saved. */
		OK,
		/** Ironwise doesn't know the token. */
		UNAUTHORIZED,
		/** The address isn't the Ironwise app (another site, a login page, a redirect). */
		WRONG_ADDRESS,
		/** Ironwise refused the data (e.g. it needs a newer plugin). */
		REJECTED,
		/** Couldn't reach Ironwise, or it had a problem: try again later. */
		RETRY,
	}

	static final class Result
	{
		final Outcome outcome;
		final String message;
		/** What a saved sync's answer said about the guide's next step (new in 0.4.0). */
		final NextStep.Reply guide;

		Result(Outcome outcome, String message)
		{
			this(outcome, message, NextStep.Reply.NOTHING);
		}

		Result(Outcome outcome, String message, NextStep.Reply guide)
		{
			this.outcome = outcome;
			this.message = message;
			this.guide = guide;
		}
	}

	/** Every answer from Ironwise's /api/sync: { "ok": true|false, "message": "..." }. */
	private static final class Body
	{
		Boolean ok;
		String message;
	}

	/** RuneLite's client, but redirects come back to us: a token must only go to the address the player set. */
	final OkHttpClient http;
	private final Gson gson;

	@Inject
	SyncClient(OkHttpClient http, Gson gson)
	{
		this.http = http.newBuilder().followRedirects(false).followSslRedirects(false).build();
		this.gson = gson;
	}

	/**
	 * The sync endpoint for an Ironwise address, or null if the address isn't usable. HTTPS only,
	 * except on this computer (http://localhost while running Ironwise locally).
	 */
	static HttpUrl syncUrl(String address)
	{
		return appUrl(address, "/api/sync");
	}

	/** {@code path} ("/api/...") on an Ironwise address, with the same rules as {@link #syncUrl}. */
	static HttpUrl appUrl(String address, String path)
	{
		if (address == null)
		{
			return null;
		}
		String a = address.trim();
		while (a.endsWith("/"))
		{
			a = a.substring(0, a.length() - 1);
		}
		if (a.isEmpty())
		{
			return null;
		}
		if (!a.contains("://"))
		{
			a = "https://" + a;
		}
		HttpUrl base = HttpUrl.parse(a);
		if (base == null)
		{
			return null;
		}
		boolean local = "localhost".equals(base.host()) || "127.0.0.1".equals(base.host()) || "[::1]".equals(base.host()) || "::1".equals(base.host());
		if (!"https".equals(base.scheme()) && !local)
		{
			return null;
		}
		return HttpUrl.parse(a + path);
	}

	/** A JSON post to Ironwise with the device token. */
	static Request post(HttpUrl url, String token, String json)
	{
		return new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + token)
			.header("User-Agent", "Ironwise-RuneLite/" + IronwisePlugin.VERSION)
			.post(RequestBody.create(JSON, json))
			.build();
	}

	void send(HttpUrl url, String token, String json, Listener listener)
	{
		http.newCall(post(url, token, json)).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				listener.done(new Result(Outcome.RETRY, "can't reach the app (" + e.getMessage() + ")"));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				Result r;
				try
				{
					r = result(response.code(), bodyOf(response), redirectOf(response));
				}
				catch (IOException e)
				{
					// The answer was cut off, so we can't tell what it said: try again, don't stop.
					r = new Result(Outcome.RETRY, "couldn't read the app's answer (" + e.getMessage() + ")");
				}
				catch (RuntimeException e)
				{
					r = new Result(Outcome.RETRY, "unexpected answer from the app");
				}
				finally
				{
					response.close();
				}
				listener.done(r);
			}
		});
	}

	static String bodyOf(Response response) throws IOException
	{
		ResponseBody body = response.body();
		return body == null ? "" : body.string();
	}

	/** Where a redirect points, relative to the address we posted to; null if it isn't a redirect. */
	private static HttpUrl redirectOf(Response response)
	{
		String location = response.header("Location");
		return response.isRedirect() && location != null ? response.request().url().resolve(location) : null;
	}

	/** Ironwise's JSON answer, or null if the body is something else (a web page, another app). */
	private Body ironwise(String body)
	{
		try
		{
			Body b = gson.fromJson(body, Body.class);
			return b != null && b.ok != null ? b : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	Result result(int code, String body, HttpUrl redirect)
	{
		Body b = ironwise(body);
		String message = b != null && b.message != null && !b.message.trim().isEmpty() ? b.message.trim() : null;
		if (code >= 200 && code < 300)
		{
			return b != null && b.ok
				? new Result(Outcome.OK, null, NextStep.fromBody(gson, body, "guide"))
				: new Result(Outcome.WRONG_ADDRESS, NOT_IRONWISE);
		}
		if (code >= 300 && code < 400)
		{
			return new Result(Outcome.WRONG_ADDRESS, redirected(redirect));
		}
		if (code == 401 || code == 403)
		{
			if (b == null)
			{
				return new Result(Outcome.WRONG_ADDRESS, LOGIN);
			}
			return new Result(Outcome.UNAUTHORIZED, message != null ? message : BAD_TOKEN);
		}
		if (code == 404)
		{
			return new Result(Outcome.REJECTED, NO_APP);
		}
		if (code == 400 || code == 413)
		{
			return new Result(Outcome.REJECTED, message != null ? message : code == 413 ? TOO_BIG : "the app answered " + code);
		}
		return new Result(Outcome.RETRY, message != null ? message : "the app answered " + code);
	}

	/**
	 * What to say about a redirect. Ironwise's sync address never redirects, so the player's address is
	 * wrong: if it leads to another sync address (www., https), that's the one to use; anywhere else is a
	 * login or another site.
	 */
	static String redirected(HttpUrl to)
	{
		if (to == null)
		{
			return "that address redirects somewhere else. Use the app's main address.";
		}
		String url = to.newBuilder().query(null).fragment(null).build().toString();
		if (url.endsWith("/api/sync"))
		{
			String address = url.substring(0, url.length() - "/api/sync".length());
			if (syncUrl(address) != null)
			{
				return "that address redirects to " + address + "; use that address instead.";
			}
		}
		return "that address redirects to " + to.host() + ", which isn't the Ironwise app. If it's a Vercel deployment URL, use the app's main address.";
	}
}

package com.ironwise;

import java.util.List;
import java.util.Map;

/**
 * What the plugin posts to Ironwise's /api/sync (version 1). Serialised with RuneLite's Gson, so
 * field names are the JSON names. The account hash is a string: it doesn't fit in a JSON number.
 */
class SyncPayload
{
	static final int VERSION = 1;

	final int v = VERSION;
	String plugin;
	long sentAt;
	Account account;
	/** RuneLite skill name → level and XP. */
	Map<String, SkillEntry> skills;
	Quests quests;
	/** "bank", "inventory", "equipment", "seedVault", "lootingBag", "groupStorage" → items. */
	Map<String, Container> containers;
	/** Varbit id → value. */
	Map<String, Integer> varbits;
	/** Varp id → value. */
	Map<String, Integer> varps;
	/** RuneLite config group ("timetracking", "killcount", "kingdomofmiscellania") → key → value. */
	Map<String, Map<String, String>> saved;
	/**
	 * The collection log as far as it's been seen this session (new in 0.3.0). Left out (null) until
	 * something is known, so older Ironwise apps, which ignore keys they don't know, are unaffected.
	 */
	CollectionLog collectionLog;

	static class Account
	{
		final String hash;
		final String rsn;
		final int world;

		Account(String hash, String rsn, int world)
		{
			this.hash = hash;
			this.rsn = rsn;
			this.world = world;
		}
	}

	static class SkillEntry
	{
		final int level;
		final int xp;

		SkillEntry(int level, int xp)
		{
			this.level = level;
			this.xp = xp;
		}
	}

	static class Quests
	{
		final int points;
		final List<QuestEntry> entries;

		Quests(int points, List<QuestEntry> entries)
		{
			this.points = points;
			this.entries = entries;
		}
	}

	static class QuestEntry
	{
		/** RuneLite's Quest enum name, e.g. "DRAGON_SLAYER_I". */
		final String id;
		final String name;
		/** NOT_STARTED, IN_PROGRESS or FINISHED. */
		final String state;

		QuestEntry(String id, String name, String state)
		{
			this.id = id;
			this.name = name;
			this.state = state;
		}
	}

	static class Container
	{
		/** When the game last sent this container (epoch ms). */
		final long seenAt;
		/** [item id, quantity] pairs. */
		final List<int[]> items;

		Container(long seenAt, List<int[]> items)
		{
			this.seenAt = seenAt;
			this.items = items;
		}
	}

	static class CollectionLog
	{
		/** From a search listing: every obtained item in the log. Left out until the player searches. */
		final ClogSnapshot all;
		/** Page name → the page as last viewed. */
		final Map<String, ClogPage> pages;
		/** ["item name", epoch ms] from "New item added to your collection log" since the last sync that got through. */
		final List<Object[]> added;

		CollectionLog(ClogSnapshot all, Map<String, ClogPage> pages, List<Object[]> added)
		{
			this.all = all;
			this.pages = pages;
			this.added = added;
		}
	}

	static class ClogSnapshot
	{
		/** When the listing was read (epoch ms). */
		final long seenAt;
		/** [item id, count] pairs, obtained items only. */
		final List<int[]> items;

		ClogSnapshot(long seenAt, List<int[]> items)
		{
			this.seenAt = seenAt;
			this.items = items;
		}
	}

	static class ClogPage
	{
		/** When the page was first seen, or last seen with something new on it (epoch ms). */
		final long seenAt;
		/** ["Vorkath kills", 123] pairs: the page's kill count lines. */
		final List<Object[]> kc;
		/** [item id, count] pairs, obtained items only. */
		final List<int[]> items;

		ClogPage(long seenAt, List<Object[]> kc, List<int[]> items)
		{
			this.seenAt = seenAt;
			this.kc = kc;
			this.items = items;
		}
	}
}

package com.ironwise;

/**
 * When a tick's farming varbits and bird house varps can be trusted, as RuneLite's Time Tracking decides at
 * be6527130b1e2bd27ac072c724145e5e60d6f73a (new in 0.5.0): never while the welcome screen is up or on the tick after it
 * closes (TimeTrackingPlugin#onGameTick: "bird house data is only sent after exiting the post-login screen"), never on a
 * tick whose region differs from the tick before's (the same method), never while a modal interface is open
 * (FarmingTracker#updateData: "Varbits don't get sent when a modal widget is open"); and bird house varps not on a tick
 * where more than two spaces drop to 0 against the values last accepted (BirdHouseTracker#updateData: the varps haven't
 * been sent yet). Pure: the controller feeds it what the client shows.
 */
final class TickGate
{
	private boolean afterWelcome;
	/** The region on the tick before; -1: none yet (after logging in, a hop or a loading screen). */
	private int lastRegion = -1;
	/** The bird house varps last accepted; null: none yet. */
	private int[] houses;

	/** Logging in, a hop, a loading screen: the next tick only records the region. */
	void reset()
	{
		afterWelcome = false;
		lastRegion = -1;
	}

	/** Whether this tick's varbits can be read. Call it once every tick. */
	boolean readable(boolean welcomeOpen, boolean modalOpen, int regionId)
	{
		if (welcomeOpen)
		{
			afterWelcome = true;
			return false;
		}
		if (afterWelcome)
		{
			afterWelcome = false;
			return false;
		}
		int before = lastRegion;
		lastRegion = regionId;
		return before != -1 && before == regionId && !modalOpen;
	}

	/** Whether this tick's bird house varps can be read (on Fossil Island's surface); only readable values are kept. */
	boolean housesReadable(int[] varps)
	{
		if (houses != null)
		{
			int dropped = 0;
			for (int i = 0; i < varps.length && i < houses.length; i++)
			{
				if (varps[i] <= 0 && houses[i] > 0)
				{
					dropped++;
				}
			}
			if (dropped > 2)
			{
				return false;
			}
		}
		houses = varps.clone();
		return true;
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

/**
 * Every stop of the current stop's cluster is watched, in any order: a patch dealt with before the one the box shows,
 * and two dealt with one after another before Ironwise answers, both reach Ironwise; logging in or hopping at a patch
 * never reads as dealt with. Catherby's herb and flower patches share region 11062 and its bounds (different varbits).
 */
public class ClusterWatchTest
{
	private static final String TABLES = "{\"HERB\":[[0,3,\"empty\"],[32,35,\"planted\"],[36,38,\"harvest\"]],\"FLOWER\":[[0,3,\"empty\"],[8,11,\"planted\"],[12,12,\"harvest\"]]}";
	private static final String RULES = "[{\"from\":[\"empty\",\"grown\",\"harvest\",\"diseased\",\"dead\"],\"to\":\"planted\"}]";

	private static String stop(String id, String state, int varbit, String impl)
	{
		return "{\"patchId\":\"" + id + "\",\"name\":\"" + id + "\",\"type\":\"herb\",\"cluster\":\"catherby\",\"state\":\"" + state + "\",\"point\":{\"x\":2810,\"y\":3464,\"plane\":0},"
			+ "\"watch\":{\"kind\":\"varbit\",\"varbit\":" + varbit + ",\"impl\":\"" + impl + "\",\"regions\":[11062],\"bounds\":null,\"doneWhen\":" + RULES + "}}";
	}

	/** Herb (current or done), flower, then Falador's herb patch (another cluster). */
	private static FarmRuns view(int index, String herb, String flower)
	{
		return FarmRuns.parse(FarmRunsTest.json("{\"ok\":true,\"rev\":\"r\",\"presets\":[],\"tables\":" + TABLES + ",\"active\":{\"name\":\"Run\",\"index\":" + index
			+ ",\"finished\":false,\"startedAt\":1,\"stops\":[" + stop("herb-catherby", herb, 4774, "HERB") + "," + stop("flower-catherby", flower, 4773, "FLOWER") + ","
			+ "{\"patchId\":\"herb-falador\",\"name\":\"Falador\",\"type\":\"herb\",\"cluster\":\"falador-farm\",\"state\":\"todo\",\"point\":null,\"watch\":null}],\"bring\":[]}}"));
	}

	/** One tick at Catherby with the herb's and the flower's values. */
	private static void tick(ClusterWatch c, int herb, int flower)
	{
		for (StopWatcher w : c.watchers())
		{
			c.tick(w, 2810, 3464, 0, 11062, w.patchId().equals("herb-catherby") ? herb : flower);
		}
	}

	@Test
	public void thePatchDoneFirstIsSentEvenIfItIsntTheCurrentStop()
	{
		ClusterWatch c = new ClusterWatch();
		c.update(view(0, "current", "todo"));
		assertEquals(2, c.watchers().size());
		tick(c, 36, 12);
		tick(c, 36, 12);
		tick(c, 36, 12);
		tick(c, 36, 3); // the flower picked and raked first
		tick(c, 36, 8); // and planted
		assertEquals("flower-catherby", c.next());
	}

	@Test
	public void twoPatchesDoneOneAfterAnotherBothReachIronwise()
	{
		ClusterWatch c = new ClusterWatch();
		c.update(view(0, "current", "todo"));
		for (int i = 0; i < 3; i++)
		{
			tick(c, 36, 12);
		}
		tick(c, 3, 12);
		tick(c, 32, 12); // herb planted: sent
		assertEquals("herb-catherby", c.next());
		tick(c, 32, 3);
		tick(c, 32, 8); // the flower planted before Ironwise answered
		c.sent("herb-catherby");
		// Ironwise's answer: the herb done, the flower current. Its watcher is kept (no new settle ticks), the flower still queued.
		c.update(view(1, "done", "current"));
		assertEquals(1, c.watchers().size());
		assertEquals("flower-catherby", c.next());
		c.update(view(2, "done", "done"));
		assertNull(c.next());
	}

	@Test
	public void loggingInOrHoppingAtAPlantedPatchIsNotDone()
	{
		ClusterWatch c = new ClusterWatch();
		TickGate g = new TickGate();
		c.update(view(0, "current", "todo"));
		// The welcome screen: nothing read (the game may send 0 until it closes), then the patch as it is: planted.
		int[][] ticks = {{0, 0}, {0, 0}, {0, 0}, {0, 0}, {32, 8}, {32, 8}, {32, 8}, {32, 8}};
		boolean[] welcome = {true, true, false, false, false, false, false, false};
		for (int i = 0; i < ticks.length; i++)
		{
			if (g.readable(welcome[i], false, 11062))
			{
				tick(c, ticks[i][0], ticks[i][1]);
			}
		}
		assertNull(c.next());
		// A hop: stale zeros on the first ticks after it, then planted again.
		g.reset();
		c.reset();
		for (int[] t : new int[][]{{0, 0}, {0, 0}, {0, 0}, {32, 8}, {32, 8}})
		{
			if (g.readable(false, false, 11062))
			{
				tick(c, t[0], t[1]);
			}
		}
		assertNull(c.next());
	}

	@Test
	public void anotherClusterStartsAfresh()
	{
		ClusterWatch c = new ClusterWatch();
		c.update(view(0, "current", "todo"));
		c.update(view(2, "done", "done")); // on to Falador: no watch there
		assertEquals(0, c.watchers().size());
		assertNull(c.hint());
	}
}

