		int calls;
		boolean searching;

		final Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			calls++;
			switch (method.getName())
			{
				case "getTickCount":
					return tick;
				case "getWorldType":
					return EnumSet.noneOf(WorldType.class);
				case "getVarbitValue":
					// Not another player's log, and the log's own body type.
					return 0;
				case "getWidget":
					if (args.length == 1 && args[0] instanceof Integer)
					{
						return widget((Integer) args[0]);
					}
					break;
				default:
					break;
			}
			throw new AssertionError("the reader called Client." + method.getName());
		});

		private Widget widget(int id)
		{
			switch (id)
			{
				case InterfaceID.Collection.HEADER_TEXT:
					return parent(text("Vorkath"), text("Obtained: <col=ff0000>1/2</col>"), text("Vorkath kills: <col=ff0000>61</col>"));
				case InterfaceID.Collection.ITEMS_CONTENTS:
					return parent(slot(11286, 0, 2), slot(22006, 150, 0));
				case InterfaceID.Collection.CONTENT_SEARCH:
					return searching ? parent() : null;
				default:
					return null;
			}
		}

		/** The log's Search lists one obtained item (clientscript collection_delayed_transmit). */
		ScriptPreFired listed(int item, int count)
		{
			Object[] args = {CollectionLogReader.COLLECTION_DELAYED_TRANSMIT, item, count, 0, 0};
			ScriptPreFired event = new ScriptPreFired(CollectionLogReader.COLLECTION_DELAYED_TRANSMIT);
			event.setScriptEvent((ScriptEvent) Proxy.newProxyInstance(ScriptEvent.class.getClassLoader(), new Class<?>[]{ScriptEvent.class}, (proxy, method, a) ->
			{
				if ("getArguments".equals(method.getName()))
				{
					return args;
				}
				throw new AssertionError("the reader called ScriptEvent." + method.getName());
			}));
			return event;
		}
	}

	private static Widget parent(Widget... children)
	{
		return widget(Collections.singletonMap("getDynamicChildren", children));
	}

	private static Widget text(String text)
	{
		return widget(Collections.singletonMap("getText", text));
	}

	private static Widget slot(int item, int opacity, int quantity)
	{
		return widget(Map.of("getItemId", item, "getOpacity", opacity, "getItemQuantity", quantity));
	}

	/** A widget that answers the given getters, says it's shown, and fails on anything else. */
	private static Widget widget(Map<String, Object> answers)
	{
		return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class<?>[]{Widget.class}, (proxy, method, args) ->
		{
			if ("isHidden".equals(method.getName()))
			{
				return false;
			}
			if (answers.containsKey(method.getName()))
			{
				return answers.get(method.getName());
			}
			throw new AssertionError("the reader called Widget." + method.getName());
		});
	}

	private static ChatMessage chat(String text)
	{
		return new ChatMessage(null, ChatMessageType.GAMEMESSAGE, "", text, "", 0);
	}

	/** Whether a sync carrying this state would have a collection log section, as RuneLite's Gson writes it. */
	private static boolean payloadHasCollectionLog(CollectionLogState state)
	{
		SyncPayload p = new SyncPayload();
		p.plugin = IronwisePlugin.VERSION;
		p.account = new SyncPayload.Account("1234567890123456789", "Iron Example", 302);
		// What PayloadBuilder.build puts there.
		p.collectionLog = state.toPayload();
		JsonObject json = new JsonParser().parse(RuneLiteAPI.GSON.toJson(p)).getAsJsonObject();
		return json.has("collectionLog");
	}

	/** Everything the game could show while the setting matters: a search listing, the page, and a chat line. */
	private static boolean playerUsesTheLog(Game game, CollectionLogReader reader)
	{
		boolean recorded = false;
		game.searching = true;
		reader.onScriptPreFired(game.listed(22006, 1));
		reader.onScriptPreFired(game.listed(11286, 2));
		for (int i = 0; i < 4; i++)
		{
			game.tick++;
			recorded |= reader.onGameTick(1000 + i);
		}
		game.searching = false;
		for (int i = 0; i < 2; i++)
		{
			game.tick++;
			recorded |= reader.onGameTick(2000 + i);
		}
		recorded |= reader.onChatMessage(chat(NEW_ITEM), 3000);
		return recorded;
	}

	@Test
	public void theSettingIsOffByDefault() throws NoSuchMethodException
	{
		IronwiseConfig defaults = new IronwiseConfig()
		{
		};
		assertFalse(defaults.syncCollectionLog());

		ConfigItem item = IronwiseConfig.class.getMethod("syncCollectionLog").getAnnotation(ConfigItem.class);
		assertEquals("syncCollectionLog", item.keyName());
		assertEquals(IronwiseConfig.SYNC_COLLECTION_LOG, item.keyName());
		assertEquals("Sync collection log", item.name());
		// It tells players how to use it.
		assertTrue(item.description(), item.description().contains("click Search"));
	}

	@Test
	public void offNothingIsReadOrSent()
	{
		Settings settings = new Settings();
		settings.clog.set(false);
		Game game = new Game();
		CollectionLogState state = new CollectionLogState();
		CollectionLogReader reader = new CollectionLogReader(game.client, state, settings);

		assertFalse(playerUsesTheLog(game, reader));

		// Not so much as a look at the game.
		assertEquals(0, game.calls);
		assertEquals(-1, reader.takeFinishedListing());
		assertNull(state.toPayload());
		assertFalse(payloadHasCollectionLog(state));
	}

	@Test
	public void onlyWhileSyncWithIronwiseIsTickedToo()
	{
		Settings settings = new Settings();
		settings.sync.set(false);
		Game game = new Game();
		CollectionLogState state = new CollectionLogState();
		CollectionLogReader reader = new CollectionLogReader(game.client, state, settings);

		assertFalse(playerUsesTheLog(game, reader));

		assertEquals(0, game.calls);
		assertFalse(payloadHasCollectionLog(state));
	}

	@Test
	public void onASearchListingIsReadAsBefore()
	{
		Game game = new Game();
		game.searching = true;
		CollectionLogState state = new CollectionLogState();
		CollectionLogReader reader = new CollectionLogReader(game.client, state, new Settings());

		reader.onScriptPreFired(game.listed(22006, 1));
		reader.onScriptPreFired(game.listed(11286, 2));
		game.tick++;
		reader.onScriptPreFired(game.listed(11286, 1));
		// Still arriving: nothing yet.
		for (int i = 0; i < 2; i++)
		{
			game.tick++;
			assertFalse(reader.onGameTick(1000));
		}
		assertEquals(-1, reader.takeFinishedListing());

		// Three quiet ticks: the listing is done.
		game.tick++;
		assertTrue(reader.onGameTick(1500));
		assertEquals(2, reader.takeFinishedListing());
		assertEquals(-1, reader.takeFinishedListing());

		SyncPayload.CollectionLog log = state.toPayload();
		assertNotNull(log);
		assertEquals("{\"seenAt\":1500,\"items\":[[11286,2],[22006,1]]}", RuneLiteAPI.GSON.toJson(log.all));
		assertTrue(payloadHasCollectionLog(state));
	}

	@Test
	public void onPagesAndNewItemLinesAreReadAsBefore()
	{
		Game game = new Game();
		CollectionLogState state = new CollectionLogState();
		CollectionLogReader reader = new CollectionLogReader(game.client, state, new Settings());

		// A page counts once it reads the same two ticks running.
		assertFalse(reader.onGameTick(2000));
		game.tick++;
		assertTrue(reader.onGameTick(2001));
		assertTrue(reader.onChatMessage(chat(NEW_ITEM), 3000));

		SyncPayload.CollectionLog log = state.toPayload();
		assertNotNull(log);
		assertNull(log.all);
		assertEquals("{\"Vorkath\":{\"seenAt\":2001,\"kc\":[[\"Vorkath kills\",61]],\"items\":[[11286,2]]}}", RuneLiteAPI.GSON.toJson(log.pages));
		assertEquals(1, log.added.size());
		assertEquals("Vorkath's head", log.added.get(0)[0]);
		assertEquals(3000L, log.added.get(0)[1]);
	}

	@Test
	public void turningItOffStopsReadingAtOnceAndNothingReadIsSent()
	{
		Settings settings = new Settings();
		Game game = new Game();
		CollectionLogState state = new CollectionLogState();
		CollectionLogReader reader = new CollectionLogReader(game.client, state, settings);
		assertTrue(playerUsesTheLog(game, reader));
		assertTrue(payloadHasCollectionLog(state));
		// A new listing starts arriving...
		game.searching = true;
		reader.onScriptPreFired(game.listed(22006, 1));

		// ...and the player unticks Sync collection log.
		settings.clog.set(false);
		int calls = game.calls;
		assertFalse(reader.onGameTick(4000));
		assertFalse(playerUsesTheLog(game, reader));
		assertEquals(calls, game.calls);
		assertEquals(-1, reader.takeFinishedListing());
		// What was read earlier this session is dropped too, so the next sync has no collection log section.
		assertNull(state.toPayload());
		assertFalse(payloadHasCollectionLog(state));

		// Ticked again, the half-read listing doesn't come back: the player searches again.
		settings.clog.set(true);
		game.searching = true;
		for (int i = 0; i < 4; i++)
		{
			game.tick++;
			reader.onGameTick(5000);
		}
		assertEquals(-1, reader.takeFinishedListing());
		assertNull(state.toPayload());
	}

	@Test
	public void untickingSyncWithIronwiseForgetsTheLogToo()
	{
		Settings settings = new Settings();
		Game game = new Game();
		CollectionLogState state = new CollectionLogState();
		CollectionLogReader reader = new CollectionLogReader(game.client, state, settings);
		assertTrue(playerUsesTheLog(game, reader));

		settings.sync.set(false);
		int calls = game.calls;
		assertFalse(reader.onGameTick(4000));
		assertEquals(calls, game.calls);
		assertFalse(payloadHasCollectionLog(state));
	}

	@Test
	public void togglingTheSettingDoesntRestartSyncing() throws ReflectiveOperationException
	{
		// Syncing stopped over a setting only the player can fix, and they've been told once.
		IronwisePlugin plugin = new IronwisePlugin();
		set(plugin, "stopped", "Ironwise: paste your device token in the plugin settings.");
		set(plugin, "dirty", false);
		set(plugin, "announced", true);

		plugin.onConfigChanged(changed(IronwiseConfig.SYNC_COLLECTION_LOG, "false", "true"));
		plugin.onConfigChanged(changed(IronwiseConfig.SYNC_COLLECTION_LOG, "true", "false"));

		// Only what's read changed, not where or how to sync: still stopped, no new sync, no second "syncing" line.
		assertEquals("Ironwise: paste your device token in the plugin settings.", get(plugin, "stopped"));
		assertFalse((Boolean) get(plugin, "dirty"));
		assertTrue((Boolean) get(plugin, "announced"));
	}

	@Test
	public void noWidgetIsEverAddedToTheCollectionLog() throws IOException
	{
		// The button that pressed the log's Search is gone...
		try
		{
			Class.forName("com.ironwise.CollectionLogSyncButton");
			fail("CollectionLogSyncButton is back");
		}
		catch (ClassNotFoundException expected)
		{
			// Gone.
		}
		// ...and nothing in the plugin adds widgets, sets up game menu options or presses anything in the game.
		File[] sources = new File("src/main/java/com/ironwise").listFiles((dir, name) -> name.endsWith(".java"));
		assertNotNull(sources);
		assertTrue(sources.length > 0);
		for (File source : sources)
		{
			String code = new String(Files.readAllBytes(source.toPath()), StandardCharsets.UTF_8);
			for (String call : new String[]{"createChild(", "menuAction(", "runScript(", "setAction(", "setOnOpListener(", "ScriptPostFired"})
			{
				assertFalse(source.getName() + " uses " + call, code.contains(call));
			}
		}
		assertNull("WikiSync's notice was only for the button", IronwisePlugin.class.getResource("THIRD_PARTY_NOTICES.txt"));
	}

	private static ConfigChanged changed(String key, String oldValue, String newValue)
	{
		ConfigChanged changed = new ConfigChanged();
		changed.setGroup(IronwiseConfig.GROUP);
		changed.setKey(key);
		changed.setOldValue(oldValue);
		changed.setNewValue(newValue);
		return changed;
	}

	private static void set(IronwisePlugin plugin, String name, Object value) throws ReflectiveOperationException
	{
		Field f = IronwisePlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private static Object get(IronwisePlugin plugin, String name) throws ReflectiveOperationException
	{
		Field f = IronwisePlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(plugin);
	}
}

package com.ironwise;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;

/** Made-up items and counts: no real account data. */
public class CollectionLogStateTest
{
	private static final char NBSP = (char) 160;

	private final CollectionLogState state = new CollectionLogState();

	private static Map<Integer, Integer> items(int... idQty)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (int i = 0; i < idQty.length; i += 2)
		{
			out.put(idQty[i], idQty[i + 1]);
		}
		return out;
	}

	private static Map<String, Integer> kc(Object... labelCount)
	{
		Map<String, Integer> out = new LinkedHashMap<>();
		for (int i = 0; i < labelCount.length; i += 2)
		{
			out.put((String) labelCount[i], (Integer) labelCount[i + 1]);
		}
		return out;
	}

	private static List<Integer> shown(Integer... ids)
	{
		return Arrays.asList(ids);
	}

	private static String pairs(List<int[]> items)
	{
		StringBuilder b = new StringBuilder();
		for (int[] p : items)
		{
			b.append('[').append(p[0]).append(',').append(p[1]).append(']');
		}
		return b.toString();
	}

	// Parsing what the game draws and says

	@Test
	public void chatLinesNameTheNewItem()
	{
		assertEquals("Vorkath's head", CollectionLogState.addedItemName("New item added to your collection log: Vorkath's head"));
		assertEquals("Draconic visage", CollectionLogState.addedItemName("New item added to your collection log: <col=ef1020>Draconic visage</col>"));
		assertEquals("Pet snakeling", CollectionLogState.addedItemName("New item added to your collection log:" + NBSP + "Pet snakeling "));
		assertNull(CollectionLogState.addedItemName("Your Vorkath kill count is: 50."));
		assertNull(CollectionLogState.addedItemName("New item added to your collection log: "));
		assertNull(CollectionLogState.addedItemName(null));
		char[] longName = new char[CollectionLogState.MAX_NAME + 1];
		Arrays.fill(longName, 'a');
		assertNull(CollectionLogState.addedItemName("New item added to your collection log: " + new String(longName)));
	}

	@Test
	public void pageHeadingsAreNames()
	{
		assertEquals("Vorkath", CollectionLogState.pageName("Vorkath"));
		assertEquals("Chambers of Xeric", CollectionLogState.pageName("<col=ff981f>Chambers of Xeric</col>"));
		assertNull(CollectionLogState.pageName(""));
		assertNull(CollectionLogState.pageName("<col=ff981f></col>"));
		char[] longName = new char[CollectionLogState.MAX_NAME + 1];
		Arrays.fill(longName, 'a');
		assertNull(CollectionLogState.pageName(new String(longName)));
	}

	@Test
	public void killCountLines()
	{
		Map.Entry<String, Integer> vorkath = CollectionLogState.kcLine("Vorkath kills: <col=ffffff>1,234</col>");
		assertNotNull(vorkath);
		assertEquals("Vorkath kills", vorkath.getKey());
		assertEquals(1234, (int) vorkath.getValue());

		Map.Entry<String, Integer> cm = CollectionLogState.kcLine("Chambers of Xeric (CM) completions: <col=ffffff>3</col>");
		assertEquals("Chambers of Xeric (CM) completions", cm.getKey());
		assertEquals(3, (int) cm.getValue());

		// Some labels already end in a colon.
		Map.Entry<String, Integer> gambles = CollectionLogState.kcLine("High-level Gambles: <col=ffffff>12</col>");
		assertEquals("High-level Gambles", gambles.getKey());

		// Not sent: zero, and lines that aren't kill counts
		assertNull(CollectionLogState.kcLine("Obor kills: <col=ffffff>0</col>"));
		assertNull(CollectionLogState.kcLine("Obtained: <col=ffff00>3/12</col>"));
		assertNull(CollectionLogState.kcLine("Obtained: 3"));
		assertNull(CollectionLogState.kcLine("Vorkath kills: <col=ffffff>Lots! (2147483647+)</col>"));
		assertNull(CollectionLogState.kcLine("Vorkath kills: 99999999999"));
		assertNull(CollectionLogState.kcLine("Vorkath"));
		assertNull(CollectionLogState.kcLine(": 12"));
	}

	@Test
	public void obtainedLines()
	{
		assertArrayEquals(new int[]{3, 12}, CollectionLogState.obtainedLine("Obtained: <col=ffff00>3/12</col>"));
		assertArrayEquals(new int[]{0, 7}, CollectionLogState.obtainedLine("Obtained: <col=ff0000>0/7</col>"));
		assertNull(CollectionLogState.obtainedLine("Vorkath kills: 12"));
	}

	// What goes into a sync

	@Test
	public void nothingSeenSendsNothing()
	{
		assertNull(state.toPayload());
	}

	@Test
	public void aSearchListingIsTheWholeLog()
	{
		assertTrue(state.searchSeen(items(22006, 1, 11286, 2, 0, 5, 995, 0), 1000));
		SyncPayload.CollectionLog log = state.toPayload();
		assertNotNull(log.all);
		assertEquals(1000, log.all.seenAt);
		// Sorted by id; empty ids and zero counts left out.
		assertEquals("[11286,2][22006,1]", pairs(log.all.items));
		assertTrue(log.pages.isEmpty());
		assertTrue(log.added.isEmpty());

		// A later search is newer even when nothing changed, and counts never go down.
		assertTrue(state.searchSeen(items(22006, 1, 11286, 1), 2000));
		log = state.toPayload();
		assertEquals(2000, log.all.seenAt);
		assertEquals("[11286,2][22006,1]", pairs(log.all.items));
	}

	@Test
	public void anEmptyLogIsStillKnown()
	{
		assertTrue(state.searchSeen(Collections.emptyMap(), 1000));
		assertEquals(0, state.toPayload().all.items.size());
	}

	@Test
	public void aListingTooBigToSendIsDropped()
	{
		Map<Integer, Integer> huge = new TreeMap<>();
		for (int id = 1; id <= CollectionLogState.MAX_ITEMS + 1; id++)
		{
			huge.put(id, 1);
		}
		assertFalse(state.searchSeen(huge, 1000));
		assertNull(state.toPayload());
	}

	@Test
	public void pagesKeepTheirItemsAndKillCounts()
	{
		assertTrue(state.pageSeen("Vorkath", kc("Vorkath kills", 50), shown(11286, 22006, 21907), items(11286, 2), 1000));
		SyncPayload.ClogPage page = state.toPayload().pages.get("Vorkath");
		assertEquals(1000, page.seenAt);
		assertEquals("[11286,2]", pairs(page.items));
		assertEquals(1, page.kc.size());
		assertArrayEquals(new Object[]{"Vorkath kills", 50}, page.kc.get(0));
		assertNull(state.toPayload().all);

		// The same page again: nothing new, so it keeps its time.
		assertFalse(state.pageSeen("Vorkath", kc("Vorkath kills", 50), shown(11286, 22006, 21907), items(11286, 2), 2000));
		assertEquals(1000, state.toPayload().pages.get("Vorkath").seenAt);

		// A new item and more kills.
		assertTrue(state.pageSeen("Vorkath", kc("Vorkath kills", 61), shown(11286, 22006, 21907), items(11286, 2, 22006, 1), 3000));
		page = state.toPayload().pages.get("Vorkath");
		assertEquals(3000, page.seenAt);
		assertEquals("[11286,2][22006,1]", pairs(page.items));
		assertArrayEquals(new Object[]{"Vorkath kills", 61}, page.kc.get(0));
	}

	@Test
	public void aPageDrawnBeforeItsItemsArriveDoesNotUndoIt()
	{
		state.pageSeen("Vorkath", kc("Vorkath kills", 61), shown(11286, 22006), items(11286, 2, 22006, 1), 1000);
		assertFalse(state.pageSeen("Vorkath", kc("Vorkath kills", 12), shown(11286, 22006), items(), 2000));
		SyncPayload.ClogPage page = state.toPayload().pages.get("Vorkath");
		assertEquals(1000, page.seenAt);
		assertEquals("[11286,2][22006,1]", pairs(page.items));
		assertArrayEquals(new Object[]{"Vorkath kills", 61}, page.kc.get(0));
	}

	@Test
	public void aPageUsesAnEarlierSearchForItsOwnItems()
	{
		state.searchSeen(items(11286, 3, 22006, 1, 12073, 4), 1000);
		// Drawn as nothing obtained (the game hadn't sent the page yet): the search still counts.
		assertTrue(state.pageSeen("Vorkath", kc(), shown(11286, 22006, 21907), items(), 2000));
		// Only the page's own items: 12073 is on another page.
		assertEquals("[11286,3][22006,1]", pairs(state.toPayload().pages.get("Vorkath").items));
	}

	@Test
	public void aPageWithNothingObtainedIsStillSent()
	{
		assertTrue(state.pageSeen("Obor", kc("Obor kills", 3), shown(20756, 20754), items(), 1000));
		SyncPayload.ClogPage page = state.toPayload().pages.get("Obor");
		assertTrue(page.items.isEmpty());
		assertArrayEquals(new Object[]{"Obor kills", 3}, page.kc.get(0));
	}

	@Test
	public void killCountLinesAreCapped()
	{
		Map<String, Integer> lines = new LinkedHashMap<>();
		for (int i = 1; i <= CollectionLogState.MAX_KC_LINES + 2; i++)
		{
			lines.put("Boss " + i + " kills", i);
		}
		state.pageSeen("Many", lines, shown(), items(), 1000);
		assertEquals(CollectionLogState.MAX_KC_LINES, state.toPayload().pages.get("Many").kc.size());
	}

	@Test
	public void theOldestPageMakesRoom()
	{
		for (int i = 0; i < CollectionLogState.MAX_PAGES; i++)
		{
			state.pageSeen("Page " + i, kc(), shown(), items(), 1000 + i);
		}
		// Page 0 is seen again with something new, so Page 1 is now the oldest.
		state.pageSeen("Page 0", kc(), shown(4151), items(4151, 1), 5000);
		state.pageSeen("One more", kc(), shown(), items(), 6000);
		Map<String, SyncPayload.ClogPage> pages = state.toPayload().pages;
		assertEquals(CollectionLogState.MAX_PAGES, pages.size());
		assertTrue(pages.containsKey("Page 0"));
		assertFalse(pages.containsKey("Page 1"));
		assertTrue(pages.containsKey("One more"));
	}

	@Test
	public void newItemLinesAreKeptUntilSent()
	{
		assertTrue(state.added("Vorkath's head", 1000));
		assertFalse(state.added("Vorkath's head", 2000));
		assertTrue(state.added("Draconic visage", 3000));

		SyncPayload.CollectionLog log = state.toPayload();
		assertNull(log.all);
		assertTrue(log.pages.isEmpty());
		assertEquals(2, log.added.size());
		assertArrayEquals(new Object[]{"Vorkath's head", 1000L}, log.added.get(0));
		assertArrayEquals(new Object[]{"Draconic visage", 3000L}, log.added.get(1));

		// One arrives while that sync is on its way: it stays for the next one.
		state.added("Skeletal visage", 4000);
		state.addedSent(log.added);
		SyncPayload.CollectionLog next = state.toPayload();
		assertEquals(1, next.added.size());
		assertArrayEquals(new Object[]{"Skeletal visage", 4000L}, next.added.get(0));

		state.addedSent(next.added);
		assertNull(state.toPayload());
		state.addedSent(null);
	}

	@Test
	public void newItemLinesAreCapped()
	{
		for (int i = 0; i < CollectionLogState.MAX_ADDED + 5; i++)
		{
			state.added("Item " + i, i);
		}
		List<Object[]> added = state.toPayload().added;
		assertEquals(CollectionLogState.MAX_ADDED, added.size());
		// The oldest go first.
		assertEquals("Item 5", added.get(0)[0]);
	}

	@Test
	public void resetForgetsEverything()
	{
		state.searchSeen(items(22006, 1), 1000);
		state.pageSeen("Vorkath", kc(), shown(22006), items(22006, 1), 1000);
		state.added("Vorkath's head", 1000);
		state.reset();
		assertNull(state.toPayload());
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.HashSet;
import net.runelite.http.api.RuneLiteAPI;
import okhttp3.OkHttpClient;
import org.junit.Test;

/**
 * Ironwise's /api/plugin/runs answers and the requests it accepts, word for word as src/server/runs/plugin.ts and
 * src/app/api/plugin/runs/route.ts write them, and the plugin's hold on the last answer (FarmRunState).
 */
public class FarmRunContractTest
{
	private final FarmRunClient client = new FarmRunClient(new SyncClient(new OkHttpClient(), RuneLiteAPI.GSON), RuneLiteAPI.GSON);

	private static String error(String error, String message)
	{
		JsonObject o = new JsonObject();
		o.addProperty("ok", false);
		o.addProperty("error", error);
		o.addProperty("message", message);
		return o.toString();
	}

	private static HashSet<Integer> ids(Integer... ids)
	{
		return new HashSet<>(Arrays.asList(ids));
	}

	@Test
	public void anAnswerIsTheNewView()
	{
		FarmRunClient.Result r = client.result(200, FarmRunsTest.ANSWER, "\"r1.2.1790000000000\"");
		assertEquals(FarmRunClient.Outcome.OK, r.outcome);
		assertNotNull(r.runs.active);
		assertEquals("\"r1.2.1790000000000\"", r.etag);
		assertEquals(FarmRunClient.Outcome.NOT_MODIFIED, client.result(304, "", null).outcome);
	}

	@Test
	public void theServersRefusalsReadOnFromTheChatLine()
	{
		// Each follows "Ironwise: couldn't <do it>: " in chat.
		String[][] answers = {
			{"401", "unauthorized", "this token isn't recognised. Make a new one on the app's Live data page."},
			{"403", "forbidden", "Ironwise hasn't had a sync of this account from this device yet."},
			{"404", "no_preset", "that saved run isn't on Ironwise any more."},
			{"409", "no_run", "there's no farm run in progress."},
			{"409", "no_stops", "none of that run's patches are open on this account yet."},
			{"409", "stale", "the run has moved on (it changed on the website). The box shows where it is now."},
			{"409", "first", "this is the first stop."},
			{"409", "finished", "the run is already finished."},
			{"400", "bad_request", "action must be start, advance, skip, previous or end."},
			{"400", "bad_request", "stop must be the patch the run box shows."},
			{"413", "too_large", "the request is too large."},
			{"503", "unavailable", "couldn't reach the farm runs on the server."},
		};
		for (String[] a : answers)
		{
			FarmRunClient.Result r = client.result(Integer.parseInt(a[0]), error(a[1], a[2]), null);
			assertEquals(a[1], FarmRunClient.Outcome.FAILED, r.outcome);
			assertEquals(a[1], a[2], r.message);
			assertNull(r.runs);
		}
	}

	@Test
	public void notIronwise()
	{
		assertEquals(SyncClient.NOT_IRONWISE, client.result(200, "<html>", null).message);
		assertEquals(FarmRunClient.NO_RUNS, client.result(404, "<html>", null).message);
		assertEquals(SyncClient.LOGIN, client.result(401, "<html>", null).message);
	}

	@Test
	public void theChatLineShowsTheServersWordsAsText()
	{
		// The chat box reads <col=…> and <img=…> as tags: a message from the server can't use them.
		assertEquals("Ironwise: couldn't skip the stop: this is the first stop.", FarmRunClient.couldnt("skip the stop", "this is the first stop."));
		assertEquals("Ironwise: couldn't end the run: <lt>img=1<gt> hi", FarmRunClient.couldnt("end the run", "<img=1> hi"));
	}

	@Test
	public void theRequests()
	{
		assertEquals("{\"accountHash\":\"-42\",\"action\":\"start\",\"presetId\":\"abcdEFGH\"}", client.body("-42", FarmRunClient.START, "abcdEFGH", null));
		assertEquals("{\"accountHash\":\"-42\",\"action\":\"advance\",\"stop\":\"herb-catherby\"}", client.body("-42", FarmRunClient.ADVANCE, null, "herb-catherby"));
		assertEquals("{\"accountHash\":\"-42\",\"action\":\"end\"}", client.body("-42", FarmRunClient.END, null, null));
		assertEquals("https://ironwise.example/api/plugin/runs?accountHash=-42", FarmRunClient.getUrl("https://ironwise.example/", "-42").toString());
		assertEquals("https://ironwise.example/api/plugin/runs", FarmRunClient.postUrl("ironwise.example").toString());
		assertNull(FarmRunClient.getUrl("http://ironwise.example", "-42"));
		assertEquals(Arrays.asList("start", "advance", "skip", "previous", "end"),
			Arrays.asList(FarmRunClient.START, FarmRunClient.ADVANCE, FarmRunClient.SKIP, FarmRunClient.PREVIOUS, FarmRunClient.END));
	}

	@Test
	public void theStateKeepsOnePollAndOneClickAtATime()
	{
		FarmRunState state = new FarmRunState();
		FarmRunState.Poll p = state.startPoll("-42", 100_000L);
		assertNotNull(p);
		assertNull(state.startPoll("-42", 100_001L)); // one in flight
		assertTrue(state.answered(p, client.result(200, FarmRunsTest.ANSWER, "\"e\""), 100_002L));
		assertNull(state.startPoll("-42", 105_000L)); // too soon
		assertNotNull(state.startPoll("-42", 110_002L));
		// Another account: the old answer is forgotten and a late answer for it is dropped.
		FarmRunState.Poll other = state.startPoll("-7", 110_003L);
		assertNotNull(other);
		assertNull(state.runs());
		assertTrue(state.startAct());
		assertEquals(false, state.startAct());
		// The click's answer (here, a failure) lets the next click go.
		assertEquals(false, state.answeredClick(state.session(), FarmRunClient.Result.failed("can't reach the app (timeout)"), 110_004L));
		assertTrue(state.startAct());
	}

	@Test
	public void aPollThatCrossedAClickIsDropped()
	{
		FarmRunState state = new FarmRunState();
		FarmRunState.Poll p = state.startPoll("-42", 100_000L);
		// The player skips a stop while the poll is on its way; the click's answer (the stop skipped) comes first.
		assertTrue(state.startAct());
		int session = state.session();
		String skipped = FarmRunsTest.ANSWER.replace("\"index\":0", "\"index\":1").replace("\"state\":\"current\"", "\"state\":\"skipped\"").replace("\"state\":\"todo\"", "\"state\":\"current\"");
		assertTrue(state.answeredClick(session, client.result(200, skipped, "\"r1.3.1\""), 100_100L));
		// Then the poll's answer, from before the click: dropped, so the box doesn't go back to the stop just skipped.
		assertEquals(false, state.answered(p, client.result(200, FarmRunsTest.ANSWER, "\"r1.2.1\""), 100_200L));
		assertEquals(1, state.active().index);
		assertNotNull(state.startPoll("-42", 110_200L)); // and polling carries on
	}

	@Test
	public void aPollSentWhileAClickIsOnItsWayIsDroppedToo()
	{
		FarmRunState state = new FarmRunState();
		assertTrue(state.answered(state.startPoll("-42", 100_000L), client.result(200, FarmRunsTest.ANSWER, "\"r1.2.1\""), 100_000L));
		// The player skips a stop; before Ironwise answers, the next poll goes out (a sync changed the ETag meanwhile,
		// so Ironwise answers it in full, as it read the run: maybe before the skip was saved).
		assertTrue(state.startAct());
		int session = state.session();
		FarmRunState.Poll p = state.startPoll("-42", 110_000L);
		assertNotNull(p);
		String skipped = FarmRunsTest.ANSWER.replace("\"index\":0", "\"index\":1").replace("\"state\":\"current\"", "\"state\":\"skipped\"").replace("\"state\":\"todo\"", "\"state\":\"current\"");
		assertTrue(state.answeredClick(session, client.result(200, skipped, "\"r1.3.2\""), 110_100L));
		// The poll's answer comes last, from before the skip: dropped, so the box doesn't go back to the stop just skipped.
		assertEquals(false, state.answered(p, client.result(200, FarmRunsTest.ANSWER, "\"r1.2.2\""), 110_200L));
		assertEquals(1, state.active().index);
		// A poll sent once no click is on its way is taken as before.
		FarmRunState.Poll next = state.startPoll("-42", 120_200L);
		assertTrue(state.answered(next, client.result(200, FarmRunsTest.ANSWER, "\"r1.4.3\""), 120_300L));
		assertEquals(0, state.active().index);
	}

	@Test
	public void failedPollsWaitLongerAndSayWhy()
	{
		FarmRunState state = new FarmRunState();
		long now = 0;
		FarmRunState.Poll p = state.startPoll("-42", now);
		// The side panel has something new to say: why.
		assertTrue(state.answered(p, client.result(401, error("unauthorized", "this token isn't recognised."), null), now));
		assertEquals("this token isn't recognised.", state.problem());
		assertNull(state.runs());
		// 20 s, then 40 s, then at most a minute between tries.
		assertNull(state.startPoll("-42", now + 19_999L));
		p = state.startPoll("-42", now += 20_000L);
		assertNotNull(p);
		state.answered(p, client.result(503, "", null), now);
		assertNull(state.startPoll("-42", now + 39_999L));
		p = state.startPoll("-42", now += 40_000L);
		state.answered(p, client.result(503, "", null), now);
		p = state.startPoll("-42", now += 60_000L);
		assertNotNull(p);
		state.answered(p, client.result(503, "", null), now);
		assertNull(state.startPoll("-42", now + 59_999L));
		// An answer: back to every 10 s, and nothing to say.
		p = state.startPoll("-42", now += 60_000L);
		assertTrue(state.answered(p, client.result(200, FarmRunsTest.ANSWER, "\"e\""), now));
		assertNull(state.problem());
		assertNotNull(state.startPoll("-42", now + FarmRunState.POLL_MS));
	}

	@Test
	public void theBankHighlightsIdsAreWorkedOutOncePerAnswer()
	{
		FarmRunState state = new FarmRunState();
		assertTrue(state.bankIds().isEmpty());
		state.answered(state.startPoll("-42", 1L), client.result(200, FarmRunsTest.ANSWER, "\"e\""), 2L);
		assertEquals(ids(5295, 952), state.bankIds());
		assertSame(state.bankIds(), state.bankIds()); // the same set, not a new one each frame
	}

	@Test
	public void aPickedRunIsOutlinedBeforeItStarts()
	{
		FarmRunState state = new FarmRunState();
		// Nothing to pick from yet.
		state.pick("abcdEFGH");
		assertNull(state.picked());
		state.answered(state.startPoll("-42", 1L), client.result(200, FarmRunsTest.NO_RUN, "\"e\""), 2L);
		assertTrue(state.bankIds().isEmpty());
		// Picked in the side panel: its Bring list, from the list Ironwise sent (bringItemIds).
		state.pick("abcdEFGH");
		assertEquals("abcdEFGH", state.picked());
		assertEquals(ids(952, 5295), state.bankIds());
		state.pick("builtin-trees");
		assertEquals(ids(952, 5343, 8431), state.bankIds());
		// Picking it again unpicks it; a run Ironwise didn't list can't be picked.
		state.pick("builtin-trees");
		assertNull(state.picked());
		assertTrue(state.bankIds().isEmpty());
		state.pick("zzzzzzzz");
		assertNull(state.picked());
		// Started (here or on the website): the run's own Bring list; finished, the pick again.
		state.pick("builtin-trees");
		String trees = "\"bringItemIds\":[952,5295]},{\"id\":\"builtin-trees\",\"name\":\"Tree run\",\"icon\":\"tree\",\"stops\":3,\"bringItemIds\":[952,5343,8431]}]";
		String running = FarmRunsTest.ANSWER.replace("\"bringItemIds\":[952,5295]}]", trees);
		state.answered(state.startPoll("-42", 20_000L), client.result(200, running, "\"f\""), 20_001L);
		assertEquals("builtin-trees", state.picked());
		assertEquals(ids(5295, 952), state.bankIds());
		String finished = running.replace("\"index\":0,\"finished\":false", "\"index\":2,\"finished\":true");
		state.answered(state.startPoll("-42", 40_000L), client.result(200, finished, "\"g\""), 40_001L);
		assertEquals(ids(952, 5343, 8431), state.bankIds());
		// A run deleted on the website is no longer picked.
		state.answered(state.startPoll("-42", 60_000L), client.result(200, FarmRunsTest.ANSWER, "\"h\""), 60_001L);
		assertNull(state.picked());
		// Another account forgets the pick.
		state.pick("abcdEFGH");
		state.startPoll("-7", 80_000L);
		assertNull(state.picked());
		assertTrue(state.bankIds().isEmpty());
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

/** The controller's clicks: each names the stop the box shows (so a click the run has moved past is refused), in words for chat. */
public class FarmRunControllerTest
{
	private static FarmRuns.Active run(String answer)
	{
		return FarmRuns.parse(FarmRunsTest.json(answer)).active;
	}

	@Test
	public void skipAndPreviousNameTheStopTheBoxShows()
	{
		assertEquals("herb-catherby", FarmRunController.shownStop(run(FarmRunsTest.ANSWER)));
		String second = FarmRunsTest.ANSWER.replace("\"index\":0", "\"index\":1");
		assertEquals("birdhouse-valley-north", FarmRunController.shownStop(run(second)));
		// A finished run shows its last stop (Ironwise's stepRun: "previous" names it).
		String finished = FarmRunsTest.ANSWER.replace("\"index\":0,\"finished\":false", "\"index\":2,\"finished\":true");
		assertEquals("birdhouse-valley-north", FarmRunController.shownStop(run(finished)));
		assertNull(FarmRunController.shownStop(null));
	}

	@Test
	public void theClicksInWords()
	{
		assertEquals("start the run", FarmRunController.words(FarmRunClient.START));
		assertEquals("skip the stop", FarmRunController.words(FarmRunClient.SKIP));
		assertEquals("go back a stop", FarmRunController.words(FarmRunClient.PREVIOUS));
		assertEquals("end the run", FarmRunController.words(FarmRunClient.END));
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.HashTable;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.PluginMessage;
import net.runelite.http.api.RuneLiteAPI;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import org.junit.Test;

/**
 * The controller as the client thread drives it (0.5.0 review): polls, Ironwise's answers, the player's position and
 * patch values tick by tick, the advance it sends, the player's clicks, logging out and hopping, and Shortest Path.
 * Ironwise holds each request until the test answers it. Made-up account and values only.
 */
public class FarmRunFlowTest
{
	private static final String TABLES = "{\"HERB\":[[0,3,\"empty\"],[32,35,\"planted\"],[36,38,\"harvest\"]],\"FLOWER\":[[0,3,\"empty\"],[8,11,\"planted\"],[12,12,\"harvest\"]]}";
	private static final String RULES = "[{\"from\":[\"empty\",\"grown\",\"harvest\",\"diseased\",\"dead\"],\"to\":\"planted\"}]";
	private static final int HERB = 4774;
	private static final int FLOWER = 4773;
	/** Catherby's patches, region 11062. */
	private static final WorldPoint CATHERBY = new WorldPoint(2810, 3464, 0);

	private static String stop(String id, String state, int varbit, String impl, int x)
	{
		return "{\"patchId\":\"" + id + "\",\"name\":\"" + id + "\",\"type\":\"herb\",\"cluster\":\"catherby\",\"state\":\"" + state + "\",\"point\":{\"x\":" + x + ",\"y\":3464,\"plane\":0},"
			+ "\"watch\":{\"kind\":\"varbit\",\"varbit\":" + varbit + ",\"impl\":\"" + impl + "\",\"regions\":[11062],\"bounds\":null,\"doneWhen\":" + RULES + "}}";
	}

	/** Catherby's herb and flower patches (one cluster), then Falador's herb patch; `index` is the current stop. */
	static String view(int index, String herb, String flower, String falador)
	{
		return "{\"ok\":true,\"rev\":\"r" + index + herb + flower + "\",\"presets\":[{\"id\":\"abcdEFGH\",\"name\":\"Herbs\",\"icon\":\"herb\",\"stops\":3,\"bringItemIds\":[952,5295]}],"
			+ "\"tables\":" + TABLES + ",\"active\":{\"presetId\":\"abcdEFGH\",\"name\":\"Herbs\",\"index\":" + index + ",\"finished\":false,\"startedAt\":1,\"stops\":["
			+ stop("herb-catherby", herb, HERB, "HERB", 2810) + "," + stop("flower-catherby", flower, FLOWER, "FLOWER", 2811) + ","
			+ "{\"patchId\":\"herb-falador\",\"name\":\"Falador\",\"type\":\"herb\",\"cluster\":\"falador-farm\",\"state\":\"" + falador + "\",\"point\":{\"x\":3058,\"y\":3311,\"plane\":0},\"watch\":null}],"
			+ "\"bring\":[{\"itemIds\":[5295],\"name\":\"Ranarr seed\",\"qty\":1,\"have\":1}]}}";
	}

	static final String NO_RUN = "{\"ok\":true,\"rev\":\"r-none\",\"presets\":[{\"id\":\"abcdEFGH\",\"name\":\"Herbs\",\"icon\":\"herb\",\"stops\":3,\"bringItemIds\":[952,5295]}],\"active\":null,\"tables\":{}}";

	/** RuneLite's client thread: the test is the client thread, so what's handed to it runs at once. */
	private static final class Now extends ClientThread
	{
		@Override
		public void invokeLater(Runnable r)
		{
			r.run();
		}
	}

	/** Ironwise, holding each request until the test answers it. */
	private static final class Ironwise extends FarmRunClient
	{
		final List<Listener> polls = new ArrayList<>();
		final List<String> posts = new ArrayList<>();
		final List<Listener> postAnswers = new ArrayList<>();

		Ironwise()
		{
			super(new SyncClient(new OkHttpClient(), RuneLiteAPI.GSON), RuneLiteAPI.GSON);
		}

		@Override
		void get(HttpUrl url, String token, String etag, Listener listener)
		{
			polls.add(listener);
		}

		@Override
		void post(HttpUrl url, String token, String json, Listener listener)
		{
			posts.add(json);
			postAnswers.add(listener);
		}

		void answerPoll(String json)
		{
			polls.remove(0).done(result(200, json, "\"" + json.hashCode() + "\""));
		}

		void answerPost(String json)
		{
			postAnswers.remove(0).done(result(200, json, "\"" + json.hashCode() + "\""));
		}

		void failPost(String message)
		{
			postAnswers.remove(0).done(FarmRunClient.Result.failed(message));
		}
	}

	/** A logged-in player on a standard world: where they stand, the patch values, and the chat lines added. */
	private static final class Game
	{
		WorldPoint at = CATHERBY;
		GameState state = GameState.LOGGED_IN;
		final Map<Integer, Integer> varbits = new HashMap<>();
		final List<String> chat = new ArrayList<>();

		private final Player player = (Player) Proxy.newProxyInstance(Player.class.getClassLoader(), new Class<?>[]{Player.class}, (proxy, method, args) ->
		{
			if ("getWorldLocation".equals(method.getName()))
			{
				return at;
			}
			throw new AssertionError("the controller called Player." + method.getName());
		});

		private final HashTable<?> noInterfaces = (HashTable<?>) Proxy.newProxyInstance(HashTable.class.getClassLoader(), new Class<?>[]{HashTable.class}, (proxy, method, args) ->
		{
			if ("iterator".equals(method.getName()))
			{
				return Collections.emptyIterator();
			}
			throw new AssertionError("the controller called HashTable." + method.getName());
		});

		final Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			switch (method.getName())
			{
				case "getAccountHash":
					return state == GameState.LOGIN_SCREEN ? -1L : 42L;
				case "getGameState":
					return state;
				case "getLocalPlayer":
					return player;
				case "getWidget":
					return null;
				case "getComponentTable":
					return noInterfaces;
				case "getVarbitValue":
					return varbits.getOrDefault((Integer) args[0], 0);
				case "addChatMessage":
					chat.add((String) args[2]);
					return null;
				default:
					throw new AssertionError("the controller called Client." + method.getName());
			}
		});
	}

	private static final class Settings implements IronwiseConfig
	{
		String address = IronwiseConfig.DEFAULT_ADDRESS;
		final AtomicBoolean path = new AtomicBoolean(true);

		@Override
		public boolean syncEnabled()
		{
			return true;
		}

		@Override
		public boolean farmRuns()
		{
			return true;
		}

		@Override
		public String serverUrl()
		{
			return address;
		}

		@Override
		public String token()
		{
			return "made-up-token";
		}

		@Override
		public boolean farmRunShortestPath()
		{
			return path.get();
		}
	}

	private final Game game = new Game();
	private final Settings settings = new Settings();
	private final Ironwise ironwise = new Ironwise();
	private final FarmRunState state = new FarmRunState();
	private final List<PluginMessage> messages = new ArrayList<>();
	private final FarmRunController controller = new FarmRunController(game.client, new Now(), settings, null, ironwise, state,
		new ShortestPath(messages::add, () -> true), null, null);
	private long now = System.currentTimeMillis();
	/** Why syncing stopped (the plugin's chat line), or null while it works. */
	private String syncStopped;

	/** One game tick with these patch values. */
	private void tick(int herb, int flower)
	{
		game.varbits.put(HERB, herb);
		game.varbits.put(FLOWER, flower);
		controller.onGameTick(now, syncStopped);
		now += 600;
	}

	/** The first poll, answered with this view, and the ticks it takes the patches to settle. */
	private void started(String view, int herb, int flower)
	{
		tick(herb, flower);
		ironwise.answerPoll(view);
		for (int i = 0; i < 4; i++)
		{
			tick(herb, flower);
		}
	}

	/** A request's action and stop ("advance herb-catherby"). */
	private static String action(String post)
	{
		return post.replaceAll(".*\"action\":\"([a-z]+)\".*", "$1") + (post.contains("\"stop\"") ? " " + post.replaceAll(".*\"stop\":\"([a-z-]+)\".*", "$1") : "");
	}

	/** Every request sent so far, in words. */
	private List<String> actions()
	{
		List<String> out = new ArrayList<>();
		for (String p : ironwise.posts)
		{
			out.add(action(p));
		}
		return out;
	}

	@Test
	public void aPatchDealtWithIsSentAndTheBoxMovesOn()
	{
		started(view(0, "current", "todo", "todo"), 36, 12);
		assertTrue(ironwise.posts.isEmpty());
		tick(3, 12); // herbs picked, weeds raked
		tick(32, 12); // planted
		assertEquals(Collections.singletonList("advance herb-catherby"), actions());
		ironwise.answerPost(view(1, "done", "current", "todo"));
		tick(32, 12);
		assertEquals("flower-catherby", state.active().current().patchId);
		// Shortest Path was pointed at the herb patch, then at the flower patch.
		assertEquals(2, messages.size());
		assertEquals(new WorldPoint(2811, 3464, 0), messages.get(1).getData().get(ShortestPath.TARGET));
	}

	@Test
	public void twoPatchesDoneOutOfOrderBothReachIronwise()
	{
		started(view(0, "current", "todo", "todo"), 36, 12);
		tick(36, 3);
		tick(36, 8); // the flower (not the stop the box shows) replanted first
		assertEquals(Collections.singletonList("advance flower-catherby"), actions());
		tick(3, 8);
		tick(32, 8); // then the herb, before Ironwise has answered for the flower
		assertEquals(1, ironwise.posts.size()); // one request at a time
		ironwise.answerPost(view(0, "current", "done", "todo"));
		tick(32, 8);
		assertEquals(2, ironwise.posts.size());
		assertEquals("advance herb-catherby", action(ironwise.posts.get(1)));
		ironwise.answerPost(view(2, "done", "done", "current"));
		tick(32, 8);
		assertEquals("herb-falador", state.active().current().patchId);
		assertEquals(2, ironwise.posts.size());
	}

	@Test
