	@Test
	public void aBadAddressIsSaidInThePanelNotWaitedOnForever()
	{
		settings.address = "http://ironwise.example";
		tick(0, 0);
		assertTrue(ironwise.polls.isEmpty());
		assertTrue(state.problem(), state.problem() != null && state.problem().contains("https://"));
		// Fixed: polling starts again.
		settings.address = IronwiseConfig.DEFAULT_ADDRESS;
		controller.addressChanged();
		tick(0, 0);
		assertEquals(1, ironwise.polls.size());
	}

	@Test
	public void whileSyncingIsStoppedNothingGoesToIronwise()
	{
		started(view(0, "current", "todo", "todo"), 36, 12);
		now += FarmRunState.POLL_MS;
		tick(36, 12); // a poll on its way
		assertEquals(1, ironwise.polls.size());
		// The sync stops on a bad token, a problem only the player can fix: the run goes, with the path this plugin
		// drew, and the side panel says why.
		syncStopped = "Ironwise: " + SyncClient.BAD_TOKEN;
		tick(36, 12);
		assertNull(state.runs());
		assertEquals(SyncClient.BAD_TOKEN, state.problem());
		assertEquals(ShortestPath.CLEAR, messages.get(messages.size() - 1).getName());
		// The poll's answer, from before, is dropped.
		ironwise.answerPoll(view(0, "current", "todo", "todo"));
		assertNull(state.runs());
		// However long it stays stopped, whatever the patches do and whatever the player clicks: nothing is sent.
		now += 10 * FarmRunState.MAX_POLL_WAIT_MS;
		tick(3, 12);
		tick(32, 12);
		tick(32, 12);
		controller.act(FarmRunClient.START, "abcdEFGH");
		assertTrue(ironwise.polls.isEmpty());
		assertTrue(ironwise.posts.isEmpty());
		assertEquals(SyncClient.BAD_TOKEN, state.problem());
		// A new token: the plugin clears the stop and the farm runs start again at once.
		syncStopped = null;
		controller.addressChanged();
		tick(32, 12);
		assertEquals(1, ironwise.polls.size());
		ironwise.answerPoll(view(0, "current", "todo", "todo"));
		assertEquals("herb-catherby", state.active().current().patchId);
		assertNull(state.problem());
	}

	@Test
	public void aStopThatOutlivesALogoutStillSaysWhy()
	{
		syncStopped = "Ironwise: " + SyncClient.BAD_TOKEN;
		tick(0, 0);
		game.state = GameState.LOGIN_SCREEN;
		controller.loggedOut();
		assertNull(state.problem());
		// Logged in again, still stopped (only a settings change clears it): the panel says why again, nothing is sent.
		game.state = GameState.LOGGED_IN;
		tick(0, 0);
		assertEquals(SyncClient.BAD_TOKEN, state.problem());
		assertTrue(ironwise.polls.isEmpty());
	}

	@Test
	public void aFailedAdvanceIsTriedAgainQuietly()
	{
		started(view(0, "current", "todo", "todo"), 36, 12);
		tick(3, 12);
		tick(32, 12);
		ironwise.failPost("can't reach the app (timeout)");
		assertTrue(game.chat.isEmpty());
		tick(32, 12);
		assertEquals(1, ironwise.posts.size()); // not straight away
		now += FarmRunState.POLL_MS;
		tick(32, 12);
		assertEquals(2, ironwise.posts.size());
		assertEquals("advance herb-catherby", action(ironwise.posts.get(1)));
	}
}

