/**
 * The run box's lines and menu, the Next step box stepping aside, Shortest Path's messages (its exact API at the pin)
 * and the bank highlight's items.
 */
public class FarmRunOverlayTest
{
	/** About 40 characters a line. */
	private static final Predicate<String> FITS_40 = s -> s.length() <= 40;

	/** The settings as RuneLite's ConfigManager would keep them: syncing and farm runs ticked, the rest at their defaults. */
	private static final class Settings implements IronwiseConfig
	{
		final AtomicBoolean box = new AtomicBoolean(true);

		@Override
		public boolean syncEnabled()
		{
			return true;
		}

		@Override
		public boolean farmRuns()
		{
			return true;
		}

		@Override
		public boolean farmRunBox()
		{
			return box.get();
		}
	}

	private static FarmRuns.Active run(String answer)
	{
		return FarmRuns.parse(FarmRunsTest.json(answer)).active;
	}

	/** The state after one poll answered with this answer. */
	private static FarmRunState state(String answer)
	{
		FarmRunState state = new FarmRunState();
		FarmRunClient client = new FarmRunClient(new SyncClient(new OkHttpClient(), RuneLiteAPI.GSON), RuneLiteAPI.GSON);
		state.answered(state.startPoll("-42", 1L), client.result(200, answer, "\"e\""), 2L);
		return state;
	}

	/** A logged-in Client on a standard world that records chat lines and fails on anything else. */
	private static Client loggedIn(List<Object[]> chat)
	{
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			switch (method.getName())
			{
				case "getGameState":
					return GameState.LOGGED_IN;
				case "getWorldType":
					return EnumSet.noneOf(WorldType.class);
				case "addChatMessage":
					chat.add(args);
					return null;
				default:
					throw new AssertionError("the box called Client." + method.getName());
			}
		});
	}

	/** The pinned answer with the first stop's way there replaced (the app's PluginTeleport, word for word). */
	static String withRoute(String route)
	{
		return FarmRunsTest.ANSWER.replace("\"teleport\":{\"label\":\"Camelot Teleport\",\"itemIds\":[],\"condition\":null}", "\"teleport\":" + route);
	}

	@Test
	public void theBoxSaysWhereYouAreAndHowToGetThere()
	{
		// The way there as Ironwise words it, as it is: a teleport's name reads on its own.
		assertEquals(Arrays.asList("Farm run · 1 of 2", "Herb patch, Catherby", "Camelot Teleport"), FarmRunOverlay.lines(run(FarmRunsTest.ANSWER), null));
		assertEquals(Arrays.asList("Farm run · 1 of 2", "Herb patch, Catherby", "Camelot Teleport", StopWatcher.GROWING), FarmRunOverlay.lines(run(FarmRunsTest.ANSWER), StopWatcher.GROWING));
		String finished = FarmRunsTest.ANSWER.replace("\"index\":0,\"finished\":false", "\"index\":2,\"finished\":true");
		assertEquals(Arrays.asList("Farm run done", "Shift + right-click the box: End run."), FarmRunOverlay.lines(run(finished), null));
		// A walk to the next patch of the same place (or no route Ironwise knows): no line for it.
		assertEquals(Arrays.asList("Farm run · 1 of 2", "Herb patch, Catherby"), FarmRunOverlay.lines(run(withRoute("null")), null));
	}

	@Test
	public void runsAndTheHomeTeleportReadAsThemselves()
	{
		// A run from the stop before and the home teleport: no items, nothing Ironwise can't confirm.
		String run = withRoute("{\"label\":\"Run from the last stop\",\"itemIds\":[],\"condition\":null}");
		assertEquals(Arrays.asList("Farm run · 1 of 2", "Herb patch, Catherby", "Run from the last stop"), FarmRunOverlay.lines(run(run), null));
		String home = withRoute("{\"label\":\"Home teleport \u2192 Lumbridge\",\"itemIds\":[],\"condition\":null}");
		assertEquals(Arrays.asList("Farm run · 1 of 2", "Herb patch, Catherby", "Home teleport -> Lumbridge"), FarmRunOverlay.lines(run(home), null));
	}

	@Test
	public void aRouteIronwiseCantConfirmSaysWhatItHangsOn()
	{
		// The stop's only route hangs on something Ironwise can't see: its condition after it, as the site words it, and
		// the whole route in its own colour, so it never reads as certain.
		String cloak = withRoute("{\"label\":\"Ardougne cloak 2 → Farm\",\"itemIds\":[13122],\"condition\":\"if you still have a teleport left today\"}");
		FarmRuns.Active a = run(cloak);
		assertEquals("if you still have a teleport left today", a.current().teleport.condition);
		assertArrayEquals(new int[]{13122}, a.current().teleport.itemIds);
		assertEquals(Arrays.asList("Farm run · 1 of 2", "Herb patch, Catherby", "Ardougne cloak 2 -> Farm (if you still have a teleport left today)", StopWatcher.GROWING),
			FarmRunOverlay.lines(a, StopWatcher.GROWING));
		assertNotEquals(Color.WHITE, FarmRunOverlay.CONDITION);
		List<FarmRunOverlay.Row> rows = FarmRunOverlay.rows(a, StopWatcher.GROWING, FITS_40);
		assertEquals(Arrays.asList("Herb patch, Catherby", "Ardougne cloak 2 -> Farm (if you still", "have a teleport left today)", "Still growing. Shift + right-click the", "box: Skip stop."),
			rows.stream().map(r -> r.text).collect(Collectors.toList()));
		Color c = FarmRunOverlay.CONDITION;
		assertEquals(Arrays.asList(Color.WHITE, c, c, FarmRunOverlay.MUTED, FarmRunOverlay.MUTED), rows.stream().map(r -> r.colour).collect(Collectors.toList()));
		// A route Ironwise can confirm: white.
		assertEquals(Color.WHITE, FarmRunOverlay.rows(run(FarmRunsTest.ANSWER), null, FITS_40).get(1).colour);
	}

	/** A line of the box at its default width, in the font RuneLite draws overlays in by default. */
	private static Predicate<String> boxWidth()
	{
		Graphics2D g = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		g.setFont(FontManager.getRunescapeFont());
		FontMetrics metrics = g.getFontMetrics();
		g.dispose();
		return s -> metrics.stringWidth(s) <= FarmRunOverlay.WIDTH - 2 * ComponentConstants.STANDARD_BORDER;
	}

	/**
	 * The app's longest run box routes (src/lib/farm/integration.test.ts RUN_BOX_LONGEST) and the ones a player sees most:
	 * the way there takes at most the box's 3 route lines, the two digsite pendant and mushtree routes (never the plan's
	 * route while the barge is one Ironwise can confirm) a 4th, and nothing is ever cut short.
	 */
	@Test
	public void theWayThereFitsTheBoxsThreeRouteLinesNeverCutShort()
	{
		Predicate<String> fits = boxWidth();
		String[] three = {
			"Run from the last stop",
			"Home teleport -> Lumbridge",
			"Home teleport -> Lumbridge (if it's off its cooldown)",
			"Home teleport -> Lumbridge (if you're on the standard spellbook and it's off its cooldown)",
			"Home teleport -> Dark Altar (if you're on the Arceuus spellbook and it's off its cooldown)",
			"Ardougne cloak 2 -> Farm (if you still have a teleport left today)",
			"Explorer's ring 2 -> cabbage patch (if you still have a teleport left today)",
			"Civitas illa Fortis Teleport, then the quetzal (if you've built its landing site)",
			"Spirit tree to Battlefield of Khazard via your house (Teleport to House)",
			"Spirit tree to the Farming Guild (if spirit trees grow there and at Brimhaven)",
			"Digsite pendant -> Fossil Island, then the rowboat (if its Fossil Island teleport is unlocked)",
			"Rimmington teleport tablet, the ship to Corsair Cove, then the rowboat (if you've built it)",
			"Spirit tree to Port Sarim via your house (Teleport to House) (if a spirit tree grows there)",
			"Spirit tree to the Farming Guild via your house (Teleport to House) (if a spirit tree grows there)",
			"Spirit tree to the Farming Guild via your house (house tablet) (if a spirit tree grows there)",
		};
		for (String route : three)
		{
			List<String> lines = FarmRunOverlay.routeLines(route, fits);
			assertTrue(route + ": " + lines, lines.size() <= FarmRunOverlay.ROUTE_LINES);
			assertEquals(route, route, String.join(" ", lines));
		}
		String[] four = {
			"Digsite pendant, then the mushtree to Mushroom Meadow (if its Fossil Island teleport is unlocked, and more)",
			"Digsite pendant, then the mushtree to Verdant Valley (if its Fossil Island teleport is unlocked, and more)",
		};
		for (String route : four)
		{
			List<String> lines = FarmRunOverlay.routeLines(route, fits);
			assertEquals(route + ": " + lines, FarmRunOverlay.ROUTE_LINES + 1, lines.size());
			assertEquals(route, route, String.join(" ", lines)); // whole: a 4th line rather than cut short
		}
	}

	@Test
	public void theBoxHasSkipPreviousEndAndHide()
	{
		FarmRunOverlay overlay = new FarmRunOverlay(new IronwisePlugin(), null, new Settings(), new FarmRunState(), null);
		List<OverlayMenuEntry> entries = overlay.getMenuEntries();
		assertEquals(Arrays.asList("Skip stop", "Previous stop", "End run", "Hide"),
			entries.stream().map(OverlayMenuEntry::getOption).collect(Collectors.toList()));
		// RuneLite overlay entries (Shift + right-click on the box), not game menu options.
		for (OverlayMenuEntry e : entries)
		{
			assertEquals(e.getOption(), MenuAction.RUNELITE_OVERLAY, e.getMenuAction());
			assertEquals(e.getOption(), "Farm run", e.getTarget());
		}
	}

	@Test
	public void hidingUnticksShowTheRunBoxAndSaysHowToGetItBack()
	{
		List<Object[]> writes = new ArrayList<>();
		List<Object[]> chat = new ArrayList<>();
		FarmRunOverlay.hide((group, key, value) -> writes.add(new Object[]{group, key, value}), loggedIn(chat));
		assertEquals(1, writes.size());
		assertArrayEquals(new Object[]{"ironwise", "farmRunBox", false}, writes.get(0));
		assertEquals(1, chat.size());
		assertArrayEquals(new Object[]{ChatMessageType.GAMEMESSAGE, "", FarmRunOverlay.HIDDEN, null}, chat.get(0));
	}

	@Test
	public void theBoxShowsDuringARunAndTheNextStepBoxStepsAside() throws ReflectiveOperationException
	{
		Settings settings = new Settings();
		Client client = loggedIn(new ArrayList<>());
		Graphics2D graphics = new BufferedImage(400, 400, BufferedImage.TYPE_INT_ARGB).createGraphics();
		FarmRunState running = state(FarmRunsTest.ANSWER);
		FarmRunOverlay box = new FarmRunOverlay(new IronwisePlugin(), client, settings, running, null);
		Dimension size = box.render(graphics);
		assertNotNull(size);
		assertTrue(size.height > 0);
		// No run on: no box.
		assertNull(new FarmRunOverlay(new IronwisePlugin(), client, settings, state(FarmRunsTest.NO_RUN), null).render(graphics));

		GuideState guide = new GuideState();
		guide.synced(guide.session(), "1234567890123456789", 1, NextStep.fromBody(RuneLiteAPI.GSON, "{\"guide\":" + NextStepTest.stepJson() + "}", "guide"));
		NextStepOverlay next = new NextStepOverlay(new IronwisePlugin(), client, settings, guide);
		assertNotNull(next.render(graphics)); // built by hand (no farm runs): as in 0.4.1
		Field f = NextStepOverlay.class.getDeclaredField("farmRuns");
		f.setAccessible(true);
		f.set(next, running);
		assertNull(next.render(graphics)); // the run box has the corner
		settings.box.set(false);
		assertNull(box.render(graphics)); // the run box hidden...
		assertNotNull(next.render(graphics)); // ...so the Next step box is back
		f.set(next, state(FarmRunsTest.NO_RUN));
		settings.box.set(true);
		assertNotNull(next.render(graphics)); // no run on
		graphics.dispose();
	}

	@Test
	public void shortestPathMessages()
	{
		PluginMessage path = ShortestPath.path(new FarmRuns.Point(2810, 3464, 0));
		assertEquals("shortestpath", path.getNamespace());
		assertEquals("path", path.getName());
		Map<String, Object> data = path.getData();
		assertEquals(Collections.singleton("target"), data.keySet());
		assertEquals(new WorldPoint(2810, 3464, 0), data.get("target"));
		PluginMessage clear = ShortestPath.clear();
		assertEquals("shortestpath", clear.getNamespace());
		assertEquals("clear", clear.getName());
		assertTrue(clear.getData().isEmpty());
	}

	@Test
	public void shortestPathIsToldOnlyWhenTheTargetChanges()
	{
		List<PluginMessage> posted = new ArrayList<>();
		AtomicBoolean on = new AtomicBoolean(true);
		ShortestPath sp = new ShortestPath(posted::add, on::get);
		FarmRuns.Point a = new FarmRuns.Point(1, 2, 0);
		sp.show(a);
		sp.show(a);
		assertEquals(Collections.singletonList(ShortestPath.path(a)), posted);
		sp.show(null);
		sp.show(null);
		assertEquals(Arrays.asList(ShortestPath.path(a), ShortestPath.clear()), posted);
		// Shortest Path switched off: nothing is sent, nothing remembered, so switching it back on draws the way again.
		posted.clear();
		sp.show(a);
		on.set(false);
		sp.show(a);
		on.set(true);
		sp.show(a);
		assertEquals(Arrays.asList(ShortestPath.path(a), ShortestPath.path(a)), posted);
		// Never a clear for a path this plugin didn't set.
		posted.clear();
		on.set(false);
		sp.show(a);
		sp.show(null);
		assertTrue(posted.isEmpty());
	}

	@Test
	public void theBankHighlightsTheBringList()
	{
		assertEquals(new HashSet<>(Arrays.asList(5295, 952)), BankHighlightOverlay.ids(run(FarmRunsTest.ANSWER)));
		assertTrue(BankHighlightOverlay.ids((FarmRuns.Active) null).isEmpty());
		FarmRuns listed = FarmRuns.parse(FarmRunsTest.json(FarmRunsTest.NO_RUN));
		assertEquals(new HashSet<>(Arrays.asList(952, 5343, 8431)), BankHighlightOverlay.ids(listed, "builtin-trees"));
		assertTrue(BankHighlightOverlay.ids(listed, null).isEmpty());
		assertTrue(BankHighlightOverlay.ids(null, "builtin-trees").isEmpty());
	}

	@Test
	public void theRunBoxLinesAreCompact()
	{
		// Like the Next step box: its width, the stop and the hint on up to two lines, the way there on up to three.
		assertEquals(NextStepOverlay.WIDTH, FarmRunOverlay.WIDTH);
		assertEquals(2, FarmRunOverlay.STOP_LINES);
		assertEquals(3, FarmRunOverlay.ROUTE_LINES);
		assertFalse(FarmRunOverlay.HIDDEN.isEmpty());
	}
}

package com.ironwise;

