/** What the side panel shows, as a model (the Swing panel only lays it out), and that server text stays text in Swing. */
public class FarmRunPanelTest
{
	private static FarmRuns runs(String answer)
	{
		return FarmRuns.parse(FarmRunsTest.json(answer));
	}

	private static FarmRunPanel.Model model(String answer, String picked)
	{
		return FarmRunPanel.Model.of(runs(answer), picked, null, true, true);
	}

	@Test
	public void savedRunsWhenNoRunIsOn()
	{
		FarmRunPanel.Model m = model(FarmRunsTest.NO_RUN, null);
		// Each run: its picture (its type's best crop, as an item sprite), name, stops and minutes, "—" when unknown.
		assertEquals(Arrays.asList("Herbs", "Tree run"), m.presetNames);
		assertEquals(Arrays.asList("2 stops · 7 min", "3 stops · — min"), m.presetDetails);
		// Minutes that count a route Ironwise can't confirm: a guess, as the site's "Total ≈".
		FarmRunPanel.Model guess = model(FarmRunsTest.NO_RUN.replace("\"minutes\":7,\"minutesUnsure\":false", "\"minutes\":7,\"minutesUnsure\":true"), null);
		assertEquals(Arrays.asList("2 stops · ~7 min", "3 stops · — min"), guess.presetDetails);
		assertEquals(Arrays.asList(257, null), m.presetIcons);
		assertEquals(Arrays.asList("abcdEFGH", "builtin-trees"), m.presetIds);
