		assertEquals("<html>&lt;b&gt;Herbs&lt;/b&gt; &#39;n&#39; trees</html>", FarmRunPanel.html("<b>Herbs</b> 'n' trees", 0));
		// Wrapped to the panel's width: only the wrapper is HTML.
		assertEquals("<html><div style=\"width:150px\">&lt;b&gt;Herbs&lt;/b&gt;</div></html>", FarmRunPanel.html("<b>Herbs</b>", 150));
