	@Test
	public void thePanelShowsHostileNamesAsText()
	{
		String hostile = "<html><b>Herbs</b><img src='http://x/a.png'>";
		String answer = FarmRunsTest.ANSWER.replace("\"name\":\"Herbs\"", "\"name\":\"" + hostile.replace("\"", "\\\"") + "\"")
			.replace("Herb patch, Catherby", "<html><u>Patch</u>");
		FarmRunPanel panel = new FarmRunPanel(null, new FarmRunPanel.Actions()
		{
		});
		panel.show(FarmRunPanel.Model.of(runs(answer), null, null, false, true));
		panel.show(FarmRunPanel.Model.of(runs(answer.replaceAll("\"active\":\\{.*\\},\"tables\"", "\"active\":null,\"tables\"")), "abcdEFGH", null, true, true));
		List<String> texts = new ArrayList<>();
		collect(panel, texts);
		assertTrue(texts.size() > 3);
		boolean sawName = false;
		for (String t : texts)
		{
			if (t.startsWith("<html>"))
			{
				String inner = t.replaceFirst("^<html>(<div style=\"width:\\d+px\">)?", "").replaceFirst("(</div>)?</html>$", "");
				assertFalse(t, inner.contains("<") || inner.contains(">"));
				sawName |= inner.contains("&lt;b&gt;Herbs&lt;/b&gt;");
			}
			else
			{
				assertFalse(t, t.contains("<"));
			}
		}
		assertTrue(texts.toString(), sawName);
	}

	private static void collect(Component c, List<String> out)
	{
		if (c instanceof JLabel && ((JLabel) c).getText() != null)
		{
			out.add(((JLabel) c).getText());
		}
		if (c instanceof AbstractButton && ((AbstractButton) c).getText() != null)
		{
			out.add(((AbstractButton) c).getText());
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				collect(child, out);
			}
		}
	}

	@Test
	public void pictures()
	{
		BufferedImage icon = FarmRunPanel.icon();
		assertEquals(16, icon.getWidth());
		assertEquals(16, icon.getHeight());
		// A tick for a stop done; each state its own mark.
		List<BufferedImage> marks = new ArrayList<>();
		for (String state : new String[]{"done", "skipped", "current", "todo"})
		{
			BufferedImage mark = FarmRunPanel.mark(state);
			assertNotNull(state, mark);
			for (BufferedImage other : marks)
			{
				assertNotEquals(state, Arrays.toString(pixels(other)), Arrays.toString(pixels(mark)));
			}
			marks.add(mark);
		}
	}

	@Test
	public void aStateIronwiseDidntNameSharesTheToDoMark()
	{
		// The marks are kept, one per state: a state the panel doesn't know is drawn (and kept) as a stop to come, so
		// whatever Ironwise sends, there are never more than four.
		assertSame(FarmRunPanel.mark("todo"), FarmRunPanel.mark("later"));
		assertSame(FarmRunPanel.mark("todo"), FarmRunPanel.mark("state-" + System.nanoTime()));
		assertEquals("Next: ", FarmRunPanel.Model.prefix("later"));
	}

	private static int[] pixels(BufferedImage img)
	{
		return img.getRGB(0, 0, img.getWidth(), img.getHeight(), null, 0, img.getWidth());
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.io.File;
