import org.junit.Test;

/**
 * The four farm run settings (new in 0.5.0): Farm runs, which talks to Ironwise, is off by default and carries RuneLite's
 * third-party server warning; the three that only draw are on, and nothing works until Sync with Ironwise is ticked too.
 */
public class FarmRunSettingsTest
{
	private static final IronwiseConfig DEFAULTS = new IronwiseConfig()
	{
	};

	private static ConfigItem item(String method) throws NoSuchMethodException
	{
		return IronwiseConfig.class.getMethod(method).getAnnotation(ConfigItem.class);
	}

	@Test
	public void farmRunsAreOptInAndOnlyWorkWhileSyncing() throws NoSuchMethodException
	{
		// Plugin Hub rule (the template's AGENTS.md): a setting that turns on a feature using a third-party server is
		// off by default and carries RuneLite's warning, which RuneLite shows when it's ticked.
		assertFalse(DEFAULTS.farmRuns());
		assertEquals(PluginHubRulesTest.THIRD_PARTY_WARNING, item("farmRuns").warning());
		assertEquals(PluginHubRulesTest.THIRD_PARTY_WARNING, item("syncEnabled").warning());
		// Its description says what it asks for and what it sends.
		assertTrue(item("farmRuns").description().contains("every 10 seconds"));
		assertTrue(item("farmRuns").description().contains("bird house"));
		// The three that only draw are on, and do nothing until Farm runs is ticked.
		assertTrue(DEFAULTS.farmRunBox());
		assertTrue(DEFAULTS.farmRunShortestPath());
		assertTrue(DEFAULTS.farmRunBankHighlight());
		for (String m : new String[]{"farmRunBox", "farmRunShortestPath", "farmRunBankHighlight"})
		{
			assertEquals(m, "", item(m).warning());
		}
		assertFalse(DEFAULTS.syncEnabled());
		// The side panel, with either unticked, says to tick both.
		assertTrue(FarmRunPanel.Model.OFF.contains("Sync with Ironwise and " + item("farmRuns").name()));
	}

	@Test
	public void theTokenSaysEverythingItCanDo() throws NoSuchMethodException, IOException
	{
		// As the README's "Your token": send data, mark guide steps, and read and change the farm runs.
		String token = item("token").description();
		assertTrue(token.contains("send data"));
		assertTrue(token.contains("mark guide steps"));
		assertTrue(token.contains("read and change the farm runs"));
		String readme = new String(Files.readAllBytes(new File("README.md").toPath()), StandardCharsets.UTF_8);
		assertTrue(readme.contains("mark guide steps, and read and change the farm runs of the accounts that device syncs"));
	}

	@Test
	public void theirKeysAndNames() throws NoSuchMethodException
	{
		assertEquals(IronwiseConfig.FARM_RUNS, item("farmRuns").keyName());
		assertEquals(IronwiseConfig.FARM_RUN_BOX, item("farmRunBox").keyName());
		assertEquals(IronwiseConfig.FARM_RUN_SHORTEST_PATH, item("farmRunShortestPath").keyName());
		assertEquals(IronwiseConfig.FARM_RUN_BANK_HIGHLIGHT, item("farmRunBankHighlight").keyName());
		assertEquals(new HashSet<>(Arrays.asList("farmRuns", "farmRunBox", "farmRunShortestPath", "farmRunBankHighlight")), IronwiseConfig.FARM_RUN_KEYS);
		// Hide on the run box names the setting that brings it back, and the setting tells players about Hide.
		assertTrue(FarmRunOverlay.HIDDEN.contains("Tick " + item("farmRunBox").name() + " in the Ironwise settings"));
		assertTrue(item("farmRunBox").description().contains("Hide"));
		// The bank outline starts as soon as a run is picked in the side panel.
		assertTrue(item("farmRunBankHighlight").description().contains("pick"));
		for (String m : new String[]{"farmRuns", "farmRunBox", "farmRunShortestPath", "farmRunBankHighlight"})
		{
			assertEquals(m, IronwiseConfig.FARM_RUNS_SECTION, item(m).section());
			assertTrue(m, item(m).position() > item("showNextStep").position());
		}
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumSet;
