import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.PluginDescriptor;
import org.junit.Test;

/**
 * How farm runs sit in the plugin (0.5.0): their settings never restart syncing, the version and descriptor say what's
 * new, the seed vault is still sent under the key Ironwise reads, and nothing new acts in the game or writes files.
 */
public class FarmRunWiringTest
{
	/** RuneLite's client thread, holding what's handed to it instead of running it. */
	private static final class HeldThread extends ClientThread
	{
		final List<Runnable> held = new ArrayList<>();

		@Override
		public void invokeLater(Runnable r)
		{
			held.add(r);
		}
	}

	@Test
	public void farmRunSettingsDontRestartSyncing() throws ReflectiveOperationException
	{
		// Syncing stopped over a setting only the player can fix, and they've been told once.
		IronwisePlugin plugin = new IronwisePlugin();
		HeldThread thread = new HeldThread();
		set(plugin, "clientThread", thread);
		set(plugin, "stopped", "Ironwise: paste your device token in the plugin settings.");
		set(plugin, "dirty", false);
		set(plugin, "announced", true);

		for (String key : IronwiseConfig.FARM_RUN_KEYS)
		{
			plugin.onConfigChanged(changed(key, "true", "false"));
			plugin.onConfigChanged(changed(key, "false", "true"));
		}

		// Nothing about syncing changed: still stopped, no new sync, no second "syncing" line...
		assertEquals("Ironwise: paste your device token in the plugin settings.", get(plugin, "stopped"));
		assertFalse((Boolean) get(plugin, "dirty"));
		assertTrue((Boolean) get(plugin, "announced"));
		// ...and the farm runs follow each change on the client thread.
		assertEquals(2 * IronwiseConfig.FARM_RUN_KEYS.size(), thread.held.size());
	}

	@Test
	public void theNextStepAndCollectionLogSettingsStayAsTheyWere() throws ReflectiveOperationException
	{
		IronwisePlugin plugin = new IronwisePlugin();
		HeldThread thread = new HeldThread();
		set(plugin, "clientThread", thread);
		set(plugin, "guide", new GuideState());
		set(plugin, "dirty", false);
		plugin.onConfigChanged(changed(IronwiseConfig.SHOW_NEXT_STEP, "true", "false"));
		plugin.onConfigChanged(changed(IronwiseConfig.SYNC_COLLECTION_LOG, "false", "true"));
		assertFalse((Boolean) get(plugin, "dirty"));
		assertTrue(thread.held.isEmpty());
		// Another address, token or Sync with Ironwise: syncing tries again, and the farm runs follow.
		for (String key : new String[]{"serverUrl", "token", "syncEnabled"})
		{
			set(plugin, "dirty", false);
			plugin.onConfigChanged(changed(key, "a", "b"));
			assertTrue(key, (Boolean) get(plugin, "dirty"));
		}
		assertEquals(3, thread.held.size());
	}

	@Test
	public void aFarmRunFaultNeverStopsTheSync() throws ReflectiveOperationException
	{
		// A logged-in player on a standard world, syncing (the collection log off).
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			switch (method.getName())
			{
				case "getGameState":
					return GameState.LOGGED_IN;
				case "getWorldType":
					return EnumSet.noneOf(WorldType.class);
				default:
					throw new AssertionError("the plugin called Client." + method.getName());
			}
		});
		IronwiseConfig config = new IronwiseConfig()
		{
			@Override
			public boolean syncEnabled()
			{
				return true;
			}
		};
		// The farm runs fail on every tick (the client refusing a varbit Ironwise named, say).
		FarmRunController failing = new FarmRunController(null, null, null, null, null, null, null, null, null)
		{
			@Override
			void onGameTick(long now, String syncStopped)
			{
				throw new IndexOutOfBoundsException("Varbit 99999 does not exist");
			}
		};
		IronwisePlugin plugin = new IronwisePlugin();
		set(plugin, "client", client);
		set(plugin, "config", config);
		set(plugin, "collectionLogReader", new CollectionLogReader(client, new CollectionLogState(), config));
		set(plugin, "farmRuns", failing);

		plugin.onGameTick(new GameTick());
		plugin.onGameTick(new GameTick());

		// The sync (0.4.1's, and the Next step box it brings) carries on counting down to its first send.
		assertEquals(2, get(plugin, "ticksLoggedIn"));
	}

	@Test
	public void theFarmRunsHearWhenSyncingStopsAndStartsAgain() throws ReflectiveOperationException
	{
		// A logged-in player on a standard world, syncing (the collection log off).
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			switch (method.getName())
			{
				case "getGameState":
					return GameState.LOGGED_IN;
				case "getWorldType":
					return EnumSet.noneOf(WorldType.class);
				default:
					throw new AssertionError("the plugin called Client." + method.getName());
			}
		});
		IronwiseConfig config = new IronwiseConfig()
		{
			@Override
			public boolean syncEnabled()
			{
				return true;
			}
		};
		List<String> heard = new ArrayList<>();
		FarmRunController recording = new FarmRunController(null, null, null, null, null, null, null, null, null)
		{
			@Override
			void onGameTick(long now, String syncStopped)
			{
				heard.add(syncStopped);
			}
		};
		IronwisePlugin plugin = new IronwisePlugin();
		set(plugin, "client", client);
		set(plugin, "config", config);
		set(plugin, "collectionLogReader", new CollectionLogReader(client, new CollectionLogState(), config));
		set(plugin, "farmRuns", recording);
		set(plugin, "clientThread", new HeldThread());
		set(plugin, "guide", new GuideState());

		// Syncing stopped over a bad token: the farm runs are told why, every tick, so nothing of theirs goes either.
		set(plugin, "stopped", "Ironwise: " + SyncClient.BAD_TOKEN);
		plugin.onGameTick(new GameTick());
		plugin.onGameTick(new GameTick());
		// A new token: syncing starts again, and so do the farm runs.
		plugin.onConfigChanged(changed("token", "a", "b"));
		plugin.onGameTick(new GameTick());
		assertEquals(Arrays.asList("Ironwise: " + SyncClient.BAD_TOKEN, "Ironwise: " + SyncClient.BAD_TOKEN, null), heard);
		assertEquals(SyncClient.BAD_TOKEN, FarmRunController.reason("Ironwise: " + SyncClient.BAD_TOKEN));
	}

	@Test
	public void version050() throws IOException
	{
		assertEquals("0.5.0", IronwisePlugin.VERSION);
		Properties p = new Properties();
		try (InputStream in = new FileInputStream("runelite-plugin.properties"))
		{
			p.load(in);
		}
		assertEquals("0.5.0", p.getProperty("version"));
		assertTrue(p.getProperty("description").contains("farm runs"));
		assertTrue(Arrays.asList(p.getProperty("tags").split(",")).contains("farming"));
		PluginDescriptor d = IronwisePlugin.class.getAnnotation(PluginDescriptor.class);
		assertTrue(Arrays.asList(d.tags()).contains("farming"));
		assertTrue(d.description().contains("farm runs"));
