	@Test
	public void theSeedVaultIsSentAsSeedVault() throws IOException
	{
		// Ironwise's sync reads containers.seedVault (src/server/sync/payload.ts SYNC_CONTAINERS) for seed counts. Read
		// from the source, as PluginHubRulesTest does: the plugin has no accessor only a test would use.
		String builder = new String(Files.readAllBytes(new File("src/main/java/com/ironwise/PayloadBuilder.java").toPath()), StandardCharsets.UTF_8);
		assertTrue(builder.contains("CONTAINERS.put(InventoryID.SEED_VAULT, \"seedVault\");"));
		assertTrue(PayloadBuilder.isTrackedContainer(net.runelite.api.gameval.InventoryID.SEED_VAULT));
	}

	@Test
	public void informationOnly() throws IOException
	{
		// Nothing in the plugin writes files, acts in the game, or changes a setting other than its own boxes'.
		File[] sources = new File("src/main/java/com/ironwise").listFiles((dir, name) -> name.endsWith(".java"));
		assertNotNull(sources);
		Set<String> writesItsOwnSetting = new HashSet<>();
		for (File source : sources)
		{
			String code = new String(Files.readAllBytes(source.toPath()), StandardCharsets.UTF_8);
			for (String call : new String[]{"FileOutputStream", "FileWriter", "Files.write", "Files.newOutputStream", "invokeMenuAction", "menuAction(",
				"runScript(", "setOnOpListener(", "createChild(", "Robot", "setLocalDestination", "setMouseCanvasPosition", "unsetConfiguration("})
			{
				assertFalse(source.getName() + " uses " + call, code.contains(call));
			}
			if (code.contains("setConfiguration("))
			{
				writesItsOwnSetting.add(source.getName());
			}
		}
		// Hide on the Next step box and on the run box: IronwiseConfig.GROUP only.
		assertEquals(new HashSet<>(Arrays.asList("IronwisePlugin.java", "FarmRunController.java")), writesItsOwnSetting);
		String controller = new String(Files.readAllBytes(new File("src/main/java/com/ironwise/FarmRunController.java").toPath()), StandardCharsets.UTF_8);
		assertTrue(controller.contains("setConfiguration(group, key, value)"));
		assertTrue(controller.contains("FarmRunOverlay.hide("));
	}

	private static ConfigChanged changed(String key, String oldValue, String newValue)
	{
		ConfigChanged changed = new ConfigChanged();
		changed.setGroup(IronwiseConfig.GROUP);
		changed.setKey(key);
		changed.setOldValue(oldValue);
		changed.setNewValue(newValue);
		return changed;
	}

	private static void set(IronwisePlugin plugin, String name, Object value) throws ReflectiveOperationException
	{
		Field f = IronwisePlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private static Object get(IronwisePlugin plugin, String name) throws ReflectiveOperationException
	{
		Field f = IronwisePlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(plugin);
	}
}

package com.ironwise;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonElement;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Test;

/**
 * Ironwise's farm run answer, word for word as src/server/runs/plugin-view.ts and plugin-deps.ts build it (same keys),
 * parsed defensively. The run and its values are made up.
 */
public class FarmRunsTest
{
	/** A run of two stops: a herb patch in Catherby (varbit, bounds) and a bird house space (varp). */
	static final String ANSWER = "{\"ok\":true,\"rev\":\"r1.2.1790000000000\","
		+ "\"presets\":[{\"id\":\"abcdEFGH\",\"name\":\"Herbs\",\"icon\":\"herb\",\"iconItem\":257,\"stops\":2,\"minutes\":7,\"minutesUnsure\":false,\"bringItemIds\":[952,5295]}],"
		+ "\"active\":{\"presetId\":\"abcdEFGH\",\"name\":\"Herbs\",\"index\":0,\"finished\":false,\"startedAt\":1790000000000,\"by\":\"web\","
		+ "\"stops\":["
		+ "{\"patchId\":\"herb-catherby\",\"name\":\"Herb patch, Catherby\",\"type\":\"herb\",\"cluster\":\"catherby\",\"state\":\"current\","
		+ "\"point\":{\"x\":2810,\"y\":3464,\"plane\":0},\"teleport\":{\"label\":\"Camelot Teleport\",\"itemIds\":[],\"condition\":null},"
		+ "\"watch\":{\"kind\":\"varbit\",\"varbit\":4774,\"impl\":\"HERB\",\"regions\":[11062,11061,11318,11317],"
		+ "\"bounds\":{\"any\":[{\"maxX\":2815},{\"minY\":3456},{\"minX\":2816,\"maxX\":2839,\"minY\":3440,\"maxY\":3455,\"plane\":0}]},"
		+ "\"doneWhen\":[{\"from\":[\"empty\",\"grown\",\"harvest\",\"diseased\",\"dead\"],\"to\":\"planted\"}]}},"
		+ "{\"patchId\":\"birdhouse-valley-north\",\"name\":\"Bird house space (north-east), Verdant Valley, Fossil Island\",\"type\":\"birdhouse\",\"cluster\":\"verdant-valley\",\"state\":\"todo\","
		+ "\"point\":{\"x\":3768,\"y\":3761,\"plane\":0},\"teleport\":{\"label\":\"Digsite pendant\",\"itemIds\":[11190,11191],\"condition\":null},"
		+ "\"watch\":{\"kind\":\"birdhouse\",\"varp\":1628,\"regions\":[14650,14651,14652,14906,14907,15162,15163],\"plane\":0,\"near\":{\"x\":3768,\"y\":3761,\"plane\":0}}}],"
		+ "\"bring\":[{\"itemIds\":[5295],\"name\":\"Ranarr seed\",\"qty\":1,\"have\":0,\"optional\":false},{\"itemIds\":[952],\"name\":\"Spade\",\"qty\":1,\"have\":null,\"optional\":false}]},"
		+ "\"tables\":{\"HERB\":[[0,3,\"empty\"],[4,7,\"planted\"],[8,10,\"harvest\"],[32,35,\"planted\"],[36,38,\"harvest\"],[170,172,\"dead\"]]}}";

	/** The same saved run and a built-in one, with no run in progress. */
	static final String NO_RUN = ANSWER.replaceAll("\"active\":\\{.*\\},\"tables\"", "\"active\":null,\"tables\"")
		.replace("\"bringItemIds\":[952,5295]}]", "\"bringItemIds\":[952,5295]},"
			+ "{\"id\":\"builtin-trees\",\"name\":\"Tree run\",\"icon\":\"tree\",\"iconItem\":null,\"stops\":3,\"minutes\":null,\"minutesUnsure\":false,\"bringItemIds\":[952,5343,8431]}]");

	/** JSON as the plugin reads it (RuneLite's Gson; its JsonParser has no parseString). */
	static JsonElement json(String s)
	{
		return RuneLiteAPI.GSON.fromJson(s, JsonElement.class);
	}

	@Test
	public void readsTheWholeAnswer()
	{
		FarmRuns r = FarmRuns.parse(FarmRunsTest.json(ANSWER));
		assertNotNull(r);
		assertEquals("r1.2.1790000000000", r.rev);
		assertEquals(1, r.presets.size());
		assertEquals(Integer.valueOf(7), r.presets.get(0).minutes);
		assertFalse(r.presets.get(0).minutesUnsure);
		assertEquals(Integer.valueOf(257), r.presets.get(0).iconItem);
		// The picked run's bank outline (before Start): the same ids as the run's Bring list once it has started.
		assertArrayEquals(new int[]{952, 5295}, r.presets.get(0).bringItemIds);
		FarmRuns.Active a = r.active;
		assertEquals(2, a.total());
		assertEquals("herb-catherby", a.current().patchId);
		assertEquals("catherby", a.current().cluster);
		// Only the current stop's cluster is watched: the bird house is another cluster's.
		assertEquals(1, a.openInCluster().size());
		assertFalse(a.bring.get(0).optional);
		assertEquals("Camelot Teleport", a.current().teleport.label);
		assertNull(a.current().teleport.condition);
		FarmRuns.Watch w = a.current().watch;
		assertEquals("varbit", w.kind);
		assertEquals(4774, w.varbit);
		assertArrayEquals(new int[]{11062, 11061, 11318, 11317}, w.regions);
		assertTrue(w.bounds.contains(2810, 3464, 0));
		assertFalse(w.bounds.contains(2845, 3445, 0));
		FarmRuns.Watch bird = a.stops.get(1).watch;
		assertEquals("birdhouse", bird.kind);
		assertEquals(1628, bird.varp);
		assertEquals(3768, bird.near.x);
		assertEquals(Integer.valueOf(0), a.bring.get(0).have);
		assertNull(a.bring.get(1).have);
		assertEquals("planted", FarmRuns.classOf(r.tables.get("HERB"), 33));
		assertEquals("dead", FarmRuns.classOf(r.tables.get("HERB"), 171));
		assertNull(FarmRuns.classOf(r.tables.get("HERB"), 110));
	}

	@Test
	public void minutesThatCountARouteIronwiseCantConfirmAreAGuess()
	{
		FarmRuns r = FarmRuns.parse(FarmRunsTest.json(ANSWER.replace("\"minutesUnsure\":false", "\"minutesUnsure\":true")));
		assertEquals(Integer.valueOf(7), r.presets.get(0).minutes);
		assertTrue(r.presets.get(0).minutesUnsure);
		// Left out (a server from before it), not a boolean, or with no minutes to call a guess: not a guess.
		assertFalse(FarmRuns.parse(FarmRunsTest.json(ANSWER.replace("\"minutesUnsure\":false,", ""))).presets.get(0).minutesUnsure);
		assertFalse(FarmRuns.parse(FarmRunsTest.json(ANSWER.replace("\"minutesUnsure\":false", "\"minutesUnsure\":\"true\""))).presets.get(0).minutesUnsure);
		assertFalse(FarmRuns.parse(FarmRunsTest.json(ANSWER.replace("\"minutes\":7,\"minutesUnsure\":false", "\"minutes\":null,\"minutesUnsure\":true"))).presets.get(0).minutesUnsure);
	}

	@Test
	public void builtInRunsAreListedToo()
	{
		FarmRuns r = FarmRuns.parse(FarmRunsTest.json("{\"ok\":true,\"rev\":\"r0.0.1.basic\",\"presets\":[{\"id\":\"builtin-herbs\",\"name\":\"Herb run\",\"icon\":\"herb\",\"iconItem\":null,\"stops\":10,\"minutes\":null,\"bringItemIds\":[]}],\"active\":null,\"tables\":{}}"));
		assertEquals("builtin-herbs", r.presets.get(0).id);
		assertNull(r.presets.get(0).iconItem);
		assertNull(r.presets.get(0).minutes);
		assertEquals(0, r.presets.get(0).bringItemIds.length);
		// Left out (a server from before bringItemIds) or not a list of ids: nothing to outline, the run still listed.
		FarmRuns old = FarmRuns.parse(FarmRunsTest.json("{\"ok\":true,\"rev\":\"r\",\"presets\":[{\"id\":\"builtin-herbs\",\"name\":\"Herb run\",\"icon\":\"herb\",\"stops\":10},{\"id\":\"builtin-trees\",\"name\":\"Tree run\",\"icon\":\"tree\",\"stops\":6,\"bringItemIds\":\"952\"}],\"active\":null,\"tables\":{}}"));
		assertEquals(2, old.presets.size());
		assertEquals(0, old.presets.get(0).bringItemIds.length);
		assertEquals(0, old.presets.get(1).bringItemIds.length);
		// Neither a saved run nor a built-in one: left out.
		assertTrue(FarmRuns.parse(FarmRunsTest.json("{\"ok\":true,\"rev\":\"r\",\"presets\":[{\"id\":\"builtin-Herbs!\",\"name\":\"X\",\"icon\":\"herb\",\"stops\":1}],\"active\":null,\"tables\":{}}")).presets.isEmpty());
	}

	@Test
	public void theBankOutlineKeepsOnlyItemIds()
	{
		// Whole numbers from 0 up, each once, at most MAX_BRING_ITEM_IDS (the server's cap); anything else is left out.
		FarmRuns r = FarmRuns.parse(FarmRunsTest.json(ANSWER.replace("\"bringItemIds\":[952,5295]", "\"bringItemIds\":[952,5295,952,-1,1.5,\"8431\",null,2147483648]")));
		assertArrayEquals(new int[]{952, 5295}, r.presets.get(0).bringItemIds);
		StringBuilder many = new StringBuilder("[");
		for (int i = 0; i < FarmRuns.MAX_BRING_ITEM_IDS + 50; i++)
		{
			many.append(i == 0 ? "" : ",").append(1000 + i);
		}
		FarmRuns big = FarmRuns.parse(FarmRunsTest.json(ANSWER.replace("\"bringItemIds\":[952,5295]", "\"bringItemIds\":" + many + "]")));
		assertEquals(FarmRuns.MAX_BRING_ITEM_IDS, big.presets.get(0).bringItemIds.length);
		assertEquals(200, FarmRuns.MAX_BRING_ITEM_IDS);
	}

	@Test
	public void theClusterOfTheCurrentStopIsWatchedInAnyOrder()
	{
		String three = FarmRunsTest.ANSWER.replace("\"cluster\":\"verdant-valley\"", "\"cluster\":\"catherby\"");
		FarmRuns.Active a = FarmRuns.parse(FarmRunsTest.json(three)).active;
		assertEquals(2, a.openInCluster().size());
		String done = three.replace("\"state\":\"todo\"", "\"state\":\"done\"");
		assertEquals(1, FarmRuns.parse(FarmRunsTest.json(done)).active.openInCluster().size());
	}

	@Test
	public void noRunInProgress()
	{
		FarmRuns r = FarmRuns.parse(FarmRunsTest.json("{\"ok\":true,\"rev\":\"r0.0.1\",\"presets\":[],\"active\":null,\"tables\":{}}"));
		assertNotNull(r);
		assertNull(r.active);
		FarmRuns listed = FarmRuns.parse(FarmRunsTest.json(NO_RUN));
		assertNull(listed.active);
		assertEquals(2, listed.presets.size());
		assertEquals("builtin-trees", listed.presets.get(1).id);
	}

	@Test
	public void unusableAnswersAreNull()
	{
		assertNull(FarmRuns.parse(FarmRunsTest.json("{\"ok\":false}")));
		assertNull(FarmRuns.parse(FarmRunsTest.json("[1,2]")));
		assertNull(FarmRuns.parse(null));
		// A run whose index is past its stops, or a stop with a bad id, drops the run, not the saved runs.
		FarmRuns bad = FarmRuns.parse(FarmRunsTest.json(ANSWER.replace("\"index\":0", "\"index\":5")));
		assertNotNull(bad);
		assertNull(bad.active);
		assertEquals(1, bad.presets.size());
		assertNull(FarmRuns.parse(FarmRunsTest.json(ANSWER.replace("herb-catherby", "Herb Catherby"))).active);
	}

	@Test
	public void idsTheClientWouldRefuseAreLeftOut()
	{
		// The client throws on a varbit or varp that doesn't exist, and a picture of an item below 0 never loads: a
		// negative id from Ironwise leaves that watch (or picture) out, never the run.
		FarmRuns r = FarmRuns.parse(FarmRunsTest.json(ANSWER.replace("\"varbit\":4774", "\"varbit\":-4774").replace("\"varp\":1628", "\"varp\":-1").replace("\"iconItem\":257", "\"iconItem\":-257")));
		assertNotNull(r.active);
		assertNull(r.active.stops.get(0).watch);
		assertNull(r.active.stops.get(1).watch);
		assertNull(r.presets.get(0).iconItem);
	}

	@Test
	public void onlyFarmingPatchAndBirdHouseVariablesAreWatched()
	{
		// Whatever Ironwise names, the plugin reads only these: the 25 farming patch varbits and the 4 bird house varps,
		// the same ids the app's patch catalogue uses (FarmingWorld's FARMING_TRANSMIT_A to M, BirdHouseSpace's A to D).
		Set<Integer> varbits = new HashSet<>();
		for (int[] range : new int[][]{{4771, 4775}, {4953, 4964}, {7904, 7911}})
		{
			for (int id = range[0]; id <= range[1]; id++)
			{
				varbits.add(id);
			}
		}
		assertEquals(varbits, FarmRuns.FARMING_VARBITS);
		assertEquals(new HashSet<>(Arrays.asList(1626, 1627, 1628, 1629)), FarmRuns.BIRD_HOUSE_VARPS);
		assertNotNull(FarmRuns.parse(json(ANSWER)).active.stops.get(0).watch);
		assertNotNull(FarmRuns.parse(json(ANSWER)).active.stops.get(1).watch);
		// Any other variable, farming-looking or not, leaves that stop unwatched (skipped by hand), never the run.
		for (int other : new int[]{4770, 4776, 4952, 4965, 7903, VarbitID.FARMING_TRANSMIT_N, VarbitID.SPELLBOOK, 0, Integer.MAX_VALUE})
		{
			FarmRuns r = FarmRuns.parse(json(ANSWER.replace("\"varbit\":4774", "\"varbit\":" + other)));
			assertNotNull(r.active);
			assertNull(String.valueOf(other), r.active.stops.get(0).watch);
		}
		for (int other : new int[]{1625, 1630, VarPlayerID.QP, 0})
		{
			FarmRuns r = FarmRuns.parse(json(ANSWER.replace("\"varp\":1628", "\"varp\":" + other)));
			assertNotNull(r.active);
			assertNull(String.valueOf(other), r.active.stops.get(1).watch);
		}
	}

	@Test
	public void colourTagsAndOverlongNamesAreCleaned()
	{
		FarmRuns r = FarmRuns.parse(FarmRunsTest.json(ANSWER.replace("\"name\":\"Herbs\",\"icon\"", "\"name\":\"<col=ff0000>Herbs</col>\",\"icon\"")));
		assertEquals("Herbs", r.presets.get(0).name);
		StringBuilder longName = new StringBuilder();
		for (int i = 0; i < 30; i++)
		{
			longName.append("Herbs ");
		}
		FarmRuns l = FarmRuns.parse(FarmRunsTest.json(ANSWER.replace("\"name\":\"Herbs\",\"icon\"", "\"name\":\"" + longName + "\",\"icon\"")));
		assertTrue(l.presets.get(0).name.length() <= FarmRuns.MAX_NAME);
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import com.sun.net.httpserver.HttpServer;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.http.api.RuneLiteAPI;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/** A mark against a real (local) HTTP server: what actually goes over the wire. */
public class GuideClientHttpTest
{
	private HttpServer server;
	private String base;
	/** "METHOD path Authorization body" for every request the server saw. */
	private final List<String> seen = new CopyOnWriteArrayList<>();
	private final GuideClient client = new GuideClient(new SyncClient(new OkHttpClient(), RuneLiteAPI.GSON), RuneLiteAPI.GSON);

	@Before
	public void start() throws Exception
	{
		JsonObject answer = new JsonObject();
		answer.addProperty("ok", true);
		JsonObject next = NextStepTest.stepJson();
		next.addProperty("stepId", "fedcba9876543210");
		next.addProperty("n", 13);
		answer.add("next", next);
		byte[] ok = answer.toString().getBytes(StandardCharsets.UTF_8);

		server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/", exchange ->
		{
			String path = exchange.getRequestURI().getPath();
			ByteArrayOutputStream body = new ByteArrayOutputStream();
			try (InputStream in = exchange.getRequestBody())
			{
				byte[] buf = new byte[4096];
				int n;
				while ((n = in.read(buf)) > 0)
				{
					body.write(buf, 0, n);
				}
			}
			seen.add(exchange.getRequestMethod() + " " + path + " " + exchange.getRequestHeaders().getFirst("Authorization")
				+ " " + new String(body.toByteArray(), StandardCharsets.UTF_8));
			if ("/ok/api/guide/tick".equals(path))
			{
				exchange.getResponseHeaders().add("Content-Type", "application/json");
				exchange.sendResponseHeaders(200, ok.length);
				try (OutputStream out = exchange.getResponseBody())
				{
					out.write(ok);
				}
				return;
			}
			if ("/moved/api/guide/tick".equals(path))
			{
				exchange.getResponseHeaders().add("Location", base + "/elsewhere/api/guide/tick");
			}
			exchange.sendResponseHeaders("/moved/api/guide/tick".equals(path) ? 307 : 404, -1);
			exchange.close();
		});
		server.start();
		base = "http://127.0.0.1:" + server.getAddress().getPort();
	}

	@After
	public void stop()
	{
		server.stop(0);
	}

	private GuideClient.Result send(String address) throws Exception
	{
		HttpUrl url = GuideClient.tickUrl(address);
		assertNotNull(address, url);
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<GuideClient.Result> result = new AtomicReference<>();
		GuideState.Tick tick = new GuideState.Tick(1, "1234567890123456789", "0123456789abcdef", GuideClient.DONE);
		client.send(url, "iw_test", tick, r ->
		{
			result.set(r);
			done.countDown();
		});
		assertTrue("no answer in time", done.await(20, TimeUnit.SECONDS));
		return result.get();
	}

	@Test
	public void markedDone() throws Exception
	{
		GuideClient.Result r = send(base + "/ok");
		assertTrue(r.message, r.ok);
		assertEquals("fedcba9876543210", r.next.stepId);
		assertEquals(1, seen.size());
		assertEquals("POST /ok/api/guide/tick Bearer iw_test {\"accountHash\":\"1234567890123456789\",\"stepId\":\"0123456789abcdef\",\"action\":\"done\"}", seen.get(0));
	}

	@Test
	public void aRedirectIsNotFollowed() throws Exception
	{
		GuideClient.Result r = send(base + "/moved");
		assertFalse(r.ok);
		// The token only went to the address the player set.
		assertEquals(1, seen.size());
		assertTrue(seen.get(0), seen.get(0).startsWith("POST /moved/api/guide/tick Bearer iw_test "));
	}

	@Test
	public void anAppWithoutTheGuide() throws Exception
	{
		GuideClient.Result r = send(base + "/old");
		assertFalse(r.ok);
		assertEquals(GuideClient.NO_GUIDE, r.message);
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import net.runelite.http.api.RuneLiteAPI;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import org.junit.Test;

/** "Mark step done"/"Skip step": what goes to Ironwise and how its answers read. */
public class GuideClientTest
{
	private final GuideClient client = new GuideClient(new SyncClient(new OkHttpClient(), RuneLiteAPI.GSON), RuneLiteAPI.GSON);

	private static String url(String address)
	{
		HttpUrl u = GuideClient.tickUrl(address);
		return u == null ? null : u.toString();
	}

	private static String ok(JsonObject next)
	{
		JsonObject o = new JsonObject();
		o.addProperty("ok", true);
		if (next != null)
		{
			o.add("next", next);
		}
		return o.toString();
	}

	@Test
	public void addresses()
	{
		// The same rules as syncing: HTTPS, except on this computer.
		assertEquals("https://ironwise.example.com/api/guide/tick", url("ironwise.example.com/"));
		assertEquals("https://ironwise-eight.vercel.app/api/guide/tick", url(IronwiseConfig.DEFAULT_ADDRESS));
		assertEquals("http://localhost:3000/api/guide/tick", url("http://localhost:3000"));
		assertNull(url("http://ironwise.example.com"));
		assertNull(url(""));
		assertNull(url(null));
		// The sync address is unchanged.
		assertEquals("https://ironwise.example.com/api/sync", SyncClient.syncUrl("ironwise.example.com").toString());
	}

	@Test
	public void body()
	{
		GuideState.Tick tick = new GuideState.Tick(1, "-1234567890123456789", "0123456789abcdef-2", GuideClient.SKIP);
		assertEquals("{\"accountHash\":\"-1234567890123456789\",\"stepId\":\"0123456789abcdef-2\",\"action\":\"skip\"}", client.body(tick));
	}

	@Test
	public void theNextStepComesBack()
	{
		GuideClient.Result r = client.result(200, ok(NextStepTest.stepJson()));
		assertTrue(r.ok);
		assertNull(r.message);
		assertEquals("0123456789abcdef", r.next.stepId);
		assertEquals(12, r.next.n);
	}

	@Test
	public void noNextStepMeansNothingToShow()
	{
		GuideClient.Result last = client.result(200, ok(null));
		assertTrue(last.ok);
		assertNull(last.next);
		assertTrue(client.result(200, "{\"ok\":true,\"next\":null}").ok);
		GuideClient.Result garbled = client.result(200, "{\"ok\":true,\"next\":{\"stepId\":\"nope\"}}");
		assertTrue(garbled.ok);
		assertNull(garbled.next);
	}

	@Test
	public void onlyIronwiseCanSayYes()
	{
		for (String body : new String[]{"", "<html>Welcome</html>", "{}", "{\"ok\":\"true\"}", "{\"ok\":false}", "[true]"})
		{
			GuideClient.Result r = client.result(200, body);
			assertFalse(body, r.ok);
			assertEquals(body, SyncClient.NOT_IRONWISE, r.message);
		}
	}

	@Test
	public void refusals()
	{
		// Ironwise's own words when it gives them.
		GuideClient.Result other = client.result(403, "{\"ok\":false,\"error\":\"forbidden\",\"message\":\"This device hasn't synced that account.\"}");
		assertFalse(other.ok);
		assertEquals("This device hasn't synced that account.", other.message);
		assertEquals(GuideClient.NOT_SYNCED, client.result(403, "{\"ok\":false}").message);
		assertEquals(SyncClient.BAD_TOKEN, client.result(401, "{\"ok\":false}").message);
		assertEquals("Unknown step.", client.result(400, "{\"ok\":false,\"message\":\"Unknown step.\"}").message);
		// A login page in front of the app.
		assertEquals(SyncClient.LOGIN, client.result(401, "<html>Log in</html>").message);
		assertEquals(SyncClient.LOGIN, client.result(403, "").message);
		// An Ironwise from before the Quests page.
		assertEquals(GuideClient.NO_GUIDE, client.result(404, "<html>Not found</html>").message);
		assertEquals("the app answered 500", client.result(500, "oops").message);
		assertEquals("Couldn't load the guide.", client.result(503, "{\"ok\":false,\"message\":\"Couldn't load the guide.\"}").message);
		assertEquals("that address redirects somewhere else. Use the app's main address.", client.result(307, "").message);
	}

	@Test
	public void aServerMessageIsPlainText()
	{
		GuideClient.Result r = client.result(400, "{\"ok\":false,\"message\":\"<col=ff0000>Bad\\nstep</col>\"}");
		assertEquals("Bad step", r.message);
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.regex.Pattern;
import net.runelite.http.api.RuneLiteAPI;
import okhttp3.OkHttpClient;
import org.junit.Test;

/**
 * The answers Ironwise's server gives, word for word as src/server/guide/tick.ts,
 * src/app/api/guide/tick/route.ts and src/server/sync/index.ts write them, and the requests it accepts.
 * The step values are made up.
 */
public class GuideContractTest
{
	private final SyncClient sync = new SyncClient(new OkHttpClient(), RuneLiteAPI.GSON);
	private final GuideClient guide = new GuideClient(sync, RuneLiteAPI.GSON);

	/**
	 * A NextStep as the server's toNextStep builds it (same keys, same order). "where" is
	 * "Ch &lt;chapter index + 1&gt; \u00B7 &lt;chapter index + 1&gt;.&lt;section index + 1&gt;": here the second
	 * section of the second chapter.
	 */
	private static final String STEP = "{\"variant\":\"landlubber\",\"stepId\":\"00ff00ff00ff00ff-2\",\"n\":57,\"total\":212,"
		+ "\"chapter\":\"Chapter 2: Somewhere in the middle\",\"section\":\"Boats and birds\",\"where\":\"Ch 2 \u00B7 2.2\","
		+ "\"text\":\"Fill a few buckets at the well, then head to the dock.\",\"done\":49,\"state\":\"behind\"}";

	/** The same step from an Ironwise before "where" (older servers). */
	private static final String STEP_WITHOUT_WHERE = STEP.replace(",\"where\":\"Ch 2 \u00B7 2.2\"", "");

	/** The server's where: "Ch", the chapter number, a spaced middle dot (U+00B7), then chapter.section. */
	private static final Pattern WHERE = Pattern.compile("^Ch ([1-9]\\d*) \u00B7 \\1\\.[1-9]\\d*$");

	private static String error(String error, String message)
	{
		JsonObject o = new JsonObject();
		o.addProperty("ok", false);
		o.addProperty("error", error);
		o.addProperty("message", message);
		return o.toString();
	}

	@Test
	public void aMarkThatWentThrough()
	{
		GuideClient.Result r = guide.result(200, "{\"ok\":true,\"next\":" + STEP + "}");
		assertTrue(r.ok);
		NextStep s = r.next;
		assertNotNull(s);
		assertEquals("landlubber", s.variant);
		assertEquals("00ff00ff00ff00ff-2", s.stepId);
		assertEquals(57, s.n);
		assertEquals(212, s.total);
		assertEquals(49, s.done);
		assertTrue(s.behind);
		assertEquals("Fill a few buckets at the well, then head to the dock.", s.text);
		assertEquals("Ch 2 \u00B7 2.2", s.where);

		// The last step marked: nothing left to show.
		GuideClient.Result last = guide.result(200, "{\"ok\":true,\"next\":null}");
		assertTrue(last.ok);
		assertNull(last.next);
	}

	@Test
	public void theServersRefusalsReadOnFromTheChatLine()
	{
		// Each message follows "Ironwise: couldn't mark the step done: " in chat, as the server intends.
		String[][] answers = {
			{"401", "unauthorized", "this token isn't recognised. Make a new one on the app's Live data page."},
			{"403", "forbidden", "Ironwise hasn't had a sync of this account from this device yet."},
			{"400", "bad_request", "stepId isn't a guide step."},
			{"400", "bad_request", "the request must be JSON."},
			{"409", "stale_step", "that step has changed in the guide. The box shows the new one after your next sync."},
			{"413", "too_large", "the request is too large."},
			{"503", "unavailable", "Ironwise can't read the guide right now. Try again in a few minutes."},
			{"503", "unavailable", "couldn't save it on the server."},
		};
		for (String[] a : answers)
		{
			GuideClient.Result r = guide.result(Integer.parseInt(a[0]), error(a[1], a[2]));
			assertFalse(a[0], r.ok);
			assertNull(r.next);
			assertEquals(a[0], a[2], r.message);
		}
		// The plugin's own fallback for a 403 without a message says the same as the server.
		assertEquals(GuideClient.NOT_SYNCED, guide.result(403, "{\"ok\":false}").message);
	}

	@Test
	public void theRequestIsWhatTheServerChecks()
	{
		// receiveTick: accountHash a string /^-?\d{1,20}$/ (not 0 or -1), stepId per GUIDE_STEP_ID_RE and
		// at most 23 characters, action done|skip|undo.
		Pattern hash = Pattern.compile("^-?\\d{1,20}$");
		Pattern id = Pattern.compile("^[0-9a-f]{16}(-\\d+)?$");
		for (String action : new String[]{GuideClient.DONE, GuideClient.SKIP})
		{
			GuideState.Tick tick = new GuideState.Tick(1, Long.toString(Long.MIN_VALUE), "0123456789abcdef-999999", action);
			JsonObject body = new JsonParser().parse(guide.body(tick)).getAsJsonObject();
			assertEquals(3, body.size());
			assertTrue(body.get("accountHash").getAsJsonPrimitive().isString());
			assertTrue(hash.matcher(body.get("accountHash").getAsString()).matches());
			String stepId = body.get("stepId").getAsString();
			assertTrue(id.matcher(stepId).matches() && stepId.length() <= 23);
			assertEquals(action, body.get("action").getAsString());
		}
		// Every id the server can send is one the plugin keeps, and the plugin keeps no longer ones.
		assertNotNull(NextStep.parse(new JsonParser().parse(STEP.replace("00ff00ff00ff00ff-2", "0123456789abcdef-999999"))));
		assertNull(NextStep.parse(new JsonParser().parse(STEP.replace("00ff00ff00ff00ff-2", "0123456789abcdef-1000000"))));
	}

	@Test
	public void theSyncAnswer()
	{
		String saved = "{\"ok\":true,\"rsn\":\"Iron Tester\",\"receivedAt\":1790243320266";

		SyncClient.Result withStep = sync.result(200, saved + ",\"guide\":" + STEP + "}", null);
		assertEquals(SyncClient.Outcome.OK, withStep.outcome);
		assertTrue(withStep.guide.said);
		assertEquals("00ff00ff00ff00ff-2", withStep.guide.step.stepId);
		assertEquals("Ch 2 \u00B7 2.2", withStep.guide.step.where);

		// null: no next step (every step done or skipped): the box goes away.
		SyncClient.Result none = sync.result(200, saved + ",\"guide\":null}", null);
		assertEquals(SyncClient.Outcome.OK, none.outcome);
		assertTrue(none.guide.said);
		assertNull(none.guide.step);

		// Left out: not worked out in time, or an older Ironwise: the box keeps what it shows.
		SyncClient.Result later = sync.result(200, saved + "}", null);
		assertEquals(SyncClient.Outcome.OK, later.outcome);
		assertFalse(later.guide.said);
	}

	@Test
	public void whereIsTheChapterAndSectionNumbers()
	{
		NextStep s = NextStep.parse(new JsonParser().parse(STEP));
		assertNotNull(s);
		assertTrue(s.where, WHERE.matcher(s.where).matches());
		// The box's muted line shows it as it came, instead of the chapter and section titles.
		assertEquals("Ch 2 \u00B7 2.2", NextStepOverlay.place(s));
		for (String where : new String[]{"Ch 1 \u00B7 1.1", "Ch 9 \u00B7 9.14", "Ch 12 \u00B7 12.3"})
		{
			NextStep other = NextStep.parse(new JsonParser().parse(STEP.replace("Ch 2 \u00B7 2.2", where)));
			assertTrue(where, WHERE.matcher(where).matches());
			assertEquals(where, other.where);
			assertEquals(where, NextStepOverlay.place(other));
		}
	}

	@Test
	public void anOlderServerWithoutWhere()
	{
		assertFalse(STEP_WITHOUT_WHERE.contains("\"where\""));
		NextStep s = NextStep.parse(new JsonParser().parse(STEP_WITHOUT_WHERE));
		assertNotNull(s);
		assertNull(s.where);
		assertEquals("Chapter 2: Somewhere in the middle \u00B7 Boats and birds", NextStepOverlay.place(s));

		SyncClient.Result r = sync.result(200, "{\"ok\":true,\"rsn\":\"Iron Tester\",\"receivedAt\":1,\"guide\":" + STEP_WITHOUT_WHERE + "}", null);
		assertEquals("00ff00ff00ff00ff-2", r.guide.step.stepId);
		assertNull(r.guide.step.where);
		GuideClient.Result tick = guide.result(200, "{\"ok\":true,\"next\":" + STEP_WITHOUT_WHERE + "}");
		assertTrue(tick.ok);
		assertNull(tick.next.where);
	}

	/** NEXT_TEXT_MAX in src/server/guide/next.ts: the server's text is at most 80 characters. */
	private static final int SERVER_TEXT_MAX = 80;

	@Test
	public void theServersShortenedTextIsKeptAsItIs()
	{
		// toNextStep in src/server/guide/next.ts: the step's summary (one line of printable ASCII, at most
		// 80 characters), or for a step with none its first sentence(s), cut by shorten() at a word with
		// "…". Here: a summary of the full 80, and shorten(<"chop some logs " to 230 characters>, 80).
		String summary = "Fill a few buckets at the well, then head to the dock and wait for the ferryman.";
		String cut = "chop some logs chop some logs chop some logs chop some logs chop some logs…";
		assertEquals(SERVER_TEXT_MAX, summary.length());
		assertTrue(cut.length() <= SERVER_TEXT_MAX);
		for (String text : new String[]{summary, cut})
		{
			assertTrue(text.length() <= NextStep.MAX_TEXT);
			String json = STEP.replace("Fill a few buckets at the well, then head to the dock.", text);
			NextStep s = NextStep.parse(new JsonParser().parse(json));
			assertNotNull(text, s);
			assertEquals(text, s.text);
		}
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Test;

/** Which step the Next step box shows as sync and mark answers arrive, in any order. */
public class GuideStateTest
{
	private static final String HASH = "1234567890123456789";

	private static NextStep step(String id, int n)
	{
		JsonObject o = NextStepTest.stepJson();
		o.addProperty("stepId", id);
		o.addProperty("n", n);
		return NextStep.parse(o);
	}

	private static NextStep.Reply reply(NextStep step)
	{
		JsonObject answer = new JsonObject();
		answer.addProperty("ok", true);
		if (step != null)
		{
			JsonObject o = NextStepTest.stepJson();
			o.addProperty("stepId", step.stepId);
			o.addProperty("n", step.n);
			answer.add("guide", o);
		}
		else
		{
			answer.add("guide", JsonNull.INSTANCE);
		}
		return NextStep.fromBody(RuneLiteAPI.GSON, answer.toString(), "guide");
	}

	private static final NextStep A = step("aaaaaaaaaaaaaaaa", 12);
	private static final NextStep B = step("bbbbbbbbbbbbbbbb", 13);
	private static final NextStep C = step("cccccccccccccccc", 14);

	@Test
	public void syncAnswersSetTheStep()
	{
		GuideState g = new GuideState();
		assertNull(g.step());
		g.synced(g.session(), HASH, 1000, reply(A));
		assertEquals(A.stepId, g.step().stepId);
		// An answer without "guide" keeps what's shown.
		g.synced(g.session(), HASH, 2000, NextStep.Reply.NOTHING);
		assertEquals(A.stepId, g.step().stepId);
		// "guide": null clears it.
		g.synced(g.session(), HASH, 3000, reply(null));
		assertNull(g.step());
	}

	@Test
	public void anAnswerForAnEarlierAccountIsDropped()
	{
		GuideState g = new GuideState();
		int before = g.session();
		g.clear(); // logged out, or another account
		g.synced(before, HASH, 1000, reply(A));
		assertNull(g.step());
	}

	@Test
	public void markingReplacesTheStepWithIronwisesNext()
	{
		GuideState g = new GuideState();
		assertNull("nothing to mark", g.startTick(GuideClient.DONE));
		g.synced(g.session(), HASH, 1000, reply(A));

		GuideState.Tick tick = g.startTick(GuideClient.DONE);
		assertNotNull(tick);
		assertEquals(HASH, tick.accountHash);
		assertEquals(A.stepId, tick.stepId);
		assertEquals(GuideClient.DONE, tick.action);
		// One click at a time.
		assertNull(g.startTick(GuideClient.SKIP));

		assertTrue(g.ticked(tick, 1500, true, B));
		assertEquals(B.stepId, g.step().stepId);
		assertNotNull("can mark again", g.startTick(GuideClient.SKIP));
	}

	@Test
	public void aFailedMarkKeepsTheStep()
	{
		GuideState g = new GuideState();
		g.synced(g.session(), HASH, 1000, reply(A));
		GuideState.Tick tick = g.startTick(GuideClient.SKIP);
		g.ticked(tick, 1500, false, null);
		assertEquals(A.stepId, g.step().stepId);
		assertNotNull("can try again", g.startTick(GuideClient.SKIP));
	}

	@Test
	public void markingTheLastStepLeavesNothing()
	{
		GuideState g = new GuideState();
		g.synced(g.session(), HASH, 1000, reply(A));
		g.ticked(g.startTick(GuideClient.DONE), 1500, true, null);
		assertNull(g.step());
	}

	@Test
	public void aSyncSentBeforeTheMarkWasAnsweredCantUndoIt()
	{
		GuideState g = new GuideState();
		g.synced(g.session(), HASH, 1000, reply(A));
		GuideState.Tick tick = g.startTick(GuideClient.DONE);
		// A sync goes out at 1200, the mark's answer arrives at 1500, then the sync's (worked out before the mark).
		g.ticked(tick, 1500, true, B);
		g.synced(g.session(), HASH, 1200, reply(A));
		assertEquals(B.stepId, g.step().stepId);
		// A sync sent after the mark was answered is newer.
		g.synced(g.session(), HASH, 1600, reply(C));
		assertEquals(C.stepId, g.step().stepId);
	}

	@Test
	public void aSyncAnsweredWhileAMarkIsOnItsWayIsReplacedByTheMark()
	{
		GuideState g = new GuideState();
		g.synced(g.session(), HASH, 1000, reply(A));
		GuideState.Tick tick = g.startTick(GuideClient.DONE);
		g.synced(g.session(), HASH, 1100, reply(A));
		g.ticked(tick, 1500, true, B);
		assertEquals(B.stepId, g.step().stepId);
	}

	@Test
	public void aMarkAnsweredAfterLogoutIsDropped()
	{
		GuideState g = new GuideState();
		g.synced(g.session(), HASH, 1000, reply(A));
		GuideState.Tick tick = g.startTick(GuideClient.DONE);
		g.clear();
		assertFalse("dropped", g.ticked(tick, 1500, true, B));
		assertNull(g.step());
		// And the next login can mark straight away.
		g.synced(g.session(), HASH, 2000, reply(C));
		assertNotNull(g.startTick(GuideClient.DONE));
	}
}

