package com.ironwise;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumSet;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.stream.Collectors;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.WorldType;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Test;

/** "Hide" on the Next step box (new in 0.4.1): it only unticks a setting and says so in chat. */
public class NextStepHideTest
{
	private static final IronwiseConfig DEFAULTS = new IronwiseConfig()
	{
	};

	/** A Client that records chat lines and fails on anything else, so Hide can't act in the game. */
	private static Client chatOnly(List<Object[]> chat)
	{
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			if ("addChatMessage".equals(method.getName()) && args != null && args.length == 4)
			{
				chat.add(args);
				return null;
			}
			throw new AssertionError("Hide called Client." + method.getName());
		});
	}

	@Test
	public void theBoxHasAHideEntry()
	{
		NextStepOverlay overlay = new NextStepOverlay(new IronwisePlugin(), null, DEFAULTS, new GuideState());
		List<OverlayMenuEntry> entries = overlay.getMenuEntries();
		assertEquals("Hide", NextStepOverlay.HIDE);
		assertEquals(3, entries.size());
		assertEquals(
			Arrays.asList(NextStepOverlay.MARK_DONE, NextStepOverlay.SKIP, NextStepOverlay.HIDE),
			entries.stream().map(OverlayMenuEntry::getOption).collect(Collectors.toList()));
		// All three are RuneLite overlay entries (Shift + right-click on the box), not game menu options.
		for (OverlayMenuEntry e : entries)
		{
			assertEquals(e.getOption(), MenuAction.RUNELITE_OVERLAY, e.getMenuAction());
			assertEquals(e.getOption(), "Next step", e.getTarget());
		}
	}

	@Test
	public void hidingUnticksShowNextStepAndSaysHowToGetItBack()
	{
		List<Object[]> writes = new ArrayList<>();
		List<Object[]> chat = new ArrayList<>();
		NextStepOverlay.hide((group, key, value) -> writes.add(new Object[]{group, key, value}), chatOnly(chat));

		assertEquals(1, writes.size());
		assertArrayEquals(new Object[]{"ironwise", "showNextStep", false}, writes.get(0));
		assertEquals(1, chat.size());
		assertArrayEquals(new Object[]{ChatMessageType.GAMEMESSAGE, "",
			"Ironwise: Next step box hidden. Tick Show next guide step in the Ironwise settings to bring it back.", null}, chat.get(0));
	}

	@Test
	public void theSettingHideWritesIsTheBoxsSetting() throws NoSuchMethodException
	{
		// The group and key the settings panel uses for "Show next guide step", and the name the chat line gives.
		assertEquals(IronwiseConfig.class.getAnnotation(ConfigGroup.class).value(), IronwiseConfig.GROUP);
		ConfigItem item = IronwiseConfig.class.getMethod("showNextStep").getAnnotation(ConfigItem.class);
		assertEquals(item.keyName(), IronwiseConfig.SHOW_NEXT_STEP);
		assertTrue(NextStepOverlay.HIDDEN.contains("Tick " + item.name() + " in the Ironwise settings"));
		// The description tells players about Hide.
		assertTrue(item.description(), item.description().contains("Hide"));
	}

	@Test
	public void hidingDoesntSyncAgain() throws ReflectiveOperationException
	{
		// Syncing stopped over a setting only the player can fix, and nothing has changed since the last sync.
		IronwisePlugin plugin = new IronwisePlugin();
		set(plugin, "stopped", "Ironwise: paste your device token in the plugin settings.");
		set(plugin, "dirty", false);
		set(plugin, "announced", true);

		ConfigChanged changed = new ConfigChanged();
		changed.setGroup(IronwiseConfig.GROUP);
		changed.setKey(IronwiseConfig.SHOW_NEXT_STEP);
		changed.setOldValue("true");
		changed.setNewValue("false");
		plugin.onConfigChanged(changed);

		// Only the box changed: no new sync, no "syncing" line, and still stopped.
		assertFalse((Boolean) get(plugin, "dirty"));
		assertTrue((Boolean) get(plugin, "announced"));
		assertEquals("Ironwise: paste your device token in the plugin settings.", get(plugin, "stopped"));
	}

	@Test
	public void theBoxDrawsNothingOnceHiddenAndComesBackWithTheSetting()
	{
		// The setting, as RuneLite's ConfigManager would keep it.
		AtomicBoolean shown = new AtomicBoolean(true);
		IronwiseConfig config = new IronwiseConfig()
		{
			@Override
			public boolean syncEnabled()
			{
				return true;
			}

			@Override
			public boolean showNextStep()
			{
				return shown.get();
			}
		};
		GuideState guide = new GuideState();
		guide.synced(guide.session(), "1234567890123456789", 1, NextStep.fromBody(RuneLiteAPI.GSON, "{\"guide\":" + NextStepTest.stepJson() + "}", "guide"));
		assertNotNull(guide.step());
		List<Object[]> chat = new ArrayList<>();
		Client client = loggedIn(chat);
		NextStepOverlay overlay = new NextStepOverlay(new IronwisePlugin(), client, config, guide);
		Graphics2D graphics = new BufferedImage(400, 400, BufferedImage.TYPE_INT_ARGB).createGraphics();

		Dimension before = overlay.render(graphics);
		assertNotNull(before);
		assertTrue(before.height > 0);

		NextStepOverlay.hide((group, key, value) ->
		{
			if (IronwiseConfig.GROUP.equals(group) && IronwiseConfig.SHOW_NEXT_STEP.equals(key))
			{
				shown.set(value);
			}
		}, client);
		assertFalse(shown.get());
		assertNull(overlay.render(graphics));
		// Hide didn't forget the step: ticking the setting again shows it at once.
		assertNotNull(guide.step());
		shown.set(true);
		assertNotNull(overlay.render(graphics));
		assertEquals(1, chat.size());
		graphics.dispose();
	}

	/** A logged-in Client on a standard world that records chat lines and fails on anything else. */
	private static Client loggedIn(List<Object[]> chat)
	{
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			switch (method.getName())
			{
				case "getGameState":
					return GameState.LOGGED_IN;
				case "getWorldType":
					return EnumSet.noneOf(WorldType.class);
				case "addChatMessage":
					chat.add(args);
					return null;
				default:
					throw new AssertionError("the box called Client." + method.getName());
			}
		});
	}

	private static void set(IronwisePlugin plugin, String name, Object value) throws ReflectiveOperationException
	{
		Field f = IronwisePlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private static Object get(IronwisePlugin plugin, String name) throws ReflectiveOperationException
	{
		Field f = IronwisePlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(plugin);
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.Predicate;
import org.junit.Test;

/** Wrapping the step's text for the Next step box (the box measures in pixels; these tests in characters). */
public class NextStepOverlayTest
{
	private static final Predicate<String> FITS_32 = s -> s.length() <= 32;
	private static final String E = NextStepOverlay.ELLIPSIS;

	private static List<String> wrap(String text)
	{
		return NextStepOverlay.wrap(text, NextStepOverlay.TEXT_LINES, FITS_32);
	}

	@Test
	public void shortTextIsOneLine()
	{
		assertEquals(Collections.singletonList("Bank at Draynor."), wrap("  Bank at   Draynor. "));
	}

	@Test
	public void wrapsBetweenWords()
	{
		List<String> lines = wrap("Chop logs south of the castle until 15 woodcutting, then light them.");
		assertEquals(Arrays.asList(
			"Chop logs south of the castle",
			"until 15 woodcutting, then light",
			"them."), lines);
		for (String line : lines)
		{
			assertTrue(line, line.length() <= 32);
		}
	}

	@Test
	public void theBoxIsCompact()
	{
		// Title, "Step n of total", at most three lines of the step and one line of where it is.
		assertEquals(3, NextStepOverlay.TEXT_LINES);
		assertEquals(1, NextStepOverlay.PLACE_LINES);
	}

	@Test
	public void atMostThreeLinesThenAnEllipsis()
	{
		String text = "Walk north to the farm and pick some cabbages, then head east along the road to the "
			+ "big city and buy a hammer and a chisel from the general store before the long trip south.";
		List<String> lines = wrap(text);
		assertEquals(3, lines.size());
		assertTrue(lines.get(2), lines.get(2).endsWith(E));
		for (String line : lines)
		{
			assertTrue(line, line.length() <= 32);
		}
		assertEquals("Walk north to the farm and pick", lines.get(0));
	}

	@Test
	public void exactlyThreeLinesHaveNoEllipsis()
	{
		String text = "aaaa bbbb cccc dddd eeee ffff gg hhhh iiii jjjj kkkk llll mmmm nn oooo pppp qqqq rrrr ssss tttt uu";
		assertEquals(Arrays.asList(
			"aaaa bbbb cccc dddd eeee ffff gg",
			"hhhh iiii jjjj kkkk llll mmmm nn",
			"oooo pppp qqqq rrrr ssss tttt uu"), wrap(text));
	}

	@Test
	public void aFourthLineIsCutIntoTheThird()
	{
		String text = "aaaa bbbb cccc dddd eeee ffff gg hhhh iiii jjjj kkkk llll mmmm nn oooo pppp qqqq rrrr ssss tttt uu vvvv wwww xxxx yyyy zz";
		assertEquals(Arrays.asList(
			"aaaa bbbb cccc dddd eeee ffff gg",
			"hhhh iiii jjjj kkkk llll mmmm nn",
			"oooo pppp qqqq rrrr ssss tttt u" + E), wrap(text));
	}

	@Test
	public void aWordLongerThanALineIsBroken()
	{
		List<String> lines = NextStepOverlay.wrap("see https://example.com/a/very/long/link/that/goes/on/and/on ok", 4, FITS_32);
		assertEquals("see", lines.get(0));
		assertEquals("https://example.com/a/very/long/", lines.get(1));
		assertEquals("link/that/goes/on/and/on ok", lines.get(2));
	}

	@Test
	public void oneLineOnly()
	{
		assertEquals(Collections.singletonList("Chapter 2: The long middle bit" + E),
			NextStepOverlay.wrap("Chapter 2: The long middle bit of the guide", 1, FITS_32));
	}

	@Test
	public void theEllipsisAlwaysFits()
	{
		// A full last line is shortened to make room.
		List<String> lines = NextStepOverlay.wrap("abcdefghij abcdefghij abcdefghij klm", 1, s -> s.length() <= 32);
		assertEquals(Collections.singletonList("abcdefghij abcdefghij abcdefghi" + E), lines);
		assertTrue(lines.get(0).length() <= 32);
	}

	@Test
	public void nothingToWrap()
	{
		assertTrue(wrap("").isEmpty());
		assertTrue(wrap("   ").isEmpty());
		assertTrue(wrap(null).isEmpty());
		// Even a box too narrow for one character makes progress.
		assertEquals(Arrays.asList("a", E), NextStepOverlay.wrap("abc", 2, s -> s.length() <= 0));
	}

	@Test
	public void chapterAndSection()
	{
		// An Ironwise that doesn't send "where" (before 0.4.1): the chapter and section titles.
		JsonObject o = NextStepTest.stepJson();
		assertEquals("Chapter 1: Getting started \u00B7 Around Lumbridge", NextStepOverlay.place(NextStep.parse(o)));
		o.addProperty("section", "");
		assertEquals("Chapter 1: Getting started", NextStepOverlay.place(NextStep.parse(o)));
		o.addProperty("chapter", "");
		o.addProperty("section", "Around Lumbridge");
		assertEquals("Around Lumbridge", NextStepOverlay.place(NextStep.parse(o)));
	}

	@Test
	public void whereTheStepIsWhenIronwiseSendsIt()
	{
		JsonObject o = NextStepTest.stepJson();
		o.addProperty("where", "Ch 2 \u00B7 2.2");
		assertEquals("Ch 2 \u00B7 2.2", NextStepOverlay.place(NextStep.parse(o)));
		// Blank or not text: back to the chapter and section.
		o.addProperty("where", "  ");
		assertEquals("Chapter 1: Getting started \u00B7 Around Lumbridge", NextStepOverlay.place(NextStep.parse(o)));
		o.addProperty("where", 22);
		assertEquals("Chapter 1: Getting started \u00B7 Around Lumbridge", NextStepOverlay.place(NextStep.parse(o)));
	}

	@Test
	public void thePlaceIsOneLine()
	{
		JsonObject o = NextStepTest.stepJson();
		o.addProperty("where", "Ch 2 \u00B7 2.2");
		assertEquals(Collections.singletonList("Ch 2 \u00B7 2.2"),
			NextStepOverlay.wrap(NextStepOverlay.place(NextStep.parse(o)), NextStepOverlay.PLACE_LINES, FITS_32));
		// Titles too long for one line are cut with "...", never after a dangling middle dot.
		o.remove("where");
		assertEquals(Collections.singletonList("Chapter 1: Getting started" + E),
			NextStepOverlay.wrap(NextStepOverlay.place(NextStep.parse(o)), NextStepOverlay.PLACE_LINES, FITS_32));
	}

	@Test
	public void theEllipsisDoesntFollowASeparator()
	{
		assertEquals("Chop logs, then" + E, NextStepOverlay.ellipsize("Chop logs, then,", FITS_32));
		assertEquals("Lumbridge" + E, NextStepOverlay.ellipsize("Lumbridge \u00B7 ", FITS_32));
		assertEquals("Buy: a hammer" + E, NextStepOverlay.ellipsize("Buy: a hammer;", FITS_32));
		assertEquals("Mine -> bank" + E, NextStepOverlay.ellipsize("Mine -> bank", FITS_32));
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Test;

/** The guide's next step as Ironwise sends it. Made-up steps in the guide's style, never the guide's own text. */
public class NextStepTest
{
	private static final Gson GSON = RuneLiteAPI.GSON;

	/** A valid step as JSON (synthetic). */
	static JsonObject stepJson()
	{
		JsonObject o = new JsonObject();
		o.addProperty("variant", "main");
		o.addProperty("stepId", "0123456789abcdef");
		o.addProperty("n", 12);
		o.addProperty("total", 40);
		o.addProperty("chapter", "Chapter 1: Getting started");
		o.addProperty("section", "Around Lumbridge");
		o.addProperty("text", "Talk to the cook in the castle kitchen to start the quest, then bank at the top floor.");
		o.addProperty("done", 11);
		o.addProperty("state", "todo");
		return o;
	}

	private static NextStep parse(JsonObject o)
	{
		return NextStep.parse(o);
	}

	private static JsonObject with(String key, Object value)
	{
		JsonObject o = stepJson();
		if (value == null)
		{
			o.remove(key);
		}
		else if (value instanceof Number)
		{
			o.addProperty(key, (Number) value);
		}
		else
		{
			o.addProperty(key, value.toString());
		}
		return o;
	}

	@Test
	public void aStep()
	{
		NextStep s = parse(stepJson());
		assertNotNull(s);
		assertEquals("main", s.variant);
		assertEquals("0123456789abcdef", s.stepId);
		assertEquals(12, s.n);
		assertEquals(40, s.total);
		assertEquals(11, s.done);
		assertEquals("Chapter 1: Getting started", s.chapter);
		assertEquals("Around Lumbridge", s.section);
		assertEquals("Talk to the cook in the castle kitchen to start the quest, then bank at the top floor.", s.text);
		assertFalse(s.behind);

		NextStep behind = parse(with("state", "behind"));
		assertNotNull(behind);
		assertTrue(behind.behind);
		assertEquals("landlubber", parse(with("variant", "landlubber")).variant);
		assertEquals("0123456789abcdef-2", parse(with("stepId", "0123456789abcdef-2")).stepId);
	}

	@Test
	public void fieldsIronwiseAddsLaterAreIgnored()
	{
		JsonObject o = stepJson();
		o.addProperty("colour", "green");
		o.add("extra", new JsonObject());
		assertNotNull(parse(o));
	}

	@Test
	public void anythingWrongMeansNoStep()
	{
		assertNull(NextStep.parse(null));
		assertNull(NextStep.parse(new JsonParser().parse("\"a step\"")));
		assertNull(NextStep.parse(new JsonParser().parse("[1,2]")));
		assertNull(NextStep.parse(new JsonParser().parse("{}")));
		assertNull(parse(with("variant", "ironman")));
		assertNull(parse(with("variant", null)));
		for (String id : new String[]{"0123456789ABCDEF", "0123456789abcde", "0123456789abcdef0", "0123456789abcdef-", "0123456789abcdef-x", "../../etc", ""})
		{
			assertNull(id, parse(with("stepId", id)));
		}
		assertNull(parse(with("state", "done")));
		assertNull(parse(with("state", null)));
		assertNull(parse(with("n", 0)));
		assertNull(parse(with("n", 41)));
		assertNull(parse(with("n", 1.5)));
		assertNull(parse(with("n", "12")));
		assertNull(parse(with("total", null)));
		assertNull(parse(with("total", 1_000_000)));
		assertNull(parse(with("done", -1)));
		assertNull(parse(with("done", 41)));
		assertNull(parse(with("chapter", null)));
		assertNull(parse(with("section", null)));
		assertNull(parse(with("text", null)));
		assertNull(parse(with("text", "   ")));
		JsonObject numberText = stepJson();
		numberText.addProperty("text", 5);
		assertNull(parse(numberText));
	}

	@Test
	public void whereTheStepIsInTheGuide()
	{
		NextStep s = parse(with("where", "Ch 2 \u00B7 2.2"));
		assertNotNull(s);
		assertEquals("Ch 2 \u00B7 2.2", s.where);
		// Plain one-line text like the rest of the step, and no longer than a title.
		assertEquals("Ch 12 \u00B7 12.3", parse(with("where", " <col=ff0000>Ch 12</col>\n\u00B7\u00A012.3 ")).where);
		StringBuilder long_ = new StringBuilder("Ch 2 \u00B7 2.2");
		while (long_.length() < 150)
		{
			long_.append(" more");
		}
		String cut = parse(with("where", long_.toString())).where;
		assertTrue(cut.length() <= 100);
		assertTrue(cut.startsWith("Ch 2 \u00B7 2.2"));
	}

	@Test
	public void noWhereFromAnOlderIronwise()
	{
		// Left out (Ironwise before the plugin's 0.4.1), null, blank or not text: the step still shows.
		NextStep absent = parse(stepJson());
		assertNotNull(absent);
		assertNull(absent.where);
		JsonObject nullWhere = stepJson();
		nullWhere.add("where", JsonNull.INSTANCE);
		JsonObject objectWhere = stepJson();
		objectWhere.add("where", new JsonObject());
		for (JsonObject o : new JsonObject[]{with("where", ""), with("where", "   "), with("where", 22), nullWhere, objectWhere})
		{
			NextStep s = parse(o);
			assertNotNull(o.toString(), s);
			assertNull(o.toString(), s.where);
			assertEquals("0123456789abcdef", s.stepId);
		}
	}

	@Test
	public void blankChapterOrSectionIsFine()
	{
		NextStep s = parse(with("section", ""));
		assertNotNull(s);
		assertEquals("", s.section);
	}

	@Test
	public void textIsPlainAndShort()
	{
		// Curly quotes and dashes aren't in RuneLite's regular font; line breaks, tabs and NBSP become spaces.
		assertEquals("Buy a 'bucket' - then \"fill\" it -> bank", NextStep.clean("Buy a \u2018bucket\u2019 \u2013 then \u201Cfill\u201D it \u2192 bank", 240));
		assertEquals("Mine 10 ore then smelt", NextStep.clean("  Mine\u00A010 ore\n\tthen\r\n smelt ", 240));
		// No colour tags, emoji or invisible characters.
		assertEquals("Kill a goblin", NextStep.clean("<col=ff0000>Kill a\u200B goblin</col> \uD83D\uDE00", 240));
		assertEquals("need >= 20 hp", NextStep.clean("need \u2265 20 hp", 240));

		StringBuilder long_ = new StringBuilder();
		for (int i = 0; i < 60; i++)
		{
			long_.append("step ");
		}
		String cut = NextStep.clean(long_.toString(), NextStep.MAX_TEXT);
		assertTrue(cut.length() <= NextStep.MAX_TEXT);
		assertTrue(cut.endsWith("\u2026"));

		NextStep s = parse(with("text", long_.toString()));
		assertNotNull(s);
		assertTrue(s.text.length() <= NextStep.MAX_TEXT);
	}

	@Test
	public void guideInASyncAnswer()
	{
		JsonObject answer = new JsonObject();
		answer.addProperty("ok", true);
		answer.addProperty("rsn", "Iron Example");
		answer.addProperty("receivedAt", 1);
		// No "guide": Ironwise didn't work it out this time (keep what's shown).
		assertSame(NextStep.Reply.NOTHING, NextStep.fromBody(GSON, answer.toString(), "guide"));

		answer.add("guide", stepJson());
		NextStep.Reply present = NextStep.fromBody(GSON, answer.toString(), "guide");
		assertTrue(present.said);
		assertEquals("0123456789abcdef", present.step.stepId);

		// "guide": null - Ironwise says there's no step.
		NextStep.Reply none = NextStep.fromBody(GSON, "{\"ok\":true,\"guide\":null}", "guide");
		assertTrue(none.said);
		assertNull(none.step);

		// Something the plugin can't read: show nothing rather than a step that may be stale.
		for (String garbage : new String[]{"\"step 12\"", "42", "[]", "{}", "{\"stepId\":\"0123456789abcdef\"}"})
		{
			NextStep.Reply r = NextStep.fromBody(GSON, "{\"ok\":true,\"guide\":" + garbage + "}", "guide");
			assertTrue(garbage, r.said);
			assertNull(garbage, r.step);
		}

		// Not JSON at all: nothing said.
		for (String body : new String[]{"", "<html>", "ok", "[1]", "{\"ok\":true,"})
		{
			assertSame(body, NextStep.Reply.NOTHING, NextStep.fromBody(GSON, body, "guide"));
		}
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.awt.image.BufferedImage;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Properties;
import java.util.Set;
import java.util.regex.Pattern;
import javax.imageio.ImageIO;
import org.junit.Test;

/**
 * The Plugin Hub's own checks on a pull request (runelite/plugin-hub-tooling, Plugin.java at
 * 5893c9f), plus the rules in its template's AGENTS.md, so an update can't quietly break them.
 * Gradle runs tests from the project folder, so the files are read from there.
 */
public class PluginHubRulesTest
{
	/** Every key the Hub's packager accepts in runelite-plugin.properties; any other key fails the build. */
	private static final Set<String> ALLOWED_KEYS = new HashSet<>(Arrays.asList(
		"displayName", "author", "description", "tags", "version", "plugins", "build", "support"));

	/** RuneLite's exact wording for a setting that sends data to a third-party server. */
	static final String THIRD_PARTY_WARNING =
		"This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers";

	private static Properties descriptor() throws IOException
	{
		Properties p = new Properties();
		try (InputStream in = new FileInputStream("runelite-plugin.properties"))
		{
			p.load(in);
		}
		return p;
	}

	@Test
	public void descriptorHasWhatTheHubNeeds() throws IOException
	{
		Properties p = descriptor();
		for (String key : p.stringPropertyNames())
		{
			assertTrue("unknown key " + key, ALLOWED_KEYS.contains(key));
		}
		assertEquals("Ironwise", p.getProperty("displayName"));
		assertEquals("Odrive", p.getProperty("author"));
		assertFalse(p.getProperty("description", "").trim().isEmpty());
		assertEquals(IronwisePlugin.class.getName(), p.getProperty("plugins"));
		assertEquals("standard", p.getProperty("build"));
		// Shown on the Hub; keep it the same as the version the plugin reports to Ironwise.
		assertEquals(IronwisePlugin.VERSION, p.getProperty("version"));
	}

	@Test
	public void iconIsWithinTheHubsLimits() throws IOException
	{
		File icon = new File("icon.png");
		assertTrue(icon.length() <= 256 * 1024);
		BufferedImage image = ImageIO.read(icon);
		assertNotNull("icon.png must be a real PNG", image);
		// "no larger than 48x72 px" (plugin-hub README); the packager refuses more than 5,000 pixels.
		assertTrue(image.getWidth() <= 48 && image.getHeight() <= 72);
	}

	@Test
	public void licenceIsBsd2() throws IOException
	{
		String licence = new String(Files.readAllBytes(new File("LICENSE").toPath()), StandardCharsets.UTF_8);
		assertTrue(licence.startsWith("BSD 2-Clause License"));
		assertTrue(licence.contains("Copyright (c) 2026, Odrive"));
		// RuneLite's farming value tables, copied into the tests' data, keep RuneLite's notice and licence (BSD 2-Clause).
		String notice = new String(Files.readAllBytes(new File("NOTICE").toPath()), StandardCharsets.UTF_8);
		assertTrue(new File("src/test/resources/com/ironwise/farm-advance-cases.json").isFile());
		assertTrue(notice.contains("farm-advance-cases.json"));
		assertTrue(notice.contains("be6527130b1e2bd27ac072c724145e5e60d6f73a"));
		assertTrue(notice.contains("Copyright (c) 2019 Abex"));
		assertTrue(notice.contains("Redistributions of source code must retain the above copyright notice"));
		assertTrue(notice.contains("SOFTWARE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGE."));
	}

	@Test
	public void sendingTheCollectionLogAndFarmRunsAreOffByDefault()
	{
		IronwiseConfig defaults = new IronwiseConfig()
		{
		};
		assertFalse(defaults.syncEnabled());
		assertFalse(defaults.syncCollectionLog());
		assertFalse(defaults.farmRuns());
		assertEquals(IronwiseConfig.DEFAULT_ADDRESS, defaults.serverUrl());
		assertTrue(defaults.serverUrl().startsWith("https://"));
	}

	@Test
	public void theSettingsThatTalkToIronwiseCarryRuneLitesWarning() throws IOException
	{
		// Read from the source: Sync with Ironwise and Farm runs, each with RuneLite's exact words (FarmRunSettingsTest
		// checks which items carry it).
		String config = new String(Files.readAllBytes(new File("src/main/java/com/ironwise/IronwiseConfig.java").toPath()), StandardCharsets.UTF_8);
		String warning = "warning = \"" + THIRD_PARTY_WARNING + "\"";
		assertEquals(2, config.split(Pattern.quote(warning), -1).length - 1);
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

/**
 * Every patch type's advance on real values: the app's advance cases (src/data/generated/farm-advance-cases.json, a copy
 * in this test's resources), with the class tables and done rules Ironwise sends and whether each sequence of varbit
 * (or bird house varp) values ends the stop. The hash pins the copy to the app's file: the app's
 * src/data/farm-patches.test.ts holds the same value, so a change there fails until this copy is updated too.
 */
public class StopWatcherFixtureTest
{
	/** The app's ADVANCE_CASES_SHA256: sha256 of the file with "\n" line ends. */
	private static final String SHA256 = "faaec7582396ee8d770e11ee312b2366b8aa8c09e79aab24e4f70d8e56a54812";

	private static String fixture() throws IOException
	{
		try (InputStream in = StopWatcherFixtureTest.class.getResourceAsStream("farm-advance-cases.json"))
		{
			assertNotNull("copy the app's src/data/generated/farm-advance-cases.json into src/test/resources/com/ironwise/", in);
			return new String(in.readAllBytes(), StandardCharsets.UTF_8).replace("\r\n", "\n");
		}
	}

	@Test
	public void theCopyIsTheAppsFile() throws Exception
	{
		StringBuilder hex = new StringBuilder();
		for (byte b : MessageDigest.getInstance("SHA-256").digest(fixture().getBytes(StandardCharsets.UTF_8)))
		{
			hex.append(String.format("%02x", b));
		}
		assertEquals("the app's farm-advance-cases.json changed: copy it here and update SHA256", SHA256, hex.toString());
	}

	@Test
	public void everyTypeAdvancesOnItsRealValues() throws IOException
	{
		JsonObject data = FarmRunsTest.json(fixture()).getAsJsonObject().getAsJsonObject("data");
		assertEquals(StopWatcher.SETTLE_TICKS, data.get("settleTicks").getAsInt());
		Map<String, List<FarmRuns.Range>> tables = FarmRuns.parse(FarmRunsTest.json("{\"ok\":true,\"rev\":\"r\",\"presets\":[],\"active\":null,\"tables\":" + data.get("tables") + "}")).tables;
		JsonObject impls = data.getAsJsonObject("impls");
		JsonObject doneWhen = data.getAsJsonObject("doneWhen");
		int cases = 0;
		for (JsonElement e : data.getAsJsonArray("cases"))
		{
			JsonObject c = e.getAsJsonObject();
			String type = c.get("type").getAsString();
			String watch = impls.get(type).isJsonNull()
				? "{\"kind\":\"birdhouse\",\"varp\":" + VarPlayerID.BIRDHOUSE_TRANSMIT_A + ",\"regions\":[1],\"plane\":0,\"near\":{\"x\":0,\"y\":0,\"plane\":0}}"
				: "{\"kind\":\"varbit\",\"varbit\":" + VarbitID.FARMING_TRANSMIT_A + ",\"impl\":\"" + impls.get(type).getAsString() + "\",\"regions\":[1],\"bounds\":null,\"doneWhen\":" + doneWhen.get(type) + "}";
			StopWatcher w = new StopWatcher(StopWatcherTest.stop("case", watch), tables);
			boolean done = false;
			for (JsonElement v : c.getAsJsonArray("values"))
			{
				done |= w.tick(0, 0, 0, 1, v.getAsInt()) == StopWatcher.Event.DONE;
			}
			assertEquals(type + ": " + c.get("name").getAsString(), c.get("done").getAsBoolean(), done);
			cases++;
		}
		assertEquals(35, cases);
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * The run box's advance on one stop, the gating around it: made-up class tables in the app's shape (a few rows each
 * for HERB, TREE and BUSH; every type's real tables are replayed in StopWatcherFixtureTest), regions and bounds, settle
 * ticks, and bird house varp values as RuneLite's BirdHouseState reads them.
 */
public class StopWatcherTest
{
	private static final String TABLES = "{\"HERB\":[[0,3,\"empty\"],[4,7,\"planted\"],[8,10,\"harvest\"],[32,35,\"planted\"],[36,38,\"harvest\"],[140,142,\"diseased\"],[170,172,\"dead\"]],"
		+ "\"TREE\":[[0,7,\"empty\"],[48,59,\"planted\"],[60,60,\"grown\"],[61,62,\"harvest\"]],"
		+ "\"BUSH\":[[0,4,\"empty\"],[5,9,\"planted\"],[10,14,\"harvest\"],[250,250,\"grown\"]]}";
	private static final String REPLANTED = "[{\"from\":[\"empty\",\"grown\",\"harvest\",\"diseased\",\"dead\"],\"to\":\"planted\"}]";
	private static final String CHECKED = "[{\"from\":[\"empty\",\"grown\",\"harvest\",\"diseased\",\"dead\"],\"to\":\"planted\"},{\"from\":[\"grown\"],\"to\":\"harvest\"}]";

	/** A one-stop run's current stop, as the server would send it (StopWatcherFixtureTest uses it too). */
	static FarmRuns.Stop stop(String id, String watch)
	{
		String json = "{\"ok\":true,\"rev\":\"r\",\"presets\":[],\"tables\":" + TABLES + ",\"active\":{\"name\":\"Run\",\"index\":0,\"finished\":false,\"startedAt\":1,"
			+ "\"stops\":[{\"patchId\":\"" + id + "\",\"name\":\"Stop\",\"type\":\"herb\",\"cluster\":\"catherby\",\"state\":\"current\",\"point\":{\"x\":1,\"y\":1,\"plane\":0},\"watch\":" + watch + "}],\"bring\":[]}}";
		return FarmRuns.parse(FarmRunsTest.json(json)).active.current();
	}

	private static Map<String, List<FarmRuns.Range>> tables()
	{
		return FarmRuns.parse(FarmRunsTest.json("{\"ok\":true,\"rev\":\"r\",\"presets\":[],\"active\":null,\"tables\":" + TABLES + "}")).tables;
	}

	private static StopWatcher herb(String impl, String rules)
	{
		return new StopWatcher(stop("herb-catherby", "{\"kind\":\"varbit\",\"varbit\":4774,\"impl\":\"" + impl + "\",\"regions\":[11062,11061],"
			+ "\"bounds\":{\"any\":[{\"maxX\":2815},{\"minY\":3456},{\"minX\":2816,\"maxX\":2839,\"minY\":3440,\"maxY\":3455,\"plane\":0}]},\"doneWhen\":" + rules + "}"), tables());
	}

	/** Feeds values one tick each while standing at Catherby's patches (region 11062, in bounds); true if any tick said DONE. */
	private static boolean feed(StopWatcher w, int... values)
	{
		boolean done = false;
		for (int v : values)
		{
			done |= w.tick(2810, 3464, 0, 11062, v) == StopWatcher.Event.DONE;
		}
		return done;
	}

	@Test
	public void herbsHarvestRakePlant()
	{
		StopWatcher w = herb("HERB", REPLANTED);
		// Two settle ticks, then ready (36), picked to weeds (3, 0), planted (32).
		assertTrue(feed(w, 36, 36, 36, 37, 3, 0, 32));
		assertEquals("herb-catherby", w.patchId());
	}

	@Test
	public void arrivingAtAGrowingPatchIsNotDone()
	{
		StopWatcher w = herb("HERB", REPLANTED);
		assertEquals(false, feed(w, 32, 32, 32, 33, 33));
		assertEquals(StopWatcher.GROWING, w.hint());
	}

	@Test
	public void theSettleTicksIgnoreTheLastRegionsValue()
	{
		StopWatcher w = herb("HERB", REPLANTED);
		// 0 is left over from the last region; the patch itself is growing (32): no false "empty → planted".
		assertEquals(false, feed(w, 0, 0, 32, 32));
	}

	@Test
	public void aResetSettlesAgain()
	{
		StopWatcher w = herb("HERB", REPLANTED);
		assertEquals(false, feed(w, 36, 36, 36));
		// A hop: the first readings after it (a stale 0, then the patch) are ignored, so no false "empty → planted".
		w.reset();
		assertEquals(false, feed(w, 0, 0, 32, 32));
	}

	@Test
	public void curingADiseasedHerbCounts()
	{
		assertTrue(feed(herb("HERB", REPLANTED), 140, 140, 140, 33));
	}

	@Test
	public void treesCheckChopDigPlant()
	{
		assertTrue(feed(herb("TREE", REPLANTED), 60, 60, 60, 61, 62, 0, 48));
	}

	@Test
	public void aHealthCheckCountsOnlyWithItsRule()
	{
		assertTrue(feed(herb("BUSH", CHECKED), 250, 250, 250, 10));
		assertEquals(false, feed(herb("BUSH", REPLANTED), 250, 250, 250, 10));
	}

	@Test
	public void valuesWithNoRowAreIgnored()
	{
		StopWatcher w = herb("HERB", REPLANTED);
		assertEquals(false, feed(w, 36, 36, 36, 110, 111));
		assertTrue(feed(w, 0, 32));
	}

	@Test
	public void onlyInTheRegionAndBounds()
	{
		StopWatcher w = herb("HERB", REPLANTED);
		// Another region, or upstairs at the fruit tree's end of Catherby: never read.
		for (int i = 0; i < 5; i++)
		{
			assertEquals(StopWatcher.Event.NONE, w.tick(3000, 3000, 0, 12083, i % 2 == 0 ? 36 : 32));
			assertEquals(StopWatcher.Event.NONE, w.tick(2830, 3445, 1, 11062, i % 2 == 0 ? 36 : 32));
		}
		// Leaving forgets what was seen: harvestable, leave, come back planted is not "done here".
		assertEquals(false, feed(w, 36, 36, 36));
		w.tick(3000, 3000, 0, 12083, 0);
		assertEquals(false, feed(w, 32, 32, 32, 32));
	}

	@Test
	public void birdHousesResetOnlyNearTheSpace()
	{
		FarmRuns.Stop s = stop("birdhouse-valley-north", "{\"kind\":\"birdhouse\",\"varp\":1628,\"regions\":[15162],\"plane\":0,\"near\":{\"x\":3768,\"y\":3761,\"plane\":0}}");
		StopWatcher w = new StopWatcher(s, tables());
		// Far across the valley: nothing counts.
		for (int v : new int[]{3, 0, 1, 3})
		{
			assertEquals(StopWatcher.Event.NONE, w.tick(3700, 3761, 0, 15162, v));
		}
		// At the space: settle, full house (seeded 21), dismantled (0), built (19), seeded (21): done.
		int[] values = {21, 21, 21, 0, 19, 21};
		boolean done = false;
		for (int v : values)
		{
			done |= w.tick(3767, 3760, 0, 15162, v) == StopWatcher.Event.DONE;
		}
		assertTrue(done);
	}

	@Test
	public void birdHouseValues()
	{
		assertEquals("empty", StopWatcher.birdhouseClass(0));
		assertEquals("built", StopWatcher.birdhouseClass(1));
		assertEquals("seeded", StopWatcher.birdhouseClass(27));
		assertNull(StopWatcher.birdhouseClass(28));
		assertNull(StopWatcher.birdhouseClass(-1));
	}

	@Test
	public void noWatchNeverAdvances()
	{
		StopWatcher w = new StopWatcher(stop("herb-catherby", "null"), tables());
		assertEquals(StopWatcher.Event.NONE, w.tick(2810, 3464, 0, 11062, 32));
		assertNull(w.hint());
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.sun.net.httpserver.HttpServer;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.http.api.RuneLiteAPI;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/** SyncClient against a real (local) HTTP server: what actually goes over the wire. */
public class SyncClientHttpTest
{
	private static final byte[] OK = "{\"ok\":true,\"rsn\":\"Iron Test\",\"receivedAt\":1}".getBytes(StandardCharsets.UTF_8);

	private HttpServer server;
	private String base;
	/** "path Authorization" for every request the server saw. */
	private final List<String> seen = new CopyOnWriteArrayList<>();
	private final SyncClient client = new SyncClient(new OkHttpClient(), RuneLiteAPI.GSON);

	@Before
	public void start() throws Exception
	{
		server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/", exchange ->
		{
			String path = exchange.getRequestURI().getPath();
			seen.add(path + " " + exchange.getRequestHeaders().getFirst("Authorization"));
			exchange.getRequestBody().close();
			if ("/ok/api/sync".equals(path))
			{
				exchange.sendResponseHeaders(200, OK.length);
				try (OutputStream out = exchange.getResponseBody())
				{
					out.write(OK);
				}
				return;
			}
			if ("/moved/api/sync".equals(path))
			{
				exchange.getResponseHeaders().add("Location", base + "/elsewhere/api/sync");
			}
			exchange.sendResponseHeaders("/moved/api/sync".equals(path) ? 307 : 404, -1);
			exchange.close();
		});
		server.start();
		base = "http://127.0.0.1:" + server.getAddress().getPort();
	}

	@After
	public void stop()
	{
		server.stop(0);
	}

	private SyncClient.Result send(String address) throws Exception
	{
		HttpUrl url = SyncClient.syncUrl(address);
		assertNotNull(address, url);
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<SyncClient.Result> result = new AtomicReference<>();
		client.send(url, "iw_test", "{}", r ->
		{
			result.set(r);
			done.countDown();
		});
		assertTrue("no answer in time", done.await(20, TimeUnit.SECONDS));
		return result.get();
	}

	@Test
	public void savedByIronwise() throws Exception
	{
		assertEquals(SyncClient.Outcome.OK, send(base + "/ok").outcome);
		assertEquals("/ok/api/sync Bearer iw_test", seen.get(0));
	}

	@Test
	public void aRedirectIsNotFollowedAndTheTokenStaysPut() throws Exception
	{
		SyncClient.Result r = send(base + "/moved");
		assertEquals(SyncClient.Outcome.WRONG_ADDRESS, r.outcome);
		assertEquals("that address redirects to " + base + "/elsewhere; use that address instead.", r.message);
		// Only the address the player set was asked; the token never went to the redirect's target.
		assertEquals(1, seen.size());
		assertEquals("/moved/api/sync Bearer iw_test", seen.get(0));
	}

	@Test
	public void aCutOffAnswerIsRetriedNotAWrongAddress() throws Exception
	{
		// A server that promises Ironwise's whole answer, sends a few bytes of it, then hangs up.
		try (ServerSocket cut = new ServerSocket(0, 1, InetAddress.getByName("127.0.0.1")))
		{
			Thread t = new Thread(() ->
			{
				try (Socket s = cut.accept())
				{
					BufferedReader in = new BufferedReader(new InputStreamReader(s.getInputStream(), StandardCharsets.UTF_8));
					String line;
					while ((line = in.readLine()) != null && !line.isEmpty())
					{
						// skip the request headers
					}
					OutputStream out = s.getOutputStream();
					out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: " + OK.length + "\r\n\r\n").getBytes(StandardCharsets.UTF_8));
					out.write(OK, 0, 5);
					out.flush();
				}
				catch (Exception e)
				{
					// the test fails on the result instead
				}
			});
			t.start();
			SyncClient.Result r = send("http://127.0.0.1:" + cut.getLocalPort());
			t.join(5000);
			assertEquals(r.message, SyncClient.Outcome.RETRY, r.outcome);
			assertTrue(r.message, r.message.startsWith("couldn't read the app's answer"));
		}
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import net.runelite.http.api.RuneLiteAPI;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import org.junit.Test;

public class SyncClientTest
{
	private final SyncClient client = new SyncClient(new OkHttpClient(), RuneLiteAPI.GSON);

	private static String url(String address)
	{
		HttpUrl u = SyncClient.syncUrl(address);
		return u == null ? null : u.toString();
	}

	private SyncClient.Result answer(int code, String body)
	{
		return client.result(code, body, null);
	}

	private SyncClient.Result redirect(int code, String location)
	{
		return client.result(code, "", HttpUrl.parse("https://ironwise.example.com/api/sync").resolve(location));
	}

	@Test
	public void addresses()
	{
		assertNull(url(""));
		assertNull(url("   "));
		assertNull(url(null));
		assertEquals("https://ironwise.example.com/api/sync", url("ironwise.example.com"));
		assertEquals("https://ironwise.vercel.app/api/sync", url(" https://ironwise.vercel.app/ "));
		assertEquals("http://localhost:3000/api/sync", url("http://localhost:3000"));
		assertEquals("http://127.0.0.1:3000/api/sync", url("http://127.0.0.1:3000/"));
		assertEquals("http://[::1]:3000/api/sync", url("http://[::1]:3000"));
		// Tokens never go over plain HTTP to another computer.
		assertNull(url("http://ironwise.example.com"));
		assertNull(url("ftp://ironwise.example.com"));
	}

	@Test
	public void defaultAddressIsUsable()
	{
		assertEquals("https://ironwise-eight.vercel.app/api/sync", url(IronwiseConfig.DEFAULT_ADDRESS));
	}

	@Test
	public void redirectsAreNotFollowed()
	{
		// The token must only go to the address the player set.
		assertFalse(client.http.followRedirects());
		assertFalse(client.http.followSslRedirects());
	}

	@Test
	public void answersFromIronwise()
	{
		assertEquals(SyncClient.Outcome.OK, answer(200, "{\"ok\":true,\"rsn\":\"Iron Example\",\"receivedAt\":1}").outcome);
		SyncClient.Result denied = answer(401, "{\"ok\":false,\"error\":\"unauthorized\",\"message\":\"Unknown token.\"}");
		assertEquals(SyncClient.Outcome.UNAUTHORIZED, denied.outcome);
		assertEquals("Unknown token.", denied.message);
		SyncClient.Result forbidden = answer(403, "{\"ok\":false}");
		assertEquals(SyncClient.Outcome.UNAUTHORIZED, forbidden.outcome);
		assertEquals(SyncClient.BAD_TOKEN, forbidden.message);
		SyncClient.Result version = answer(400, "{\"ok\":false,\"message\":\"Unsupported sync version\"}");
		assertEquals(SyncClient.Outcome.REJECTED, version.outcome);
		assertEquals("Unsupported sync version", version.message);
		SyncClient.Result big = answer(413, "{\"ok\":false,\"error\":\"too_large\",\"message\":\"Sync is too large.\"}");
		assertEquals(SyncClient.Outcome.REJECTED, big.outcome);
		assertEquals("Sync is too large.", big.message);
		SyncClient.Result busy = answer(503, "{\"ok\":false,\"message\":\"Couldn't save the sync on the server.\"}");
		assertEquals(SyncClient.Outcome.RETRY, busy.outcome);
		assertEquals("Couldn't save the sync on the server.", busy.message);
	}

	@Test
	public void theGuideStepComesWithASavedSync()
	{
		SyncClient.Result without = answer(200, "{\"ok\":true,\"rsn\":\"Iron Example\",\"receivedAt\":1}");
		assertEquals(SyncClient.Outcome.OK, without.outcome);
		assertSame(NextStep.Reply.NOTHING, without.guide);

		SyncClient.Result with = answer(200, "{\"ok\":true,\"rsn\":\"Iron Example\",\"receivedAt\":1,\"guide\":" + NextStepTest.stepJson() + "}");
		assertEquals(SyncClient.Outcome.OK, with.outcome);
		assertTrue(with.guide.said);
		assertEquals("0123456789abcdef", with.guide.step.stepId);

		// A step the plugin can't read never makes the sync fail.
		SyncClient.Result garbled = answer(200, "{\"ok\":true,\"guide\":{\"n\":\"twelve\"}}");
		assertEquals(SyncClient.Outcome.OK, garbled.outcome);
		assertTrue(garbled.guide.said);
		assertNull(garbled.guide.step);

		// Only a saved sync carries a step.
		assertSame(NextStep.Reply.NOTHING, answer(400, "{\"ok\":false,\"guide\":" + NextStepTest.stepJson() + "}").guide);
	}

	@Test
	public void successOnlyCountsFromIronwise()
	{
		for (String body : new String[]{"<html><body>Welcome</body></html>", "", "{}", "{\"status\":\"ok\"}", "[1,2]", "ok"})
		{
			SyncClient.Result r = answer(200, body);
			assertEquals(body, SyncClient.Outcome.WRONG_ADDRESS, r.outcome);
			assertEquals(body, SyncClient.NOT_IRONWISE, r.message);
		}
		SyncClient.Result notOk = answer(200, "{\"ok\":false}");
		assertEquals(SyncClient.Outcome.WRONG_ADDRESS, notOk.outcome);
		assertEquals(SyncClient.NOT_IRONWISE, notOk.message);
		assertEquals(SyncClient.Outcome.WRONG_ADDRESS, answer(204, "").outcome);
	}

	@Test
	public void aLoginPageIsNotABadToken()
	{
		for (int code : new int[]{401, 403})
		{
			for (String body : new String[]{"<html>Authentication Required</html>", "", "{\"error\":\"forbidden\"}"})
			{
				SyncClient.Result r = answer(code, body);
				assertEquals(code + " " + body, SyncClient.Outcome.WRONG_ADDRESS, r.outcome);
				assertEquals(code + " " + body, SyncClient.LOGIN, r.message);
			}
		}
	}

	@Test
	public void otherAnswers()
	{
		SyncClient.Result missing = answer(404, "<html>Not found</html>");
		assertEquals(SyncClient.Outcome.REJECTED, missing.outcome);
		assertEquals(SyncClient.NO_APP, missing.message);
		SyncClient.Result big = answer(413, "Request Entity Too Large");
		assertEquals(SyncClient.Outcome.REJECTED, big.outcome);
		assertEquals(SyncClient.TOO_BIG, big.message);
		assertEquals("the app answered 400", answer(400, "<html>").message);
		assertEquals(SyncClient.Outcome.RETRY, answer(503, "oops").outcome);
		assertEquals("the app answered 502", answer(502, "").message);
		assertEquals(SyncClient.Outcome.RETRY, answer(429, "").outcome);
	}

	@Test
	public void redirectsSayWhere()
	{
		// Another sync address (www., a different domain): that's the one to use.
		SyncClient.Result www = redirect(308, "https://www.ironwise.example.com/api/sync");
		assertEquals(SyncClient.Outcome.WRONG_ADDRESS, www.outcome);
		assertEquals("that address redirects to https://www.ironwise.example.com; use that address instead.", www.message);
		assertEquals("that address redirects to https://ironwise.example.com/app; use that address instead.",
			redirect(301, "/app/api/sync").message);
		// A login page (e.g. a Vercel deployment URL behind Vercel's login).
		SyncClient.Result login = redirect(307, "https://vercel.com/sso-api?url=https%3A%2F%2Fironwise-abc.vercel.app%2Fapi%2Fsync");
		assertEquals(SyncClient.Outcome.WRONG_ADDRESS, login.outcome);
		assertEquals("that address redirects to vercel.com, which isn't the Ironwise app. If it's a Vercel deployment URL, use the app's main address.", login.message);
		assertEquals("that address redirects to ironwise.example.com, which isn't the Ironwise app. If it's a Vercel deployment URL, use the app's main address.",
			redirect(302, "/login?next=%2Fapi%2Fsync").message);
		// A redirect to plain HTTP is never suggested: tokens don't go over HTTP.
		assertEquals("that address redirects to insecure.example.com, which isn't the Ironwise app. If it's a Vercel deployment URL, use the app's main address.",
			redirect(302, "http://insecure.example.com/api/sync").message);
		// No Location header.
		SyncClient.Result nowhere = client.result(302, "", null);
		assertEquals(SyncClient.Outcome.WRONG_ADDRESS, nowhere.outcome);
		assertEquals("that address redirects somewhere else. Use the app's main address.", nowhere.message);
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Test;

/** The JSON the plugin posts, as RuneLite's own Gson writes it. Made-up data only. */
public class SyncPayloadTest
{
	/** The Gson RuneLite injects into plugins. */
	private static final Gson GSON = RuneLiteAPI.GSON;

	private static SyncPayload payload()
	{
		SyncPayload p = new SyncPayload();
		p.plugin = IronwisePlugin.VERSION;
		p.sentAt = 1790243320266L;
		p.account = new SyncPayload.Account("1234567890123456789", "Iron Example", 302);
		p.skills = Collections.emptyMap();
		p.containers = Collections.emptyMap();
		p.varbits = Collections.emptyMap();
		p.varps = Collections.emptyMap();
		p.saved = Collections.emptyMap();
		return p;
	}

	@Test
	public void noCollectionLogKeyUntilSomethingIsKnown()
	{
		JsonObject json = new JsonParser().parse(GSON.toJson(payload())).getAsJsonObject();
		assertFalse(json.has("collectionLog"));
		assertEquals(1, json.get("v").getAsInt());
		assertEquals(IronwisePlugin.VERSION, json.get("plugin").getAsString());
	}

	@Test
	public void collectionLogShape()
	{
		CollectionLogState state = new CollectionLogState();
		state.searchSeen(Collections.singletonMap(22006, 1), 1000);
		state.pageSeen("Vorkath", Collections.singletonMap("Vorkath kills", 61), Arrays.asList(11286, 22006),
			Collections.singletonMap(11286, 2), 2000);
		state.added("Vorkath's head", 3000);
		SyncPayload p = payload();
		p.collectionLog = state.toPayload();

		JsonObject log = new JsonParser().parse(GSON.toJson(p)).getAsJsonObject().getAsJsonObject("collectionLog");
		assertEquals("{\"seenAt\":1000,\"items\":[[22006,1]]}", log.get("all").toString());
		assertEquals("{\"Vorkath\":{\"seenAt\":2000,\"kc\":[[\"Vorkath kills\",61]],\"items\":[[11286,2],[22006,1]]}}", log.get("pages").toString());
		assertEquals("[[\"Vorkath's head\",3000]]", log.get("added").toString());
	}

	@Test
	public void pagesAndAddedArePresentWhenOnlyOneIsKnown()
	{
		CollectionLogState state = new CollectionLogState();
		state.added("Vorkath's head", 3000);
		SyncPayload p = payload();
		p.collectionLog = state.toPayload();

		JsonObject log = new JsonParser().parse(GSON.toJson(p)).getAsJsonObject().getAsJsonObject("collectionLog");
		assertFalse(log.has("all"));
		assertEquals("{}", log.get("pages").toString());
		JsonArray added = log.getAsJsonArray("added");
		assertEquals(1, added.size());
	}

	@Test
	public void trackedVarsIncludeSpellbookAndCombatAchievements()
	{
		Set<Integer> varbits = new HashSet<>();
		for (int id : TrackedVars.VARBITS)
		{
			assertTrue("duplicate varbit " + id, varbits.add(id));
		}
		Set<Integer> varps = new HashSet<>();
		for (int id : TrackedVars.VARPS)
		{
			assertTrue("duplicate varp " + id, varps.add(id));
		}
		assertEquals(4070, VarbitID.SPELLBOOK);
		assertTrue(varbits.contains(VarbitID.SPELLBOOK));
		int[] ca = {
			VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1, VarPlayerID.CA_TASK_COMPLETED_2,
			VarPlayerID.CA_TASK_COMPLETED_3, VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
			VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7, VarPlayerID.CA_TASK_COMPLETED_8,
			VarPlayerID.CA_TASK_COMPLETED_9, VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
			VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13, VarPlayerID.CA_TASK_COMPLETED_14,
			VarPlayerID.CA_TASK_COMPLETED_15, VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
			VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19, VarPlayerID.CA_TASK_COMPLETED_20,
		};
		for (int id : ca)
		{
			assertTrue("missing CA varp " + id, varps.contains(id));
		}
		// The ids the app expects (RuneLite gameval, runelite-parent-1.12.39).
		assertEquals(3116, VarPlayerID.CA_TASK_COMPLETED_0);
		assertEquals(3128, VarPlayerID.CA_TASK_COMPLETED_12);
		assertEquals(3387, VarPlayerID.CA_TASK_COMPLETED_13);
		assertEquals(5673, VarPlayerID.CA_TASK_COMPLETED_20);
	}
}

package com.ironwise;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/** When readings can be trusted, as RuneLite's Time Tracking decides (TimeTrackingPlugin, FarmingTracker, BirdHouseTracker). */
public class TickGateTest
{
	private static final int CATHERBY = 11062;

	@Test
	public void theWelcomeScreenAndTheTickAfterItAreNeverRead()
	{
		TickGate g = new TickGate();
		assertFalse(g.readable(true, false, CATHERBY));
		assertFalse(g.readable(true, false, CATHERBY));
		assertFalse(g.readable(false, false, CATHERBY)); // the tick it closes on
		assertFalse(g.readable(false, false, CATHERBY)); // the first tick only records the region
		assertTrue(g.readable(false, false, CATHERBY));
	}

	@Test
	public void aTickInAnotherRegionThanTheTickBeforeIsNotRead()
	{
		TickGate g = new TickGate();
		g.readable(false, false, 12083);
		assertTrue(g.readable(false, false, 12083));
		assertFalse(g.readable(false, false, CATHERBY)); // just teleported
		assertTrue(g.readable(false, false, CATHERBY));
	}

	@Test
	public void notWhileAModalInterfaceIsOpen()
	{
		TickGate g = new TickGate();
		g.readable(false, false, CATHERBY);
		assertFalse(g.readable(false, true, CATHERBY));
		assertTrue(g.readable(false, false, CATHERBY));
	}

	@Test
	public void aHopOrLoadingScreenStartsAgain()
	{
		TickGate g = new TickGate();
		g.readable(false, false, CATHERBY);
		assertTrue(g.readable(false, false, CATHERBY));
		g.reset();
		assertFalse(g.readable(false, false, CATHERBY));
		assertTrue(g.readable(false, false, CATHERBY));
	}

	@Test
	public void birdHousesDroppingToZeroTogetherAreNotRead()
	{
		TickGate g = new TickGate();
		assertTrue(g.housesReadable(new int[]{21, 21, 21, 3}));
		// Arriving on Fossil Island: the varps read 0 for a moment. More than two drops at once: ignored, and kept out.
		assertFalse(g.housesReadable(new int[]{0, 0, 0, 3}));
		assertTrue(g.housesReadable(new int[]{21, 21, 21, 3}));
		// Dismantling one house is a real drop.
		assertTrue(g.housesReadable(new int[]{0, 21, 21, 3}));
		assertEquals(true, g.housesReadable(new int[]{0, 0, 0, 3})); // two more: still at most two against the last
	}
}
